INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-shi', 'HSK 1', 0, 'CÂU CHỮ 是 (A LÀ B)', '是', 'ba', 'Câu chữ 是 (a là b) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["是","key"],["Danh ngữ"]]', '["Bẫy người Việt: ","QUÊN ĐỘNG TỪ 是 HOẶC THAY BẰNG LÀ, CÂU A LÀ B BẮT BUỘC CÓ 是 GIỮA CHỦ NGỮ VÀ DANH NGỮ"," , không bỏ được như tiếng Việt."]', '[{"hz":"我是学生。","py":"wǒ shì xuésheng.","vi":"Tôi là học sinh."},{"hz":"她是我妈妈。","py":"tā shì wǒ māma.","vi":"Cô ấy là mẹ tôi."},{"hz":"你是老师吗?","py":"nǐ shì lǎoshī ma?","vi":"Bạn là giáo viên à?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-ma', 'HSK 1', 1, 'CÂU HỎI CÓ KHÔNG VỚI 吗', '吗', 'bongu', 'Câu hỏi có không với 吗 — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["Vị ngữ"],["吗","key"]]', '["Bẫy người Việt: ","DÙNG THÊM DANH TỪ NGHI VẤN KHI ĐÃ CÓ 吗"," ở cuối câu\u003b một câu chỉ cần một cách hỏi là đủ."]', '[{"hz":"你好吗?","py":"nǐ hǎo ma?","vi":"Bạn có khỏe không?"},{"hz":"他是中国人吗?","py":"tā shì Zhōngguó rén ma?","vi":"Anh ấy là người Trung Quốc à?"},{"hz":"你喝咖啡吗?","py":"nǐ hē kāfēi ma?","vi":"Bạn có uống cà phê không?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-shen-me', 'HSK 1', 2, 'CÂU HỎI VỚI 什么 (CÁI GÌ)', '什么', 'hutu', 'Câu hỏi với 什么 (cái gì) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["Động từ"],["什么","key"]]', '["Bẫy người Việt: ","ĐẶT 什么 Ở ĐẦU CÂU NHƯ TỪ WHAT"," \u003b trong tiếng Trung 什么 đứng ở vị trí của tân ngữ, sau động từ."]', '[{"hz":"这是什么?","py":"zhè shì shénme?","vi":"Đây là cái gì?"},{"hz":"你吃什么?","py":"nǐ chī shénme?","vi":"Bạn ăn gì?"},{"hz":"你叫什么名字?","py":"nǐ jiào shénme míngzi?","vi":"Bạn tên là gì?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-na', 'HSK 1', 3, 'CÂU HỎI VỚI 哪 (NÀO, ĐÂU)', '哪', 'hutu', 'Câu hỏi với 哪 (nào, đâu) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["Vị ngữ"],["哪","key"]]', '["Bẫy người Việt: ","NHẦM 哪 (NÀO) VỚI 那 (ĐÓ)"," \u003b hai chữ gần giống nhau nhưng 哪 dùng để hỏi, 那 dùng để chỉ."]', '[{"hz":"你去哪儿?","py":"nǐ qù nǎr?","vi":"Bạn đi đâu?"},{"hz":"你是哪国人?","py":"nǐ shì nǎ guó rén?","vi":"Bạn là người nước nào?"},{"hz":"哪个是你的?","py":"nǎge shì nǐ de?","vi":"Cái nào là của bạn?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-shui', 'HSK 1', 4, 'CÂU HỎI VỚI 谁 (AI)', '谁', 'hutu', 'Câu hỏi với 谁 (ai) — điểm ngữ pháp HSK 1.', '[["谁","key"],["Động từ"],["Tân ngữ"]]', '["Bẫy người Việt: ","ĐỌC 谁 THÀNH SHUÍ KHI NÓI NHANH"," \u003b trong khẩu ngữ 通常 đọc là shéi, hai cách đọc đều đúng."]', '[{"hz":"她是谁?","py":"tā shì shéi?","vi":"Cô ấy là ai?"},{"hz":"谁是你的中文老师?","py":"shéi shì nǐ de Zhōngwén lǎoshī?","vi":"Ai là giáo viên tiếng Trung của bạn?"},{"hz":"你等谁?","py":"nǐ děng shéi?","vi":"Bạn đợi ai?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-ji', 'HSK 1', 5, 'CÂU HỎI VỚI 几 (MẤY)', '几', 'hutu', 'Câu hỏi với 几 (mấy) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["几","key"],["Lượng từ + Danh từ"]]', '["Bẫy người Việt: ","DÙNG 几 CHO SỐ LỌN TRÊN MƯỜI"," \u003b 几 chỉ hỏi số nhỏ thường dưới 10, số lớn phải dùng 多少."]', '[{"hz":"你家有几口人?","py":"nǐ jiā yǒu jǐ kǒu rén?","vi":"Nhà bạn có mấy người?"},{"hz":"现在几点?","py":"xiànzài jǐ diǎn?","vi":"Bây giờ là mấy giờ?"},{"hz":"你有几个弟弟?","py":"nǐ yǒu jǐge dìdi?","vi":"Bạn có mấy người em trai?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-duo-shao', 'HSK 1', 6, 'CÂU HỎI VỚI 多少 (BAO NHIÊU)', '多少', 'hutu', 'Câu hỏi với 多少 (bao nhiêu) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["Động từ"],["多少","key"],["Danh từ"]]', '["Bẫy người Việt: ","THÊM LƯỢNG TỪ SAU 多少 MỘT CÁCH TÙY TIỆN"," \u003b 多少 đứng trước danh từ hoặc thay cả cụm số-lượng, không chia nhỏ được."]', '[{"hz":"这个多少钱?","py":"zhège duōshao qián?","vi":"Cái này bao nhiêu tiền?"},{"hz":"你有多少本书?","py":"nǐ yǒu duōshao běn shū?","vi":"Bạn có bao nhiêu cuốn sách?"},{"hz":"你们班有多少学生?","py":"nǐmen bān yǒu duōshao xuésheng?","vi":"Lớp các bạn có bao nhiêu học sinh?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-duo-da', 'HSK 1', 7, 'CÂU HỎI TUỔI VỚI 多大', '多大', 'hutu', 'Câu hỏi tuổi với 多大 — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["多大","key"]]', '["Bẫy người Việt: ","HỎI TUỔI NGƯỜI LỚN BẰNG 你几岁"," \u003b 几岁 chỉ dùng cho trẻ nhỏ, với người lớn nên hỏi 你多大."]', '[{"hz":"你多大?","py":"nǐ duō dà?","vi":"Bạn bao nhiêu tuổi?"},{"hz":"你儿子多大?","py":"nǐ érzi duō dà?","vi":"Con trai bạn bao nhiêu tuổi?"},{"hz":"你的狗多大?","py":"nǐ de gǒu duō dà?","vi":"Chú chó của bạn mấy tuổi?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-zen-me', 'HSK 1', 8, 'CÂU HỎI CÁCH THỨC VỚI 怎么', '怎么', 'hutu', 'Câu hỏi cách thức với 怎么 — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["怎么","key"],["Động từ"]]', '["Bẫy người Việt: ","ĐẶT 怎么 Ở CUỐI CÂU NHƯ TỪ THẾ NÀO"," \u003b trong tiếng Trung 怎么 phải đứng trước động từ."]', '[{"hz":"这个怎么说?","py":"zhège zěnme shuō?","vi":"Cái này nói thế nào?"},{"hz":"这个字怎么写?","py":"zhège zì zěnme xiě?","vi":"Chữ này viết thế nào?"},{"hz":"你怎么去学校?","py":"nǐ zěnme qù xuéxiào?","vi":"Bạn đi trường bằng cách nào?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-zen-me-yang', 'HSK 1', 9, 'CÂU HỎI ĐÁNH GIÁ VỚI 怎么样', '怎么样', 'hutu', 'Câu hỏi đánh giá với 怎么样 — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["怎么样","key"]]', '["Bẫy người Việt: ","TÁCH 怎么样 THÀNH 怎么 + 什么"," \u003b 怎么样 là một từ hỏi hoàn chỉnh nghĩa là ra sao, không tách được."]', '[{"hz":"今天天气怎么样?","py":"jīntiān tiānqì zěnmeyàng?","vi":"Hôm nay thời tiết thế nào?"},{"hz":"这个菜怎么样?","py":"zhège cài zěnmeyàng?","vi":"Món này ăn thế nào?"},{"hz":"你的汉语怎么样?","py":"nǐ de Hànyǔ zěnmeyàng?","vi":"Tiếng Trung của bạn thế nào rồi?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-ne', 'HSK 1', 10, 'CÂU HỎI TÓM TẮT VỚI 呢', '呢', 'bongu', 'Câu hỏi tóm tắt với 呢 — điểm ngữ pháp HSK 1.', '[["Ngữ đã biết"],["Chủ ngữ"],["呢","key"]]', '["Bẫy người Việt: ","DÙNG 呢 KHI CHƯA CÓ NGỮ CẢNH TRƯỚC ĐÓ"," \u003b 呢 chỉ lặp lại câu hỏi đã nói, không mở đầu câu hỏi mới được."]', '[{"hz":"我很好,你呢?","py":"wǒ hěn hǎo, nǐ ne?","vi":"Tôi khỏe, còn bạn thì sao?"},{"hz":"他去学校,你呢?","py":"tā qù xuéxiào, nǐ ne?","vi":"Anh ấy đi trường, còn bạn?"},{"hz":"我喝咖啡,你呢?","py":"wǒ hē kāfēi, nǐ ne?","vi":"Tôi uống cà phê, còn bạn?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-ba', 'HSK 1', 11, 'CÂU ĐỀ NGHỊ VỚI 吧', '吧', 'bongu', 'Câu đề nghị với 吧 — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["Vị ngữ"],["吧","key"]]', '["Bẫy người Việt: ","DÙNG 吧 Ở CÂU HỎI CÓ KHÔNG"," \u003b 吞 chú ý 吧 dùng cho đề nghị hoặc phỏng đoán, câu hỏi Có không phải dùng 吗."]', '[{"hz":"我们去学校吧!","py":"wǒmen qù xuéxiào ba!","vi":"Chúng ta đi trường thôi!"},{"hz":"我们喝水吧。","py":"wǒmen hē shuǐ ba.","vi":"Chúng ta uống nước nhé."},{"hz":"他是学生吧?","py":"tā shì xuésheng ba?","vi":"Anh ấy là học sinh chứ?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-hao-ma', 'HSK 1', 12, 'CÂU MỜI KÈM 好吗', '好吗', 'bongu', 'Câu mời kèm 好吗 — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["Vị ngữ"],[",好吗","key"]]', '["Bẫy người Việt: ","ĐẶT 好吗 Ở ĐẦU CÂU"," \u003b 好吗 luôn đứng cuối câu như một câu hỏi đuôi mang tính mời mọc."]', '[{"hz":"我们去学校,好吗?","py":"wǒmen qù xuéxiào, hǎo ma?","vi":"Chúng ta đi trường nhé?"},{"hz":"你吃苹果,好吗?","py":"nǐ chī píngguǒ, hǎo ma?","vi":"Bạn ăn táo nhé?"},{"hz":"我们看电视,好吗?","py":"wǒmen kàn diànshì, hǎo ma?","vi":"Chúng ta xem tivi nhé?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-bu', 'HSK 1', 13, 'PHỦ ĐỊNH VỚI 不', '不', 'hutu', 'Phủ định với 不 — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["不","key"],["Động từ / Tính từ"]]', '["Bẫy người Việt: ","DÙNG 不 ĐỂ PHỦ ĐỊNH ĐỘNG TỪ 有"," \u003b 有 luôn bị phủ định bằng 没, không bao giờ nói 不有."]', '[{"hz":"我不是学生。","py":"wǒ bú shì xuésheng.","vi":"Tôi không phải là học sinh."},{"hz":"他不喝咖啡。","py":"tā bù hē kāfēi.","vi":"Anh ấy không uống cà phê."},{"hz":"我不忙。","py":"wǒ bù máng.","vi":"Tôi không bận."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-mei', 'HSK 1', 14, 'PHỦ ĐỊNH VỚI 没(有)', '没', 'hutu', 'Phủ định với 没(有) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["没","key"],["Động từ"]]', '["Bẫy người Việt: ","DÙNG 没 CHO THÓI QUEN Ở HIỆN TẠI"," \u003b 没 chỉ phủ định sự sở hữu và hành động đã xảy ra, thói quen phải dùng 不."]', '[{"hz":"我没有弟弟。","py":"wǒ méiyǒu dìdi.","vi":"Tôi không có em trai."},{"hz":"他没来。","py":"tā méi lái.","vi":"Anh ấy đã không đến."},{"hz":"我没去学校。","py":"wǒ méi qù xuéxiào.","vi":"Tôi đã không đi trường."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-dou', 'HSK 1', 15, 'PHÓ TỪ 都 (ĐỀU)', '都', 'hutu', 'Phó từ 都 (đều) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ (số nhiều)"],["都","key"],["Vị ngữ"]]', '["Bẫy người Việt: ","ĐẶT 都 TRƯỚC CHỦ NGỮ HOẶC SAU ĐỘNG TỪ"," \u003b 都 luôn đứng ngay sau chủ ngữ, trước động từ và tính từ."]', '[{"hz":"我们都是学生。","py":"wǒmen dōu shì xuésheng.","vi":"Chúng tôi đều là học sinh."},{"hz":"他们都喝咖啡。","py":"tāmen dōu hē kāfēi.","vi":"Họ đều uống cà phê."},{"hz":"苹果和香蕉都很好吃。","py":"píngguǒ hé xiāngjiāo dōu hěn hǎochī.","vi":"Táo và chuối đều rất ngon."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-ye', 'HSK 1', 16, 'PHÓ TỪ 也 (CŨNG)', '也', 'hutu', 'Phó từ 也 (cũng) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["也","key"],["Vị ngữ"]]', '["Bẫy người Việt: ","DÙNG 也 TRONG CÂU PHỦ ĐỊNH CÓ 不 và 没 SAI VỊ TRÍ"," \u003b thứ tự đúng là 主语 + 不/没 + 也, ví dụ 他也不是学生."]', '[{"hz":"他也是老师。","py":"tā yě shì lǎoshī.","vi":"Anh ấy cũng là giáo viên."},{"hz":"我也爱中国菜。","py":"wǒ yě ài Zhōngguó cài.","vi":"Tôi cũng thích món Trung Quốc."},{"hz":"他也不是学生。","py":"tā yě bú shì xuésheng.","vi":"Anh ấy cũng không phải học sinh."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-hen', 'HSK 1', 17, 'PHÓ TỪ TRÌNH ĐỘ 很', '很', 'hutu', 'Phó từ trình độ 很 — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["很","key"],["Tính từ"]]', '["Bẫy người Việt: ","DỊCH 很 LÀ RẤT TRONG MỌI CÂU"," \u003b ở câu vị ngữ tính từ, 很 chỉ giữ nhịp câu, nghĩa RẤT yếu đi, muốn nhấn mạnh phải đọc nhấn."]', '[{"hz":"我很高兴。","py":"wǒ hěn gāoxìng.","vi":"Tôi rất vui."},{"hz":"她很漂亮。","py":"tā hěn piàoliang.","vi":"Cô ấy đẹp."},{"hz":"学校很大。","py":"xuéxiào hěn dà.","vi":"Trường rất lớn."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-tai-le', 'HSK 1', 18, 'CẤU TRÚC 太…了', '太了', 'hutu', 'Cấu trúc 太…了 — điểm ngữ pháp HSK 1.', '[["太","key"],["Tính từ"],["了","key"]]', '["Bẫy người Việt: ","QUÊN 了 Ở CUỐI CẤU TRÚC 太…了"," \u003b 太 luôn đi cặp với 了 ở cuối câu, thiếu một trong hai là sai ngữ pháp."]', '[{"hz":"太好了!","py":"tài hǎo le!","vi":"Tốt quá!"},{"hz":"你太忙了!","py":"nǐ tài máng le!","vi":"Bạn bận quá!"},{"hz":"这个菜太好吃了!","py":"zhège cài tài hǎochī le!","vi":"Món này ngon quá!"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-hui', 'HSK 1', 19, 'ĐỘNG TỪ TRÌNH THỌC 会 (BIẾT LÀM)', '会', 'hutu', 'Động từ trình thọc 会 (biết làm) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["会","key"],["Động từ"]]', '["Bẫy người Việt: ","DÙNG 会 KHI NÓI VỀ SỰ CHO PHÉP"," \u003b 会 diễn tả khả năng học được, sự cho phép phải dùng 能 hoặc 可以."]', '[{"hz":"我会说汉语。","py":"wǒ huì shuō Hànyǔ.","vi":"Tôi biết nói tiếng Trung."},{"hz":"他会打电话。","py":"tā huì dǎ diànhuà.","vi":"Anh ấy biết gọi điện thoại."},{"hz":"你会写汉字吗?","py":"nǐ huì xiě Hànzì ma?","vi":"Bạn biết viết chữ Trung không?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-neng', 'HSK 1', 20, 'ĐỘNG TỪ TRÌNH THỌC 能 (CÓ THỂ)', '能', 'hutu', 'Động từ trình thọc 能 (có thể) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["能","key"],["Động từ"]]', '["Bẫy người Việt: ","PHỦ ĐỊNH 能 BẰNG 不会"," \u003b không được phép hay không thể làm phải phủ định bằng 不能."]', '[{"hz":"我能坐这儿吗?","py":"wǒ néng zuò zhèr ma?","vi":"Tôi có thể ngồi đây không?"},{"hz":"你能来吗?","py":"nǐ néng lái ma?","vi":"Bạn có thể đến được không?"},{"hz":"今天我不能去学校。","py":"jīntiān wǒ bù néng qù xuéxiào.","vi":"Hôm nay tôi không thể đi trường."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-xiang', 'HSK 1', 21, 'ĐỘNG TỪ TRÌNH THỌC 想 (MUỐN)', '想', 'hutu', 'Động từ trình thọc 想 (muốn) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["想","key"],["Động từ / Danh từ"]]', '["Bẫy người Việt: ","NHẦM 想 (MUỐN, NHỚ) VỚI 要 (SẼ, CẦN)"," \u003b 想 nói mong muốn nhẹ nhàng, 要 mang tính quyết định hoặc yêu cầu."]', '[{"hz":"我想喝水。","py":"wǒ xiǎng hē shuǐ.","vi":"Tôi muốn uống nước."},{"hz":"我想妈妈。","py":"wǒ xiǎng māma.","vi":"Tôi nhớ mẹ."},{"hz":"你想吃什么?","py":"nǐ xiǎng chī shénme?","vi":"Bạn muốn ăn gì?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-yao', 'HSK 1', 22, 'ĐỘNG TỪ TRÌNH THỌC 要 (MUỐN, SẼ)', '要', 'hutu', 'Động từ trình thọc 要 (muốn, sẽ) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["要","key"],["Danh từ / Động từ"]]', '["Bẫy người Việt: ","DÙNG 要 TRƯỚC ĐỘNG TỪ DIỄN TẢ KHA NĂNG"," \u003b 要 nói về mong muốn và dự định, khả năng phải dùng 会 hoặc 能."]', '[{"hz":"我要一个苹果。","py":"wǒ yào yíge píngguǒ.","vi":"Tôi muốn một quả táo."},{"hz":"他要咖啡。","py":"tā yào kāfēi.","vi":"Anh ấy muốn cà phê."},{"hz":"明天我要去学校。","py":"míngtiān wǒ yào qù xuéxiào.","vi":"Ngày mai tôi sẽ đi trường."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-zai', 'HSK 1', 23, 'CÂU CHỮ 在 (Ở ĐÂU)', '在', 'ba', 'Câu chữ 在 (ở đâu) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["在","key"],["Địa điểm"]]', '["Bẫy người Việt: ","QUÊN 在 KHI NÓI NƠI Ở"," \u003b câu ai ở đâu bắt buộc phải có 在 trước địa điểm, không nối bằng 是."]', '[{"hz":"我在学校。","py":"wǒ zài xuéxiào.","vi":"Tôi ở trường."},{"hz":"他在家。","py":"tā zài jiā.","vi":"Anh ấy ở nhà."},{"hz":"爸爸在商店。","py":"bàba zài shāngdiàn.","vi":"Bố ở cửa hàng."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-zheng-zai', 'HSK 1', 24, 'CẤU TRÚC 正在 (ĐANG)', '正在', 'hutu', 'Cấu trúc 正在 (đang) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["正在","key"],["Động từ"]]', '["Bẫy người Việt: ","ĐẶT 正在 SAU ĐỘNG TỪ"," \u003b 正在 là phó từ nên phải đứng trước động từ diễn tả hành động đang diễn ra."]', '[{"hz":"他正在吃饭。","py":"tā zhèngzài chī fàn.","vi":"Anh ấy đang ăn cơm."},{"hz":"我们正在学汉语。","py":"wǒmen zhèngzài xué Hànyǔ.","vi":"Chúng tôi đang học tiếng Trung."},{"hz":"妈妈正在看电视。","py":"māma zhèngzài kàn diànshì.","vi":"Mẹ đang xem tivi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-zai-+-V-P', 'HSK 1', 25, '在 + ĐỊA ĐIỂM + ĐỘNG TỪ', '在+VP', 'ba', '在 + địa điểm + động từ — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["在","key"],["Địa điểm"],["Động từ"]]', '["Bẫy người Việt: ","ĐẶT ĐỊA ĐIỂM SAU ĐỘNG TỪ NHƯ TIẾNG VIỆT"," \u003b trong tiếng Trung địa điểm đứng trước động từ qua 在."]', '[{"hz":"我在家吃饭。","py":"wǒ zài jiā chī fàn.","vi":"Tôi ăn cơm ở nhà."},{"hz":"他在学校学中文。","py":"tā zài xuéxiào xué Zhōngwén.","vi":"Anh ấy học tiếng Trung ở trường."},{"hz":"我们在商店买苹果。","py":"wǒmen zài shāngdiàn mǎi píngguǒ.","vi":"Chúng tôi mua táo ở cửa hàng."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-you', 'HSK 1', 26, 'CÂU CHỮ 有 (CÓ, SỞ HỮU)', '有', 'ba', 'Câu chữ 有 (có, sở hữu) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["有","key"],["Danh ngữ"]]', '["Bẫy người Việt: ","NỐI NGƯỜI SỞ HỮU BẰNG 是"," \u003b diễn tả sở hữu phải dùng 有, 是 chỉ dùng để định danh A là B."]', '[{"hz":"我有一个弟弟。","py":"wǒ yǒu yíge dìdi.","vi":"Tôi có một người em trai."},{"hz":"你家有电脑吗?","py":"nǐ jiā yǒu diànnǎo ma?","vi":"Nhà bạn có máy tính không?"},{"hz":"桌子上有一本书。","py":"zhuōzi shang yǒu yì běn shū.","vi":"Trên bàn có một cuốn sách."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-le', 'HSK 1', 27, 'TRỢ ĐỘNG TỪ 了 (HÀNH ĐỘNG XONG)', '了', 'bongu', 'Trợ động từ 了 (hành động xong) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["Động từ + 了","key"],["Tân ngữ"]]', '["Bẫy người Việt: ","DÙNG 了 VỚI HÀNH ĐỘNG THƯỜNG NGÀY"," \u003b 了 chỉ gắn với hành động đã hoàn thành, thói quen hiện tại không dùng 了."]', '[{"hz":"我吃了一个苹果。","py":"wǒ chīle yíge píngguǒ.","vi":"Tôi đã ăn một quả táo."},{"hz":"我买了书。","py":"wǒ mǎile shū.","vi":"Tôi đã mua sách."},{"hz":"他喝了咖啡。","py":"tā hēle kāfēi.","vi":"Anh ấy đã uống cà phê."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-de', 'HSK 1', 28, 'CẤU TRÚC 的 (CỦA)', '的', 'bongu', 'Cấu trúc 的 (của) — điểm ngữ pháp HSK 1.', '[["Danh ngữ (người/vật)"],["的","key"],["Danh ngữ"]]', '["Bẫy người Việt: ","ĐẢO THỨ TỰ SỞ HỮU NHƯ TIẾNG VIỆT"," \u003b trong tiếng Trung người sở hữu đứng trước, 的 nối vào trước vật được sở hữu."]', '[{"hz":"这是我的书。","py":"zhè shì wǒ de shū.","vi":"Đây là sách của tôi."},{"hz":"这是爸爸的书。","py":"zhè shì bàba de shū.","vi":"Đây là sách của bố."},{"hz":"她是我们的老师。","py":"tā shì wǒmen de lǎoshī.","vi":"Cô ấy là giáo viên của chúng tôi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-ge', 'HSK 1', 29, 'LƯỢNG TỪ 个', '个', 'hutu', 'Lượng từ 个 — điểm ngữ pháp HSK 1.', '[["Số từ"],["个","key"],["Danh từ"]]', '["Bẫy người Việt: ","BỎ LƯỢNG TỪ KHI ĐẾM ĐỒ VẬT"," \u003b tiếng Trung bắt buộc có lượng từ giữa số từ và danh từ, 个 là lượng từ thông dụng nhất."]', '[{"hz":"我有两个朋友。","py":"wǒ yǒu liǎngge péngyou.","vi":"Tôi có hai người bạn."},{"hz":"一个苹果。","py":"yíge píngguǒ.","vi":"Một quả táo."},{"hz":"我们家有三个人。","py":"wǒmen jiā yǒu sānge rén.","vi":"Nhà tôi có ba người."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-ben', 'HSK 1', 30, 'LƯỢNG TỪ 本、张、只、口', '本', 'hutu', 'Lượng từ 本、张、只、口 — điểm ngữ pháp HSK 1.', '[["Số từ"],["Lượng từ","key"],["Danh từ"]]', '["Bẫy người Việt: ","DÙNG 个 CHO MỌI DANH TỪ"," \u003b sách đếm bằng 本, bàn ghế bằng 张, con vật bằng 只, nhân khẩu bằng 口, không thay thế tùy tiện."]', '[{"hz":"一本书。","py":"yì běn shū.","vi":"Một cuốn sách."},{"hz":"两只猫。","py":"liǎng zhǐ māo.","vi":"Hai con mèo."},{"hz":"我家有四口人。","py":"wǒ jiā yǒu sì kǒu rén.","vi":"Nhà tôi có bốn nhân khẩu."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-kuai', 'HSK 1', 31, 'NÓI GIÁ TIỀN VỚI 块', '块', 'hutu', 'Nói giá tiền với 块 — điểm ngữ pháp HSK 1.', '[["Danh từ"],["Số từ + 块","key"]]', '["Bẫy người Việt: ","BỎ QUẢ 块 HOẶC 钱 KHI NÓI GIÁ"," \u003b nói giá tiền cần đủ số từ và đơn vị, ví dụ 五块钱, không nói riêng lẻ."]', '[{"hz":"这个五块钱。","py":"zhège wǔ kuài qián.","vi":"Cái này năm tệ."},{"hz":"苹果三块钱。","py":"píngguǒ sān kuài qián.","vi":"Táo ba tệ."},{"hz":"一杯水两块。","py":"yì bēi shuǐ liǎng kuài.","vi":"Một cốc nước hai tệ."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-sui', 'HSK 1', 32, 'CÂU DANH TỪ VỊ NGỮ (TUỔI TĂC)', '岁', 'ba', 'Câu danh từ vị ngữ (tuổi tăc) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["Số từ + 岁","key"]]', '["Bẫy người Việt: ","THÊM 是 TRƯỚC SỐ TUỔI"," \u003b câu nói tuổi không cần động từ, số từ cộng 岁 đứng thẳng sau chủ ngữ."]', '[{"hz":"我二十岁。","py":"wǒ èrshí suì.","vi":"Tôi hai mươi tuổi."},{"hz":"我儿子五岁。","py":"wǒ érzi wǔ suì.","vi":"Con trai tôi năm tuổi."},{"hz":"我妹妹十八岁。","py":"wǒ mèimei shíbā suì.","vi":"Em gái tôi mười tám tuổi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-ban', 'HSK 1', 33, 'THỜI LƯỢNG VỚI 半 (RƯỠI)', '半', 'hutu', 'Thời lượng với 半 (rưỡi) — điểm ngữ pháp HSK 1.', '[["Số từ + 小时"],["半","key"]]', '["Bẫy người Việt: ","ĐẶT 半 TRƯỚC 小时 NHƯ MỘT RƯỠI TIẾNG"," \u003b nói rưỡi tiếng thì 半 đứng sau 小时, còn nửa tiếng là 半个小时."]', '[{"hz":"我睡了半个小时。","py":"wǒ shuìle bàn ge xiǎoshí.","vi":"Tôi đã ngủ nửa tiếng."},{"hz":"一个半小时。","py":"yíge bàn xiǎoshí.","vi":"Một tiếng rưỡi."},{"hz":"他学了半个小时汉语。","py":"tā xuéle bàn ge xiǎoshí Hànyǔ.","vi":"Anh ấy đã học nửa tiếng tiếng Trung."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-dian', 'HSK 1', 34, 'NÓI GIỜ VỚI 点、分', '点', 'hutu', 'Nói giờ với 点、分 — điểm ngữ pháp HSK 1.', '[["Số từ + 点","key"],["Số từ + 分"]]', '["Bẫy người Việt: ","ĐẢO THỨ TỰ GIỜ VÀ PHÚT"," \u003b tiếng Trung nói giờ trước rồi mới đến phút, hai giờ rưỡi là 两点半 không phải 半两."]', '[{"hz":"现在八点。","py":"xiànzài bā diǎn.","vi":"Bây giờ là tám giờ."},{"hz":"八点二十分。","py":"bā diǎn èrshí fēn.","vi":"Tám giờ hai mươi phút."},{"hz":"十点半。","py":"shí diǎn bàn.","vi":"Mười giờ rưỡi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-ming-tian', 'HSK 1', 35, 'TỪ NGỮ THỜI GIAN ĐỨNG ĐẦU CÂU', '明天', 'ba', 'Từ ngữ thời gian đứng đầu câu — điểm ngữ pháp HSK 1.', '[["Từ thời gian","key"],["Chủ ngữ"],["Vị ngữ"]]', '["Bẫy người Việt: ","ĐẶT TỪ THỜI GIAN SAU ĐỘNG TỪ"," \u003b từ chỉ thời gian phải đứng trước động từ, ngay sau chủ ngữ hoặc đầu câu."]', '[{"hz":"我明天去学校。","py":"wǒ míngtiān qù xuéxiào.","vi":"Ngày mai tôi đi trường."},{"hz":"今天我很忙。","py":"jīntiān wǒ hěn máng.","vi":"Hôm nay tôi rất bận."},{"hz":"星期天我在家。","py":"xīngqītiān wǒ zài jiā.","vi":"Chủ nhật tôi ở nhà."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-yue', 'HSK 1', 36, 'THỨ TỰ NĂM THÁNG NGÀY', '月', 'ba', 'Thứ tự năm tháng ngày — điểm ngữ pháp HSK 1.', '[["Năm"],["Tháng + 月","key"],["Ngày + 号"]]', '["Bẫy người Việt: ","NÓI NGÀY TRƯỚC THÁNG NHƯ TIẾNG VIỆT"," \u003b tiếng Trung xếp từ lớn đến nhỏ: năm trước, tháng sau, ngày cuối cùng."]', '[{"hz":"今天是十月二十三号。","py":"jīntiān shì shíyuè èrshísān hào.","vi":"Hôm nay là ngày hai mươi ba tháng mười."},{"hz":"我的生日是五月八号。","py":"wǒ de shēngrì shì wǔyuè bā hào.","vi":"Sinh nhật tôi là ngày mùng 8 tháng 5."},{"hz":"九月一号我上学。","py":"jiǔyuè yī hào wǒ shàngxué.","vi":"Ngày mùng 1 tháng 9 tôi đi học."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-zhe', 'HSK 1', 37, 'ĐẠI TỪ CHỈ 这、那 (NÀY, KIA)', '这', 'hutu', 'Đại từ chỉ 这、那 (này, kia) — điểm ngữ pháp HSK 1.', '[["这/那","key"],["Lượng từ 个"],["Danh từ"]]', '["Bẫy người Việt: ","BỎ 个 SAU 这 VÀ 那 KHI NÓI DANH TỪ ĐƠN"," \u003b 这 và 那 phải kèm lượng từ 个 trước danh từ, không nói trực tiếp 这书."]', '[{"hz":"这个人是我爸爸。","py":"zhège rén shì wǒ bàba.","vi":"Người này là bố tôi."},{"hz":"那个是学校。","py":"nàge shì xuéxiào.","vi":"Kia là trường học."},{"hz":"这个苹果很好吃。","py":"zhège píngguǒ hěn hǎochī.","vi":"Quả táo này rất ngon."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-zhe-er', 'HSK 1', 38, 'ĐẠI TỪ NƠI CHỐN 这儿、那儿', '这儿', 'hutu', 'Đại từ nơi chốn 这儿、那儿 — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["在"],["这儿/那儿","key"]]', '["Bẫy người Việt: ","DÙNG 这 里 LUÔN THAY CHO 这儿"," \u003b chỉ nơi đây dùng 这儿 hoặc 这里, nhưng trong một câu chỉ chọn một dạng cho thống nhất."]', '[{"hz":"我在这儿。","py":"wǒ zài zhèr.","vi":"Tôi ở đây."},{"hz":"他在那儿。","py":"tā zài nàr.","vi":"Anh ấy ở kia."},{"hz":"这儿人很多。","py":"zhèr rén hěn duō.","vi":"Ở đây người rất đông."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-li', 'HSK 1', 39, 'VỊ TỪ 里 (TRONG)', '里', 'bongu', 'Vị từ 里 (trong) — điểm ngữ pháp HSK 1.', '[["Danh từ + 里","key"],["有/是"],["Danh từ"]]', '["Bẫy người Việt: ","ĐẶT 里 TRƯỚC DANH TỪ"," \u003b 里 là vị từ luôn đứng sau danh từ chỉ nơi chứa, ví dụ 杯子里 không phải 里杯子."]', '[{"hz":"杯子里有水。","py":"bēizi li yǒu shuǐ.","vi":"Trong cốc có nước."},{"hz":"家里有桌子。","py":"jiā li yǒu zhuōzi.","vi":"Trong nhà có bàn."},{"hz":"教室里都是学生。","py":"jiàoshì li dōu shì xuésheng.","vi":"Trong lớp toàn là học sinh."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-shang', 'HSK 1', 40, 'VỊ TỪ 上、下 (TRÊN, DƯỚI)', '上', 'bongu', 'Vị từ 上、下 (trên, dưới) — điểm ngữ pháp HSK 1.', '[["Danh từ + 上","key"],["有"],["Danh từ"]]', '["Bẫy người Việt: ","QUÊN 面 KHI NÓI 桌子下面"," \u003b 桌子上 và 桌子上面 đều đúng nhưng phải giữ vị từ sau danh từ, không đảo lên trước."]', '[{"hz":"桌子上有一本书。","py":"zhuōzi shang yǒu yì běn shū.","vi":"Trên bàn có một cuốn sách."},{"hz":"桌子上有一只猫。","py":"zhuōzi shang yǒu yì zhǐ māo.","vi":"Trên bàn có một con mèo."},{"hz":"书在床下面。","py":"shū zài chuáng xiàmiàn.","vi":"Sách ở dưới giường."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-hou-mian', 'HSK 1', 41, 'VỊ TỪ 前面、后面 (TRƯỚC, SAU)', '后面', 'bongu', 'Vị từ 前面、后面 (trước, sau) — điểm ngữ pháp HSK 1.', '[["Danh từ + 前面/后面","key"],["有"],["Danh từ"]]', '["Bẫy người Việt: ","BỎ 面 KHI DÙNG 前、后 ĐƠN LỆ"," \u003b với người và vật cụ thể phải nói 前面、后面 đầy đủ, dạng 前、后 đơn lẻ chỉ dùng trong từ ghép."]', '[{"hz":"学校前面有一个商店。","py":"xuéxiào qiánmiàn yǒu yíge shāngdiàn.","vi":"Trước trường có một cửa hàng."},{"hz":"猫在车后面。","py":"māo zài chē hòumiàn.","vi":"Con mèo ở sau chiếc xe."},{"hz":"我家后面是学校。","py":"wǒ jiā hòumiàn shì xuéxiào.","vi":"Sau nhà tôi là trường học."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-he', 'HSK 1', 42, 'LIÊN TỪ 和 (VÀ)', '和', 'bongu', 'Liên từ 和 (và) — điểm ngữ pháp HSK 1.', '[["Danh ngữ"],["和","key"],["Danh ngữ"]]', '["Bẫy người Việt: ","DÙNG 和 NỐI HAI CÂU"," \u003b 和 chỉ nối danh từ với nhau, nối hai mệnh đề phải dùng dấu phẩy hoặc từ khác."]', '[{"hz":"我和爸爸在家。","py":"wǒ hé bàba zài jiā.","vi":"Tôi và bố ở nhà."},{"hz":"我和你都是学生。","py":"wǒ hé nǐ dōu shì xuésheng.","vi":"Tôi và bạn đều là học sinh."},{"hz":"他喝咖啡和牛奶。","py":"tā hē kāfēi hé niúnǎi.","vi":"Anh ấy uống cà phê và sữa."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-gei', 'HSK 1', 43, 'CẤU TRÚC ĐỘNG TỪ KÉP VỚI 给', '给', 'ba', 'Cấu trúc động từ kép với 给 — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["Động từ"],["给","key"],["Người nhận"],["Vật"]]', '["Bẫy người Việt: ","ĐẶT NGƯỜI NHẬN TRƯỚC ĐỘNG TỪ 给"," \u003b thứ tự chuẩn là động từ trước, 给 nối người nhận rồi mới đến vật."]', '[{"hz":"我给他一本书。","py":"wǒ gěi tā yì běn shū.","vi":"Tôi đưa anh ấy một cuốn sách."},{"hz":"妈妈给我苹果。","py":"māma gěi wǒ píngguǒ.","vi":"Mẹ cho tôi táo."},{"hz":"老师给学生书。","py":"lǎoshī gěi xuésheng shū.","vi":"Giáo viên đưa học sinh sách."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-qing', 'HSK 1', 44, 'CÂU MỆNH LỆNH LỊCH SỰ VỚI 请', '请', 'hutu', 'Câu mệnh lệnh lịch sự với 请 — điểm ngữ pháp HSK 1.', '[["请","key"],["Động từ"]]', '["Bẫy người Việt: ","BỎ 主语 HOẶC THÊM 你 SAU 请 SAI CÁCH"," \u003b 请 + động từ là đủ lịch sự, thêm 你 vào giữa nghe gượng và không chuẩn."]', '[{"hz":"请坐!","py":"qǐng zuò!","vi":"Mời ngồi!"},{"hz":"请喝水。","py":"qǐng hē shuǐ.","vi":"Mời uống nước."},{"hz":"请看这儿。","py":"qǐng kàn zhèr.","vi":"Xin nhìn đây."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-yi-dian-er', 'HSK 1', 45, 'SỐ LƯỢNG ÍT VỚI 一点儿', '一点儿', 'hutu', 'Số lượng ít với 一点儿 — điểm ngữ pháp HSK 1.', '[["Động từ"],["一点儿","key"],["Danh từ"]]', '["Bẫy người Việt: ","BỎ 儿 HOẶC ĐẢO THÀNH 点儿一"," \u003b thứ tự cố định là 一点儿 + danh từ, một số vùng khẩu ngữ nói 点儿 nhưng viết phải đủ 一点儿."]', '[{"hz":"我喝一点儿水。","py":"wǒ hē yìdiǎnr shuǐ.","vi":"Tôi uống một chút nước."},{"hz":"我会一点儿汉语。","py":"wǒ huì yìdiǎnr Hànyǔ.","vi":"Tôi biết một chút tiếng Trung."},{"hz":"请给我一点儿咖啡。","py":"qǐng gěi wǒ yìdiǎnr kāfēi.","vi":"Cho tôi một chút cà phê."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-yi-xia', 'HSK 1', 46, 'BỔ NGỮ 一下 (LÀM MỘT CHÚT)', '一下', 'bi', 'Bổ ngữ 一下 (làm một chút) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["Động từ"],["一下","key"]]', '["Bẫy người Việt: ","ĐẶT 一下 TRƯỚC ĐỘNG TỪ"," \u003b 一下 là bổ ngữ đứng ngay sau động từ, làm câu nghe nhẹ nhàng như thử hoặc làm qua loa."]', '[{"hz":"我看一下。","py":"wǒ kàn yíxià.","vi":"Tôi xem một chút."},{"hz":"你说一下。","py":"nǐ shuō yíxià.","vi":"Bạn nói thử xem."},{"hz":"我看一下你的书。","py":"wǒ kàn yíxià nǐ de shū.","vi":"Tôi xem một chút sách của bạn."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-dui-bu-qi', 'HSK 1', 47, 'XIN LỖI VỚI 对不起、没关系', '对不起', 'hutu', 'Xin lỗi với 对不起、没关系 — điểm ngữ pháp HSK 1.', '[["对不起","key"],[","],["没关系"]]', '["Bẫy người Việt: ","TRẢ LỜI XIN LỖI BẰNG 不客气"," \u003b 不客气 chỉ dùng khi nhận lời cảm ơn, khi ai xin lỗi phải đáp 没关系."]', '[{"hz":"对不起!","py":"duìbuqǐ!","vi":"Xin lỗi!"},{"hz":"没关系!","py":"méi guānxi!","vi":"Không sao!"},{"hz":"对不起,老师。","py":"duìbuqǐ, lǎoshī.","vi":"Em xin lỗi, thầy ạ."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-qu', 'HSK 1', 48, 'ĐỘNG TỪ CHỈ HƯỚNG 去、来', '去', 'hutu', 'Động từ chỉ hướng 去、来 — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["去/来","key"],["Địa điểm"]]', '["Bẫy người Việt: ","DÙNG 去 KHI VẬT THỂ CHỈ VỀ PHÍA MÌNH"," \u003b 去 là đi ra xa người nói, 来 là đến gần người nói, chọn sai sẽ gây hiểu nhầm hướng."]', '[{"hz":"我去学校。","py":"wǒ qù xuéxiào.","vi":"Tôi đi trường."},{"hz":"他来我家。","py":"tā lái wǒ jiā.","vi":"Anh ấy đến nhà tôi."},{"hz":"你去哪儿?","py":"nǐ qù nǎr?","vi":"Bạn đi đâu thế?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-zuo', 'HSK 1', 49, 'ĐI LẠI BẰNG PHƯƠNG TIỆN VỚI 坐', '坐', 'hutu', 'Đi lại bằng phương tiện với 坐 — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["坐","key"],["Phương tiện"],["Động từ"]]', '["Bẫy người Việt: ","ĐẶT PHƯƠNG TIỆN SAU ĐỘNG TỪ ĐÍCH ĐẾN"," \u003b phương tiện đi qua 坐 phải đứng trước động từ chỉ hướng, ví dụ 坐车去 không phải 去...坐车."]', '[{"hz":"我坐公共汽车去学校。","py":"wǒ zuò gōnggòng qìchē qù xuéxiào.","vi":"Tôi đi trường bằng xe buýt."},{"hz":"他坐出租车回家。","py":"tā zuò chūzūchē huí jiā.","vi":"Anh ấy về nhà bằng taxi."},{"hz":"我们坐车去。","py":"wǒmen zuò chē qù.","vi":"Chúng ta đi bằng xe nhé."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-xing', 'HSK 1', 50, 'GIỚI THIỆU HỌ VỚI 姓', '姓', 'hutu', 'Giới thiệu họ với 姓 — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["姓","key"],["Họ"]]', '["Bẫy người Việt: ","THÊM DANH TỪ XINGSHI SAU 姓"," \u003b 姓 vừa là động từ vừa là danh từ, hỏi họ chỉ nói 你姓什么, không thêm từ khác."]', '[{"hz":"你姓什么?","py":"nǐ xìng shénme?","vi":"Bạn họ gì?"},{"hz":"我姓王。","py":"wǒ xìng Wáng.","vi":"Tôi họ Vương."},{"hz":"他姓李。","py":"tā xìng Lǐ.","vi":"Anh ấy họ Lý."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-jiao', 'HSK 1', 51, 'GIỚI THIỆU TÊN VỚI 叫', '叫', 'hutu', 'Giới thiệu tên với 叫 — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["叫","key"],["Tên"]]', '["Bẫy người Việt: ","DÙNG 是 THAY CHO 叫 KHI NÓI TÊN MÌNH"," \u003b giới thiệu tên tự nhiên nhất là 我叫…, kết cấu 是 + tên nghe cứng nhắc hơn."]', '[{"hz":"我叫小明。","py":"wǒ jiào Xiǎomíng.","vi":"Tôi tên là Tiểu Minh."},{"hz":"她叫什么名字?","py":"tā jiào shénme míngzi?","vi":"Cô ấy tên là gì?"},{"hz":"我妈妈叫张丽。","py":"wǒ māma jiào Zhāng Lì.","vi":"Mẹ tôi tên Trương Lệ."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-jue-de', 'HSK 1', 52, 'CẤU TRÚC 觉得 (THẤY, NGHĨ RẰNG)', '觉得', 'hutu', 'Cấu trúc 觉得 (thấy, nghĩ rằng) — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["觉得","key"],["Mệnh đề"]]', '["Bẫy người Việt: ","DÙNG 是 SAU 觉得 NHƯ TỪ THAT"," \u003b sau 觉得 nối thẳng mệnh đề, không cần từ nối nào ở giữa."]', '[{"hz":"我觉得很好。","py":"wǒ juéde hěn hǎo.","vi":"Tôi thấy rất tốt."},{"hz":"我觉得苹果很好吃。","py":"wǒ juéde píngguǒ hěn hǎochī.","vi":"Tôi thấy táo rất ngon."},{"hz":"你觉得怎么样?","py":"nǐ juéde zěnmeyàng?","vi":"Bạn thấy thế nào?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-qing-wen', 'HSK 1', 53, 'HỎI LỊCH SỰ VỚI 请问', '请问', 'hutu', 'Hỏi lịch sự với 请问 — điểm ngữ pháp HSK 1.', '[["请问","key"],[","],["Câu hỏi"]]', '["Bẫy người Việt: ","ĐẶT 请问 Ở CUỐI CÂU"," \u003b 请问 luôn mở đầu câu hỏi với người lạ, sau nó thường có dấu phẩy rồi mới đến câu hỏi."]', '[{"hz":"请问,你去哪儿?","py":"qǐngwèn, nǐ qù nǎr?","vi":"Cho hỏi, bạn đi đâu?"},{"hz":"请问,现在几点?","py":"qǐngwèn, xiànzài jǐ diǎn?","vi":"Cho hỏi, bây giờ mấy giờ?"},{"hz":"请问,厕所在哪儿?","py":"qǐngwèn, cèsuǒ zài nǎr?","vi":"Cho hỏi, nhà vệ sinh ở đâu?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-yi', 'HSK 1', 54, 'BIẾN ĐIỆU THANH CỦA 一', '一', 'hutu', 'Biến điệu thanh của 一 — điểm ngữ pháp HSK 1.', '[["Số từ 一","key"],["Lượng từ"]]', '["Bẫy người Việt: ","ĐỌC 一 LUÔN LÀ YĨ"," \u003b 一 đọc yī khi đứng một mình, thành yí trước thanh 4 và yì trước thanh 1, 2, 3."]', '[{"hz":"一个。","py":"yí ge.","vi":"Một cái."},{"hz":"一本。","py":"yì běn.","vi":"Một cuốn."},{"hz":"一天。","py":"yì tiān.","vi":"Một ngày."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-kan-kan', 'HSK 1', 55, 'ĐỘNG TỪ NHÂN ĐÔI 看看、试试', '看看', 'hutu', 'Động từ nhân đôi 看看、试试 — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["Động từ ×2","key"]]', '["Bẫy người Việt: ","DÙNG 看看 CHO HÀNH ĐỘNG ĐANG XẢY RA"," \u003b nhân đôi động từ diễn tả hành động ngắn, thử nghiệm hoặc nhẹ nhàng, không diễn tả sự đang tiếp diễn."]', '[{"hz":"我看看。","py":"wǒ kànkan.","vi":"Tôi xem thử."},{"hz":"你试试。","py":"nǐ shìshi.","vi":"Bạn thử xem."},{"hz":"我们看看这个。","py":"wǒmen kànkan zhège.","vi":"Chúng ta xem thử cái này."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-zai-na-er', 'HSK 1', 56, 'HỎI VỊ TRÍ VỚI 在哪儿', '在哪儿', 'hutu', 'Hỏi vị trí với 在哪儿 — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["在哪儿","key"]]', '["Bẫy người Việt: ","BỎ 在 KHI HỎI ĐỊA CHỈ"," \u003b hỏi cái gì ở đâu phải đủ 在哪儿, chỉ nói 哪儿 thôi là thiếu động từ 在."]', '[{"hz":"学校在哪儿?","py":"xuéxiào zài nǎr?","vi":"Trường học ở đâu?"},{"hz":"厕所在哪儿?","py":"cèsuǒ zài nǎr?","vi":"Nhà vệ sinh ở đâu?"},{"hz":"你家在哪儿?","py":"nǐ jiā zài nǎr?","vi":"Nhà bạn ở đâu?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-chi', 'HSK 1', 57, 'TRẬT TỰ CÂU CHỦ - VỊ - TÂN', '吃', 'ba', 'Trật tự câu chủ - vị - tân — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["Động từ","key"],["Tân ngữ"]]', '["Bẫy người Việt: ","ĐẢO TÂN NGỮ LÊN TRƯỚC ĐỘNG TỪ"," \u003b câu đơn tiếng Trung luôn theo thứ tự chủ ngữ, động từ, tân ngữ, rất ít ngoại lệ."]', '[{"hz":"我吃苹果。","py":"wǒ chī píngguǒ.","vi":"Tôi ăn táo."},{"hz":"他喝咖啡。","py":"tā hē kāfēi.","vi":"Anh ấy uống cà phê."},{"hz":"我们学汉语。","py":"wǒmen xué Hànyǔ.","vi":"Chúng tôi học tiếng Trung."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-xie-xie', 'HSK 1', 58, 'CẢM ƠN VỚI 谢谢、不客气', '谢谢', 'hutu', 'Cảm ơn với 谢谢、不客气 — điểm ngữ pháp HSK 1.', '[["谢谢","key"],["Người/vật"]]', '["Bẫy người Việt: ","ĐÁP LỜI CẢM ƠN BẰNG 没关系"," \u003b 没关系 dùng cho lời xin lỗi, đáp lời cảm ơn phải nói 不客气."]', '[{"hz":"谢谢你!","py":"xièxie nǐ!","vi":"Cảm ơn bạn!"},{"hz":"不客气!","py":"bú kèqi!","vi":"Không có gì!"},{"hz":"谢谢你的书。","py":"xièxie nǐ de shū.","vi":"Cảm ơn cuốn sách của bạn."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk1-mang', 'HSK 1', 59, 'CÂU VỊ NGỮ TÍNH TỪ', '忙', 'ba', 'Câu vị ngữ tính từ — điểm ngữ pháp HSK 1.', '[["Chủ ngữ"],["Tính từ","key"]]', '["Bẫy người Việt: ","THÊM 是 TRƯỚC TÍNH TỪ NHƯ TIẾNG VIỆT CÓ LÀ"," \u003b câu vị ngữ tính từ không dùng 是, tính từ đứng thẳng sau chủ ngữ kèm 很 hoặc 不."]', '[{"hz":"我很忙。","py":"wǒ hěn máng.","vi":"Tôi rất bận."},{"hz":"今天很热。","py":"jīntiān hěn rè.","vi":"Hôm nay rất nóng."},{"hz":"他不高兴。","py":"tā bù gāoxìng.","vi":"Anh ấy không vui."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-le', 'HSK 2', 0, '了 (HOÀN THÀNH ĐỘNG TÁC)', '了', 'bongu', '了 (hoàn thành động tác) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["Động từ"],["了","key"],["Tân ngữ / số lượng"]]', '["Người Việt hay ","ĐẶT 了 SAU TÂN NGỮ hoặc QUÊN 了 khi có số lượng từ"," như 我看了一个电影了. Đặt 了 ngay sau động từ: 我看了一个电影."]', '[{"hz":"我买了一本书。","py":"wǒ mǎi le yī běn shū.","vi":"Tôi đã mua một cuốn sách."},{"hz":"他吃了三个苹果。","py":"tā chī le sān gè píngguǒ.","vi":"Anh ấy đã ăn ba quả táo."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-le-2', 'HSK 2', 1, '了 (THAY ĐỔI TRẠNG THÁI)', '了', 'bongu', '了 (thay đổi trạng thái) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["Tính từ / động từ"],["了","key"]]', '["Người Việt hay ","NHẦM 了 này với 了 hoàn thành, đặt sai vị trí sau tân ngữ",". 了 đổi trạng thái đứng CUỐI CÂU, sau tính từ: 天冷了 (trời lạnh rồi)."]', '[{"hz":"天冷了。","py":"tiān lěng le.","vi":"Trời lạnh rồi."},{"hz":"他会说汉语了。","py":"tā huì shuō hànyǔ le.","vi":"Anh ấy giờ đã biết nói tiếng Trung rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-guo', 'HSK 2', 2, '过 (KINH NGHIỆM)', '过', 'bongu', '过 (kinh nghiệm) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["Động từ"],["过","key"],["Tân ngữ"]]', '["Người Việt hay ","DÙNG 了 thay vì 过 khi nói kinh nghiệm từng làm",". 过 nghĩa là đã từng trải nghiệm: 我去过中国 (tôi từng đi Trung Quốc)."]', '[{"hz":"我吃过北京烤鸭。","py":"wǒ chī guò běijīng kǎoyā.","vi":"Tôi từng ăn vịt quay Bắc Kinh."},{"hz":"你没学过汉语吗？","py":"nǐ méi xué guò hànyǔ ma?","vi":"Bạn chưa từng học tiếng Trung à?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-guo-2', 'HSK 2', 3, '过 (VƯỢT QUÁ MỨC)', '过', 'hutu', '过 (vượt quá mức) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["Tính từ / động từ"],["过","key"],["(了)"]]', '["Người Việt hay ","DỊCH 过 là kinh nghiệm, không hiểu nghĩa vượt mức",". Sau tính từ, 过 nghĩa là quá lố, quá mức cho phép: 他睡过头了 (anh ấy ngủ quá giờ)."]', '[{"hz":"他睡过头了。","py":"tā shuì guò tóu le.","vi":"Anh ấy ngủ quá giờ rồi."},{"hz":"你买太多了。","py":"nǐ mǎi tài duō le.","vi":"Bạn mua nhiều quá rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-zhe', 'HSK 2', 4, '着 (TRẠNG THÁI ĐANG DUY TRÌ)', '着', 'bongu', '着 (trạng thái đang duy trì) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["Động từ"],["着","key"],["Tân ngữ"]]', '["Người Việt hay ","DÙNG 在 thay vì 着 khi diễn tả trạng thái tĩnh đang duy trì",". 着 mô tả cách sự vật tồn tại: 门开着 (cửa đang mở)."]', '[{"hz":"门开着。","py":"mén kāi zhe.","vi":"Cửa đang mở."},{"hz":"他穿着一件白衬衫。","py":"tā chuān zhe yī jiàn bái chènshān.","vi":"Anh ấy mặc một chiếc áo sơ mi trắng."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-zai', 'HSK 2', 5, '在 + ĐỘNG TỪ (ĐANG LÀM)', '在', 'bongu', '在 + động từ (đang làm) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["在","key"],["Động từ"],["Tân ngữ"]]', '["Người Việt hay ","QUÊN 在 hoặc ĐẶT 在 SAU ĐỘNG TỪ",". 在 luôn đứng TRƯỚC động từ để chỉ hành động đang diễn ra: 我在吃饭."]', '[{"hz":"我在学汉语。","py":"wǒ zài xué hànyǔ.","vi":"Tôi đang học tiếng Trung."},{"hz":"妈妈在做饭。","py":"māma zài zuòfàn.","vi":"Mẹ đang nấu ăn."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-zheng-zai', 'HSK 2', 6, '正在...呢 (ĐANG TIẾN HÀNH NHẤN MẠNH)', '正在', 'bongu', '正在...呢 (đang tiến hành nhấn mạnh) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["正在","key"],["Động từ"],["呢"]]', '["Người Việt hay ","DÙNG 正在 và 呢 RỜI RẠC, hoặc THÊM 了 vào câu đang diễn ra",". Câu đang làm không dùng 了: 我正在看书呢."]', '[{"hz":"他正在打电话呢。","py":"tā zhèngzài dǎ diànhuà ne.","vi":"Anh ấy đang gọi điện thoại."},{"hz":"我们正在上课呢。","py":"wǒmen zhèngzài shàngkè ne.","vi":"Chúng tôi đang học bài."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-ma', 'HSK 2', 7, '吗 (CÂU HỎI CÓ/KHÔNG)', '吗', 'bongu', '吗 (câu hỏi có/không) — điểm ngữ pháp HSK 2.', '[["Câu trần thuật"],["吗","key"],["?"]]', '["Người Việt hay ","VỪA dùng 吗 VỪA dùng từ nghi vấn hoặc từ phủ định kép",". Câu có 吗 không thêm 怎么/什么: 你去吗？ đúng, 你去什么吗？ sai."]', '[{"hz":"你是学生吗？","py":"nǐ shì xuéshēng ma?","vi":"Bạn là học sinh à?"},{"hz":"今天下雨了吗？","py":"jīntiān xià yǔ le ma?","vi":"Hôm nay có mưa không?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-ne', 'HSK 2', 8, '呢 (HỎI LẠI NGẮN GỌN)', '呢', 'bongu', '呢 (hỏi lại ngắn gọn) — điểm ngữ pháp HSK 2.', '[["Từ được hỏi"],["呢","key"],["?"]]', '["Người Việt hay ","GIẢI THÍCH DÀI DÒNG thay vì dùng 呢 hỏi lại",". 呢 đứng cuối để hỏi lại cùng câu hỏi: 你呢？ = còn bạn thì sao?"]', '[{"hz":"我很好，你呢？","py":"wǒ hěn hǎo, nǐ ne?","vi":"Tôi khỏe, còn bạn thì sao?"},{"hz":"他去学校了，你妹妹呢？","py":"tā qù xuéxiào le, nǐ mèimei ne?","vi":"Anh ấy đi học rồi, còn em gái bạn thì sao?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-ba', 'HSK 2', 9, '吧 (ĐỀ NGHỊ, RỦ MỜI)', '吧', 'bongu', '吧 (đề nghị, rủ mời) — điểm ngữ pháp HSK 2.', '[["Mệnh đề đề nghị"],["吧","key"],["?"]]', '["Người Việt hay ","DÙNG 吗 thay vì 吧 khi rủ rê, đề nghị",". 吧 làm câu nói mềm mại, mời mọc: 我们走吧 (mình đi thôi)."]', '[{"hz":"我们回家吧。","py":"wǒmen huí jiā ba.","vi":"Mình về nhà thôi."},{"hz":"喝杯茶吧。","py":"hē bēi chá ba.","vi":"Uống một cốc trà nhé."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-hai-shi', 'HSK 2', 10, '还是 (CÂU HỎI LỰA CHỌN)', '还是', 'bongu', '还是 (câu hỏi lựa chọn) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["Phương án A"],["还是","key"],["Phương án B ?"]]', '["Người Việt hay ","DÙNG 还是 trong câu trần thuật hoặc dùng 或者 khi hỏi",". Hỏi lựa chọn dùng 还是, câu trần thuật dùng 或者."]', '[{"hz":"你喝茶还是咖啡？","py":"nǐ hē chá háishi kāfēi?","vi":"Bạn uống trà hay cà phê?"},{"hz":"我们坐火车还是坐飞机？","py":"wǒmen zuò huǒchē háishi zuò fēijī?","vi":"Chúng ta đi tàu hay đi máy bay?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-huo-zhe', 'HSK 2', 11, '或者 (HOẶC, CÂU TRẦN THUẬT)', '或者', 'bongu', '或者 (hoặc, câu trần thuật) — điểm ngữ pháp HSK 2.', '[["Phương án A"],["或者","key"],["Phương án B"],["Phần còn lại"]]', '["Người Việt hay ","DÙNG 或者 trong câu hỏi thay vì 还是",". 或者 chỉ nối các lựa chọn trong câu trần thuật: 我喝茶或者咖啡都行."]', '[{"hz":"明天或者后天我去看你。","py":"míngtiān huòzhě hòutiān wǒ qù kàn nǐ.","vi":"Mai hoặc mốt tôi đến thăm bạn."},{"hz":"晚上我看书或者看电视。","py":"wǎnshang wǒ kàn shū huòzhě kàn diànshì.","vi":"Tối tôi đọc sách hoặc xem tivi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-jiu', 'HSK 2', 12, '就 (SỚM, NHANH)', '就', 'bongu', '就 (sớm, nhanh) — điểm ngữ pháp HSK 2.', '[["Thời gian"],["就","key"],["Động từ"]]', '["Người Việt hay ","NHẦM 就 với 才 vì tiếng Việt chỉ có một từ mới",". 就 = sớm, nhanh hơn mong đợi: 我八点就来了 (tám giờ tôi đã đến rồi)."]', '[{"hz":"他五点就起床了。","py":"tā wǔ diǎn jiù qǐchuáng le.","vi":"Năm giờ anh ấy đã dậy rồi."},{"hz":"我们马上就走。","py":"wǒmen mǎshàng jiù zǒu.","vi":"Chúng tôi đi ngay bây giờ."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-jiu-2', 'HSK 2', 13, '就 (NỐI TIẾP, LÀM NGAY)', '就', 'bongu', '就 (nối tiếp, làm ngay) — điểm ngữ pháp HSK 2.', '[["Mệnh đề trước"],["就","key"],["Mệnh đề sau"]]', '["Người Việt hay ","QUÊN 就 trong cấu trúc 一...就...",". 一...就... nghĩa là vừa... thì đã...: 我一到家就睡觉."]', '[{"hz":"我一到家就睡觉。","py":"wǒ yī dào jiā jiù shuìjiào.","vi":"Tôi vừa về đến nhà là đi ngủ."},{"hz":"下课以后我就去找你。","py":"xià kè yǐhòu wǒ jiù qù zhǎo nǐ.","vi":"Hết lớp tôi sẽ đi tìm bạn ngay."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-cai', 'HSK 2', 14, '才 (MUỘN, CHẬM HƠN MONG ĐỢI)', '才', 'bongu', '才 (muộn, chậm hơn mong đợi) — điểm ngữ pháp HSK 2.', '[["Thời gian"],["才","key"],["Động từ"]]', '["Người Việt hay ","DÙNG 就 thay vì 才 khi nói muộn",". 才 = muộn, chậm: 他十点才来 (mười giờ anh ấy mới đến)."]', '[{"hz":"他十点才来。","py":"tā shí diǎn cái lái.","vi":"Mười giờ anh ấy mới đến."},{"hz":"我下午才回家。","py":"wǒ xiàwǔ cái huí jiā.","vi":"Chiều tôi mới về nhà."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-dou', 'HSK 2', 15, '都 (TẤT CẢ, ĐỀU)', '都', 'bongu', '都 (tất cả, đều) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ (số nhiều)"],["都","key"],["Động từ"]]', '["Người Việt hay ","ĐẶT 都 TRƯỚC CHỦ NGỮ hoặc nhầm 都 là động từ",". 都 là phó từ, luôn đứng sau chủ ngữ, trước động từ: 我们都是学生."]', '[{"hz":"我们都是学生。","py":"wǒmen dōu shì xuéshēng.","vi":"Chúng tôi đều là học sinh."},{"hz":"他们都说汉语。","py":"tāmen dōu shuō hànyǔ.","vi":"Họ đều nói tiếng Trung."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-ye', 'HSK 2', 16, '也 (CŨNG)', '也', 'bongu', '也 (cũng) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["也","key"],["Động từ / tính từ"]]', '["Người Việt hay ","ĐẶT 也 SAU động từ hoặc trước chủ ngữ",". 也 đứng sau chủ ngữ, trước động từ: 我也去, không nói 我去也."]', '[{"hz":"他也喜欢唱歌。","py":"tā yě xǐhuan chànggē.","vi":"Anh ấy cũng thích hát."},{"hz":"明天我也去。","py":"míngtiān wǒ yě qù.","vi":"Mai tôi cũng đi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-zai-2', 'HSK 2', 17, '再 (LẦN NỮA TRONG TƯƠNG LAI)', '再', 'bongu', '再 (lần nữa trong tương lai) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["Động từ"],["再","key"],["Động từ 2"]]', '["Người Việt hay ","DÙNG 又 thay vì 再 cho hành động chưa xảy ra",". 再 dùng cho hành động lặp lại sau này: 再说一遍 (nói lại một lần nữa)."]', '[{"hz":"请你再说一遍。","py":"qǐng nǐ zài shuō yī biàn.","vi":"Xin bạn nói lại một lần nữa."},{"hz":"明天我再来。","py":"míngtiān wǒ zài lái.","vi":"Mai tôi sẽ đến lần nữa."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-you', 'HSK 2', 18, '又 (LẦN NỮA TRONG QUÁ KHỨ)', '又', 'bongu', '又 (lần nữa trong quá khứ) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["又","key"],["Động từ + 了"]]', '["Người Việt hay ","DÙNG 再 thay vì 又 khi kể chuyện đã xảy ra",". 又 dùng cho hành động lặp đã xảy ra: 他又迟到了 (anh ấy lại đi trễ nữa)."]', '[{"hz":"他又迟到了。","py":"tā yòu chídào le.","vi":"Anh ấy lại đến trễ nữa."},{"hz":"昨天我又买了一件衣服。","py":"zuótiān wǒ yòu mǎi le yī jiàn yīfu.","vi":"Hôm qua tôi lại mua thêm một bộ quần áo."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-tai', 'HSK 2', 19, '太...了 (QUÁ)', '太', 'hutu', '太...了 (quá) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["太","key"],["Tính từ"],["了"]]', '["Người Việt hay ","QUÊN 了 CUỐI CÂU hoặc dùng 太 sai ngữ cảnh khen chê",". Cấu trúc cố định là 太 + tính từ + 了: 太贵了."]', '[{"hz":"这个东西太贵了。","py":"zhège dōngxi tài guì le.","vi":"Cái này đắt quá."},{"hz":"今天太热了。","py":"jīntiān tài rè le.","vi":"Hôm nay nóng quá."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-hen', 'HSK 2', 20, '很 (ĐỘ MỨC CÂU TRẦN THUẬT)', '很', 'bongu', '很 (độ mức câu trần thuật) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["很","key"],["Tính từ"]]', '["Người Việt hay ","DỊCH 很 là rất trong mọi câu, khiến câu nghe quá đà",". Trong câu trần thuật đơn, 很 chỉ nối chủ ngữ và tính từ, dịch nhẹ: 他很好 (anh ấy ổn)."]', '[{"hz":"我很好，谢谢。","py":"wǒ hěn hǎo, xièxie.","vi":"Tôi vẫn khỏe, cảm ơn."},{"hz":"这个苹果很甜。","py":"zhège píngguǒ hěn tián.","vi":"Quả táo này ngọt lắm."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-hui', 'HSK 2', 21, '会 (BIẾT LÀM, CÓ NĂNG LỰC)', '会', 'bongu', '会 (biết làm, có năng lực) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["会","key"],["Động từ"]]', '["Người Việt hay ","DÙNG 能 hoặc 可以 thay vì 会 khi nói kỹ năng học được",". 会 = biết làm nhờ học: 我会说汉语."]', '[{"hz":"我会说一点儿汉语。","py":"wǒ huì shuō yīdiǎnr hànyǔ.","vi":"Tôi biết nói một chút tiếng Trung."},{"hz":"他会游泳。","py":"tā huì yóuyǒng.","vi":"Anh ấy biết bơi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-hui-2', 'HSK 2', 22, '会 (SẼ, TƯƠNG LAI)', '会', 'bongu', '会 (sẽ, tương lai) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["会","key"],["Động từ"],["(了)"]]', '["Người Việt hay ","NHẦM 会 tương lai với 会 năng lực",". 会 đứng trước động từ chỉ tương lai: 明天会下雨 (mai sẽ mưa)."]', '[{"hz":"明天会下雨。","py":"míngtiān huì xià yǔ.","vi":"Mai sẽ mưa."},{"hz":"他会来的。","py":"tā huì lái de.","vi":"Anh ấy sẽ đến mà."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-neng', 'HSK 2', 23, '能 (CÓ THỂ, KHẢ NĂNG CHỦ QUAN)', '能', 'bongu', '能 (có thể, khả năng chủ quan) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["能","key"],["Động từ"]]', '["Người Việt hay ","DÙNG 会 thay vì 能 khi xin phép hoặc nói điều kiện cho phép",". 能 hỏi được phép: 我能进来吗？"]', '[{"hz":"我能进来吗？","py":"wǒ néng jìnlái ma?","vi":"Tôi có thể vào được không?"},{"hz":"今天我不能去。","py":"jīntiān wǒ bù néng qù.","vi":"Hôm nay tôi không thể đi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-ke-yi', 'HSK 2', 24, '可以 (ĐƯỢC PHÉP, CÓ THỂ)', '可以', 'bongu', '可以 (được phép, có thể) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["可以","key"],["Động từ"]]', '["Người Việt hay ","DÙNG 能 để trả lời xin phép thay vì 可以",". 可以 trả lời sự cho phép: 你可以走了 (bạn có thể đi rồi)."]', '[{"hz":"这里可以吸烟吗？","py":"zhèlǐ kěyǐ xīyān ma?","vi":"Ở đây hút thuốc được không?"},{"hz":"你可以用我的书。","py":"nǐ kěyǐ yòng wǒ de shū.","vi":"Bạn có thể dùng sách của tôi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-ying-gai', 'HSK 2', 25, '应该 (NÊN)', '应该', 'bongu', '应该 (nên) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["应该","key"],["Động từ"]]', '["Người Việt hay ","DÙNG 要 thay vì 应该 khi khuyên bảo",". 应该 = nên, nghĩa vụ hợp lý: 你应该多喝水."]', '[{"hz":"你应该多喝水。","py":"nǐ yīnggāi duō hē shuǐ.","vi":"Bạn nên uống nhiều nước."},{"hz":"我们应该早点儿睡。","py":"wǒmen yīnggāi zǎodiǎnr shuì.","vi":"Chúng ta nên ngủ sớm hơn."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-de', 'HSK 2', 26, '得 DĚI (PHẢI, BẮT BUỘC)', '得', 'bongu', '得 děi (phải, bắt buộc) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["得","key"],["Động từ"]]', '["Người Việt hay ","ĐỌC NHẦM 得 děi với 得 de (bổ ngữ)",". Khi nghĩa là phải, 得 đọc děi: 我得走了 (tôi phải đi rồi)."]', '[{"hz":"我得走了。","py":"wǒ děi zǒu le.","vi":"Tôi phải đi rồi."},{"hz":"明天我得早起。","py":"míngtiān wǒ děi zǎo qǐ.","vi":"Mai tôi phải dậy sớm."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-xiang', 'HSK 2', 27, '想 (MUỐN LÀM GÌ)', '想', 'bongu', '想 (muốn làm gì) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["想","key"],["Động từ"]]', '["Người Việt hay ","DÙNG 想 và 要 TRỘN LẪN khi nói mong muốn",". 想 = muốn làm gì đó (mong ước nhẹ nhàng): 我想去中国."]', '[{"hz":"我想去中国。","py":"wǒ xiǎng qù zhōngguó.","vi":"Tôi muốn đi Trung Quốc."},{"hz":"他想吃饭。","py":"tā xiǎng chīfàn.","vi":"Anh ấy muốn ăn cơm."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-yao', 'HSK 2', 28, '要 (MUỐN CÁI GÌ)', '要', 'bongu', '要 (muốn cái gì) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["要","key"],["Danh từ"]]', '["Người Việt hay ","DÙNG 想 + danh từ thay vì 要 khi mua, đặt hàng",". Muốn một vật cụ thể dùng 要: 我要一杯咖啡."]', '[{"hz":"我要一杯咖啡。","py":"wǒ yào yī bēi kāfēi.","vi":"Tôi muốn một cốc cà phê."},{"hz":"你要什么？","py":"nǐ yào shénme?","vi":"Bạn muốn gì?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-yao-2', 'HSK 2', 29, '要...了 (SẮP)', '要', 'bongu', '要...了 (sắp) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["要","key"],["Động từ"],["了"]]', '["Người Việt hay ","QUÊN 了 hoặc DÙNG 会 thay vì 要...了",". 要...了 = sắp xảy ra: 要下雨了 (sắp mưa rồi)."]', '[{"hz":"要下雨了。","py":"yào xià yǔ le.","vi":"Sắp mưa rồi."},{"hz":"火车要开了。","py":"huǒchē yào kāi le.","vi":"Tàu sắp chạy rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-bie', 'HSK 2', 30, '别 (ĐỪNG)', '别', 'bongu', '别 (đừng) — điểm ngữ pháp HSK 2.', '[["别","key"],["Động từ"]]', '["Người Việt hay ","DÙNG 不 + động từ thay vì 别 khi khuyên ngăn",". 别 = đừng, dùng trong câu mệnh lệnh phủ định: 别走!"]', '[{"hz":"别走！","py":"bié zǒu!","vi":"Đừng đi!"},{"hz":"别担心，我会帮助你。","py":"bié dānxīn, wǒ huì bāngzhù nǐ.","vi":"Đừng lo, tôi sẽ giúp bạn."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-ba-2', 'HSK 2', 31, '把 (CẤU TRÚC XỬ LÝ)', '把', 'ba', '把 (cấu trúc xử lý) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["把","key"],["Tân ngữ"],["Động từ + thành phần khác"]]', '["Người Việt hay ","THIẾU thành phần sau động từ (了/到/在/补 ngữ)",". Câu 把 động từ phải có kết quả đi kèm: 我把书放在桌子上了."]', '[{"hz":"我把书放在桌子上了。","py":"wǒ bǎ shū fàng zài zhuōzi shang le.","vi":"Tôi đặt cuốn sách lên bàn rồi."},{"hz":"请把门关上。","py":"qǐng bǎ mén guān shang.","vi":"Xin hãy đóng cửa lại."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-zai-3', 'HSK 2', 32, '在 + NƠI CHỐN (Ở, TẠI)', '在', 'ba', '在 + nơi chốn (ở, tại) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["在","key"],["Nơi chốn"],["Động từ"]]', '["Người Việt hay ","ĐẶT 在 SAU động từ theo trật tự tiếng Việt",". Trong câu có động từ, 在 + nơi chốn đứng TRƯỚC động từ: 我在学校学习."]', '[{"hz":"我在学校学习。","py":"wǒ zài xuéxiào xuéxí.","vi":"Tôi học ở trường."},{"hz":"他在家工作。","py":"tā zài jiā gōngzuò.","vi":"Anh ấy làm việc ở nhà."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-gei', 'HSK 2', 33, '给 (CHO NGƯỜI, LÀM CHO AI)', '给', 'ba', '给 (cho người, làm cho ai) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["给","key"],["Người"],["Động từ + tân ngữ"]]', '["Người Việt hay ","ĐẶT người nhận SAU tân ngữ như tiếng Việt",". 给 + người đứng trước động từ: 我给妈妈打电话 (tôi gọi điện cho mẹ)."]', '[{"hz":"我给妈妈打电话。","py":"wǒ gěi māma dǎ diànhuà.","vi":"Tôi gọi điện cho mẹ."},{"hz":"他给我买了一本书。","py":"tā gěi wǒ mǎi le yī běn shū.","vi":"Anh ấy mua cho tôi một cuốn sách."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-dui', 'HSK 2', 34, '对 (ĐỐI VỚI)', '对', 'ba', '对 (đối với) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["对","key"],["Đối tượng"],["Động từ / tính từ"]]', '["Người Việt hay ","DÙNG 给 thay vì 对 với động từ như 说、看",". 对 nhắm thẳng vào đối tượng: 对他说, 对他很好."]', '[{"hz":"他对我说汉语。","py":"tā duì wǒ shuō hànyǔ.","vi":"Anh ấy nói tiếng Trung với tôi."},{"hz":"老师对学生很好。","py":"lǎoshī duì xuésheng hěn hǎo.","vi":"Thầy cô đối với học sinh rất tốt."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-he-/-gen', 'HSK 2', 35, '和 / 跟 (CÙNG, VỚI)', '和 / 跟', 'ba', '和 / 跟 (cùng, với) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["和 / 跟","key"],["Người"],["Động từ"]]', '["Người Việt hay ","DÙNG 和 NỐI HAI CHỦ NGỰ rồi quên 也/都 hoặc đặt sai vị trí",". 和 + người đứng sau chủ ngữ khi là đối tượng đi cùng: 我和他去."]', '[{"hz":"我和朋友去看电影。","py":"wǒ hé péngyou qù kàn diànyǐng.","vi":"Tôi đi xem phim với bạn."},{"hz":"我跟老师说汉语。","py":"wǒ gēn lǎoshī shuō hànyǔ.","vi":"Tôi nói tiếng Trung với thầy."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-cong', 'HSK 2', 36, '从 (TỪ)', '从', 'ba', '从 (từ) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["从","key"],["Điểm xuất phát"],["Động từ / 到..."]]', '["Người Việt hay ","ĐẶT 从 SAU động từ hoặc quên cặp 从...到...",". 从 đứng trước nơi/thời gian: 从家到学校."]', '[{"hz":"从家到学校很远。","py":"cóng jiā dào xuéxiào hěn yuǎn.","vi":"Từ nhà đến trường rất xa."},{"hz":"我从早上八点工作。","py":"wǒ cóng zǎoshang bā diǎn gōngzuò.","vi":"Tôi làm việc từ tám giờ sáng."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-dao', 'HSK 2', 37, '到 (ĐẾN)', '到', 'ba', '到 (đến) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["Động từ"],["到","key"],["Điểm đến"]]', '["Người Việt hay ","ĐẶT 到 TRƯỚC động từ như 在",". Sau động từ di chuyển, 到 chỉ điểm đến: 我到北京了 (tôi đến Bắc Kinh rồi)."]', '[{"hz":"我到北京了。","py":"wǒ dào běijīng le.","vi":"Tôi đã đến Bắc Kinh."},{"hz":"他每天到学校很早。","py":"tā měitiān dào xuéxiào hěn zǎo.","vi":"Ngày nào anh ấy đến trường cũng sớm."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-li', 'HSK 2', 38, '离 (CÁCH, KHOẢNG CÁCH)', '离', 'ba', '离 (cách, khoảng cách) — điểm ngữ pháp HSK 2.', '[["A"],["离","key"],["B"],["近 / 远"]]', '["Người Việt hay ","DÙNG 在 thay vì 离 khi nói khoảng cách",". 离 diễn tả A cách B gần hay xa: 我家离学校很近."]', '[{"hz":"我家离学校很近。","py":"wǒ jiā lí xuéxiào hěn jìn.","vi":"Nhà tôi cách trường rất gần."},{"hz":"车站离这儿远吗？","py":"chēzhàn lí zhèr yuǎn ma?","vi":"Bến xe cách đây xa không?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-bi', 'HSK 2', 39, '比 (SO SÁNH HƠN)', '比', 'ba', '比 (so sánh hơn) — điểm ngữ pháp HSK 2.', '[["A"],["比","key"],["B"],["Tính từ"]]', '["Người Việt hay ","THÊM 很 hoặc 太 trước tính từ trong câu 比",". Sau 比 tính từ đứng trần, không kèm 很: 他比我高, không nói 他比我很高."]', '[{"hz":"他比我高。","py":"tā bǐ wǒ gāo.","vi":"Anh ấy cao hơn tôi."},{"hz":"今天比昨天热。","py":"jīntiān bǐ zuótiān rè.","vi":"Hôm nay nóng hơn hôm qua."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-dao-2', 'HSK 2', 40, 'BỔ NGỮ KẾT QUẢ 到 (THẤY, NGHE THẤY)', '到', 'bi', 'Bổ ngữ kết quả 到 (thấy, nghe thấy) — điểm ngữ pháp HSK 2.', '[["Động từ"],["到","key"],["Tân ngữ"]]', '["Người Việt hay ","BỎ 到 sau 看、听、找",". 到 chỉ kết quả đạt được: 看到了 (thấy rồi), 找到了 (tìm thấy rồi)."]', '[{"hz":"我看到了那只猫。","py":"wǒ kàndào le nà zhī māo.","vi":"Tôi thấy con mèo đó rồi."},{"hz":"你找到了吗？","py":"nǐ zhǎodào le ma?","vi":"Bạn tìm thấy chưa?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-wan', 'HSK 2', 41, 'BỔ NGỮ KẾT QUẢ 完 (XONG)', '完', 'bi', 'Bổ ngữ kết quả 完 (xong) — điểm ngữ pháp HSK 2.', '[["Động từ"],["完","key"],["Tân ngữ + 了"]]', '["Người Việt hay ","DÙNG 了 mà quên 完 khi nhấn mạnh làm xong hết",". 完 = làm xong trọn vẹn: 吃完了 (ăn xong rồi)."]', '[{"hz":"我做完作业了。","py":"wǒ zuòwán zuòyè le.","vi":"Tôi làm xong bài tập rồi."},{"hz":"他吃完了两个苹果。","py":"tā chīwán le liǎng gè píngguǒ.","vi":"Anh ấy ăn xong hai quả táo."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-hao', 'HSK 2', 42, 'BỔ NGỮ KẾT QUẢ 好 (XONG, TỐT ĐẸP)', '好', 'bi', 'Bổ ngữ kết quả 好 (xong, tốt đẹp) — điểm ngữ pháp HSK 2.', '[["Động từ"],["好","key"],["Tân ngữ + 了"]]', '["Người Việt hay ","NHẦM 好 với 完",". 好 nhấn mạnh kết quả hoàn chỉnh, sẵn sàng: 准备好了 (chuẩn bị xong rồi)."]', '[{"hz":"我准备好了。","py":"wǒ zhǔnbèi hǎo le.","vi":"Tôi chuẩn bị xong rồi."},{"hz":"饭做好了。","py":"fàn zuò hǎo le.","vi":"Cơm nấu xong rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-lai-/-qu', 'HSK 2', 43, 'BỔ NGỮ PHƯƠNG HƯỚNG 来 / 去', '来 / 去', 'bi', 'Bổ ngữ phương hướng 来 / 去 — điểm ngữ pháp HSK 2.', '[["Động từ"],["上 / 下 / 进 / 出"],["来 / 去","key"]]', '["Người Việt hay ","ĐẶT 来/去 TRƯỚC động từ khi nói hướng vận động",". 来 = về phía người nói, 去 = ra xa: 进来 (đi vào đây), 上去 (đi lên đó)."]', '[{"hz":"快进来！","py":"kuài jìnlái!","vi":"Vào đây mau!"},{"hz":"他把书拿去了。","py":"tā bǎ shū ná qù le.","vi":"Anh ấy mang cuốn sách đi rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-de-2', 'HSK 2', 44, 'BỔ NGỮ TRẠNG THÁI 得 (LÀM TỐT / XẤU)', '得', 'bi', 'Bổ ngữ trạng thái 得 (làm tốt / xấu) — điểm ngữ pháp HSK 2.', '[["Động từ"],["得","key"],["Tính từ / cụm trạng thái"]]', '["Người Việt hay ","DÙNG 很 TRƯỚC động từ thay vì 得 sau động từ",". Nhận xét cách làm dùng động từ + 得 + tính từ: 说得很好."]', '[{"hz":"他说得很快。","py":"tā shuō de hěn kuài.","vi":"Anh ấy nói rất nhanh."},{"hz":"你写得真好！","py":"nǐ xiě de zhēn hǎo!","vi":"Bạn viết hay thật!"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-de-/-bu', 'HSK 2', 45, 'BỔ NGỮ KHẢ NĂNG (V ĐƯỢC / KHÔNG ĐƯỢC)', '得 / 不', 'bi', 'Bổ ngữ khả năng (v được / không được) — điểm ngữ pháp HSK 2.', '[["Động từ"],["得 / 不","key"],["Kết quả / bổ ngữ"]]', '["Người Việt hay ","ĐẶT 能 TRƯỚC động từ thay vì chèn 得/不 vào giữa",". Khả năng hoàn thành chèn vào sau động từ: 看得见 (nhìn thấy được), 看不见 (không nhìn thấy)."]', '[{"hz":"我听不懂。","py":"wǒ tīng bù dǒng.","vi":"Tôi nghe không hiểu."},{"hz":"太远了，走不到。","py":"tài yuǎn le, zǒu bù dào.","vi":"Xa quá, đi không tới."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-ge', 'HSK 2', 46, '量 TỪ 个 (CÁI, ĐẾM VẬT CHUNG)', '个', 'hutu', '量 từ 个 (cái, đếm vật chung) — điểm ngữ pháp HSK 2.', '[["Số từ"],["个","key"],["Danh từ"]]', '["Người Việt hay ","BỎ lượng từ như tiếng Việt khi đếm",". Tiếng Trung bắt buộc có lượng từ: 三个学生, không nói 三学生."]', '[{"hz":"我有三个弟弟。","py":"wǒ yǒu sān gè dìdi.","vi":"Tôi có ba người em trai."},{"hz":"请给我一个苹果。","py":"qǐng gěi wǒ yī gè píngguǒ.","vi":"Xin cho tôi một quả táo."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-ben-/-zhang-/-bei-/-jian', 'HSK 2', 47, 'LƯỢNG TỪ CHỈ ĐỒ DÙNG (本 / 张 / 杯 / 件)', '本 / 张 / 杯 / 件', 'hutu', 'Lượng từ chỉ đồ dùng (本 / 张 / 杯 / 件) — điểm ngữ pháp HSK 2.', '[["Số từ"],["本 / 张 / 杯 / 件","key"],["Danh từ"]]', '["Người Việt hay ","DÙNG 个 CHO MỌI THỨ",". Sách dùng 本, giấy và bàn dùng 张, đồ uống dùng 杯, quần áo dùng 件."]', '[{"hz":"我要买两本书。","py":"wǒ yào mǎi liǎng běn shū.","vi":"Tôi muốn mua hai cuốn sách."},{"hz":"请给我一杯水。","py":"qǐng gěi wǒ yī bēi shuǐ.","vi":"Xin cho tôi một cốc nước."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-ji-/-duo-shao', 'HSK 2', 48, '几 VÀ 多少 (HỎI SỐ)', '几 / 多少', 'hutu', '几 và 多少 (hỏi số) — điểm ngữ pháp HSK 2.', '[["几 / 多少","key"],["Lượng từ"],["Danh từ ?"]]', '["Người Việt hay ","DÙNG 多少 CHO SỐ NHỎ khi 几 mới đúng",". 几 cho số dưới mười và phải có lượng từ: 几个\u003b 多少 thì tự do hơn."]', '[{"hz":"你家有几口人？","py":"nǐ jiā yǒu jǐ kǒu rén?","vi":"Nhà bạn có mấy người?"},{"hz":"这个多少钱？","py":"zhège duōshao qián?","vi":"Cái này bao nhiêu tiền?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-liang', 'HSK 2', 49, '两 VÀ 二 (SỐ HAI)', '两', 'hutu', '两 và 二 (số hai) — điểm ngữ pháp HSK 2.', '[["两","key"],["Lượng từ"],["Danh từ"]]', '["Người Việt hay ","DÙNG 二 trước lượng từ khi phải dùng 两",". Đếm trong dãy số dùng 二, đếm đồ vật dùng 两: 两个人, 二号."]', '[{"hz":"我们班有二十个学生。","py":"wǒmen bān yǒu èrshí gè xuésheng.","vi":"Lớp chúng tôi có hai mươi học sinh."},{"hz":"我要两杯茶。","py":"wǒ yào liǎng bēi chá.","vi":"Tôi muốn hai cốc trà."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-dian', 'HSK 2', 50, 'NÓI GIỜ (点, 半, 刻, 分)', '点', 'hutu', 'Nói giờ (点, 半, 刻, 分) — điểm ngữ pháp HSK 2.', '[["Số"],["点","key"],["半 / 刻 / 分"]]', '["Người Việt hay ","DÙNG 个 trước 点 hoặc nhầm 半 với 一半",". Giờ dùng 点, 三点半 là ba rưỡi, 一刻 là mười lăm phút."]', '[{"hz":"现在三点半。","py":"xiànzài sān diǎn bàn.","vi":"Bây giờ là ba rưỡi."},{"hz":"我们八点上课。","py":"wǒmen bā diǎn shàngkè.","vi":"Tám giờ chúng ta học."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-ri', 'HSK 2', 51, 'THỨ TỰ THỜI GIAN (NĂM - THÁNG - NGÀY - GIỜ)', '日', 'hutu', 'Thứ tự thời gian (năm - tháng - ngày - giờ) — điểm ngữ pháp HSK 2.', '[["Năm"],["Tháng"],["日","key"],["Giờ"]]', '["Người Việt hay ","XẾP THỜI GIAN NHỎ TRƯỚC LỚN như tiếng Việt",". Tiếng Trung xếp từ lớn đến nhỏ: năm, tháng, ngày, giờ, phút."]', '[{"hz":"十月一日是我的生日。","py":"shí yuè yī rì shì wǒ de shēngrì.","vi":"Ngày mùng một tháng mười là sinh nhật tôi."},{"hz":"他是二月来的中国。","py":"tā shì èr yuè lái de zhōngguó.","vi":"Anh ấy đến Trung Quốc vào tháng hai."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-de-shi-hou', 'HSK 2', 52, '...的时候 (KHI, LÚC)', '的时候', 'hutu', '...的时候 (khi, lúc) — điểm ngữ pháp HSK 2.', '[["Mệnh đề"],["的时候","key"],["Mệnh đề chính"]]', '["Người Việt hay ","DÙNG 时间 thay vì 时候 khi nói về lúc xảy ra việc",". 时间 = khoảng thời gian\u003b 时候 = lúc nào đó: 上课的时候 (lúc đang học)."]', '[{"hz":"上课的时候不要说话。","py":"shàngkè de shíhou bùyào shuōhuà.","vi":"Lúc học bài đừng nói chuyện."},{"hz":"我小的时候很喜欢游泳。","py":"wǒ xiǎo de shíhou hěn xǐhuan yóuyǒng.","vi":"Lúc nhỏ tôi rất thích bơi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-yi-qian-/-yi-hou', 'HSK 2', 53, '以前 / 以后 (TRƯỚC / SAU)', '以前 / 以后', 'hutu', '以前 / 以后 (trước / sau) — điểm ngữ pháp HSK 2.', '[["Mệnh đề / danh từ"],["以前 / 以后","key"],["Mệnh đề chính"]]', '["Người Việt hay ","ĐẢO NGƯỢC TRẬT TỰ mệnh đề với 以前/以后",". Mệnh đề điều kiện đứng trước, 以前/以后 đứng sau nó: 下课以后 (sau giờ học)."]', '[{"hz":"下课以后我们去吃饭。","py":"xià kè yǐhòu wǒmen qù chīfàn.","vi":"Sau giờ học chúng ta đi ăn."},{"hz":"来中国以前我不会说汉语。","py":"lái zhōngguó yǐqián wǒ bù huì shuō hànyǔ.","vi":"Trước khi sang Trung Quốc tôi không biết nói tiếng Trung."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-yi-bian', 'HSK 2', 54, '一边...一边... (VỪA... VỪA...)', '一边', 'hutu', '一边...一边... (vừa... vừa...) — điểm ngữ pháp HSK 2.', '[["一边","key"],["Động từ 1"],["一边"],["Động từ 2"]]', '["Người Việt hay ","CHỈ DÙNG MỘT 边 hoặc thêm 了 vào các động từ",". Cả hai vế phải có 边 và không dùng 了: 他一边吃饭一边看书."]', '[{"hz":"他一边吃饭一边看书。","py":"tā yībiān chīfàn yībiān kànshū.","vi":"Anh ấy vừa ăn cơm vừa đọc sách."},{"hz":"我们一边走一边说。","py":"wǒmen yībiān zǒu yībiān shuō.","vi":"Chúng ta vừa đi vừa nói."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-yin-wei', 'HSK 2', 55, '因为...所以... (VÌ... NÊN...)', '因为', 'hutu', '因为...所以... (vì... nên...) — điểm ngữ pháp HSK 2.', '[["因为","key"],["Nguyên nhân"],["所以"],["Kết quả"]]', '["Người Việt hay ","ĐẶT SAI THỨ TỰ: kết quả trước nguyên nhân",". Nguyên nhân đi sau 因为, kết quả đi sau 所以."]', '[{"hz":"因为下雨，所以我在家。","py":"yīnwèi xià yǔ, suǒyǐ wǒ zài jiā.","vi":"Vì trời mưa nên tôi ở nhà."},{"hz":"因为他很忙，所以没来。","py":"yīnwèi tā hěn máng, suǒyǐ méi lái.","vi":"Vì anh ấy bận nên không đến."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-sui-ran', 'HSK 2', 56, '虽然...但是... (TUY... NHƯNG...)', '虽然', 'hutu', '虽然...但是... (tuy... nhưng...) — điểm ngữ pháp HSK 2.', '[["虽然","key"],["Mệnh đề nhượng bộ"],["但是"],["Mệnh đề chính"]]', '["Người Việt hay ","THÊM 但是 ở cả HAI vế hoặc dùng thêm 可笑 nhầm 可是",". Chỉ một 但是/可是 ở vế sau: 虽然贵，但是很好."]', '[{"hz":"虽然贵，但是很好。","py":"suīrán guì, dànshì hěn hǎo.","vi":"Tuy đắt nhưng rất tốt."},{"hz":"虽然他很小，但是跑得很快。","py":"suīrán tā hěn xiǎo, dànshì pǎo de hěn kuài.","vi":"Tuy anh ấy bé nhưng chạy rất nhanh."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-you-dian-er-/-yi-dian-er', 'HSK 2', 57, '一点儿 VÀ 有点儿 (MỘT CHÚT)', '有点儿 / 一点儿', 'hutu', '一点儿 và 有点儿 (một chút) — điểm ngữ pháp HSK 2.', '[["Tính từ / danh từ"],["有点儿 / 一点儿","key"],["Phần còn lại"]]', '["Người Việt hay ","ĐẢO NGƯỢC vị trí: 有点儿 đứng TRƯỚC tính từ không mong muốn, 一点儿 đứng SAU động từ",". 有点儿累 (hơi mệt), 想喝一点儿水."]', '[{"hz":"今天有点儿冷。","py":"jīntiān yǒudiǎnr lěng.","vi":"Hôm nay hơi lạnh."},{"hz":"请说慢一点儿。","py":"qǐng shuō màn yīdiǎnr.","vi":"Xin nói chậm một chút."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-zen-me-/-zen-me-yang', 'HSK 2', 58, '怎么 VÀ 怎么样 (THẾ NÀO)', '怎么 / 怎么样', 'hutu', '怎么 và 怎么样 (thế nào) — điểm ngữ pháp HSK 2.', '[["你"],["怎么 / 怎么样","key"],["?"]]', '["Người Việt hay ","DÙNG 怎么样 để hỏi CÁCH LÀM thay vì 怎么",". 怎么 hỏi cách làm: 怎么去？\u003b 怎么样 hỏi tình trạng: 你怎么样？"]', '[{"hz":"这个字怎么读？","py":"zhège zì zěnme dú?","vi":"Chữ này đọc thế nào?"},{"hz":"今天天气怎么样？","py":"jīntiān tiānqì zěnmeyàng?","vi":"Thời tiết hôm nay thế nào?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk2-shi', 'HSK 2', 59, '是...的 (NHẤN MẠNH THÔNG TIN ĐÃ XẢY RA)', '是', 'hutu', '是...的 (nhấn mạnh thông tin đã xảy ra) — điểm ngữ pháp HSK 2.', '[["Chủ ngữ"],["是","key"],["Thời gian / nơi / cách"],["Động từ"],["的"]]', '["Người Việt hay ","DÙNG 是...的 cho việc CHƯA xảy ra hoặc đang diễn ra",". Cấu trúc này chỉ nhấn mạnh chi tiết việc đã làm xong: 我是昨天来的."]', '[{"hz":"我是昨天来的。","py":"wǒ shì zuótiān lái de.","vi":"Tôi đến vào hôm qua (nhấn mạnh thời gian)."},{"hz":"他是坐火车去的。","py":"tā shì zuò huǒchē qù de.","vi":"Anh ấy đi bằng tàu hỏa (nhấn mạnh cách đi)."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-ba', 'HSK 3', 0, 'CÂU 把 – LÀM THAY ĐỔI VỊ TRÍ HOẶC TRẠNG THÁI CỦA TÂN NGỮ', '把', 'ba', 'Câu 把 – làm thay đổi vị trí hoặc trạng thái của tân ngữ — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["把","key"],["tân ngữ xác định"],["động từ"],["bổ ngữ / 了 / 在 / 到 / 给…"]]', '["Người Việt dịch theo trật tự tiếng Việt nên viết ","‘我写把作业’ hoặc ‘我把作业做’ thiếu thành phần sau động từ",". Đúng phải là ‘我把作业做完了’: tân ngữ phải xác định, sau động từ bắt buộc có bổ ngữ hoặc 了."]', '[{"hz":"我把作业做完了。","py":"wǒ bǎ zuòyè zuò wán le.","vi":"Tôi đã làm xong bài tập."},{"hz":"请把门关上。","py":"qǐng bǎ mén guān shàng.","vi":"Làm ơn đóng cửa lại."},{"hz":"我把书放在桌子上了。","py":"wǒ bǎ shū fàng zài zhuōzi shàng le.","vi":"Tôi đã đặt sách lên bàn."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-bei', 'HSK 3', 1, 'CÂU 被 – CÂU BỊ ĐỘNG (BỊ AI/CÁI GÌ LÀM CHO)', '被', 'ba', 'Câu 被 – câu bị động (bị ai/cái gì làm cho) — điểm ngữ pháp HSK 3.', '[["chủ ngữ (bị tác động)"],["被","key"],["người/vật tác động (có thể bỏ)"],["động từ"],["bổ ngữ / 了"]]', '["Người Việt hay quên rằng sau động từ của câu 被 ","thường phải có bổ ngữ hoặc 了 để chỉ kết quả đã xảy ra",", ví dụ ‘杯子被我打破了’, không nói ‘杯子被我打’."]', '[{"hz":"我的自行车被朋友借走了。","py":"wǒ de zìxíngchē bèi péngyou jiè zǒu le.","vi":"Chiếc xe đạp của tôi bị bạn mượn mất."},{"hz":"蛋糕都被我们吃了。","py":"dàngāo dōu bèi wǒmen chī le.","vi":"Bánh ngọt đều bị chúng tôi ăn hết rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-shi', 'HSK 3', 2, 'CÂU 是…的 – NHẤN MẠNH THÔNG TIN CỦA HÀNH ĐỘNG ĐÃ XẢY RA', '是', 'ba', 'Câu 是…的 – nhấn mạnh thông tin của hành động đã xảy ra — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["是","key"],["thời gian / nơi chốn / cách thức"],["động từ"],["的"]]', '["Nhiều người chỉ dùng 了 hoặc quên từ cuối: ","khi giải thích ‘khi nào, ở đâu, bằng gì’ của việc đã xong phải dùng 是…的",", ví dụ ‘我是坐飞机来的’, ‘他是什么时候走的?’."]', '[{"hz":"我是坐飞机来中国的。","py":"wǒ shì zuò fēijī lái Zhōngguó de.","vi":"Tôi đến Trung Quốc bằng máy bay."},{"hz":"他是什么时候走的？","py":"tā shì shénme shíhou zǒu de?","vi":"Cậu ấy đi lúc nào thế?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-qing', 'HSK 3', 3, 'CÂU 兼语 – 请/让/叫 AI LÀM GÌ', '请', 'ba', 'Câu 兼语 – 请/让/叫 ai làm gì — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["请","key"],["người (vừa là tân ngữ, vừa là chủ ngữ hai)"],["động từ"],["tân ngữ / thành phần khác (让/叫 cùng loại)"]]', '["Người Việt hay thêm 在 trước động từ thứ hai hoặc đảo trật tự: ","người đứng sau 请/让/叫 đồng thời là chủ ngữ của động từ phía sau",", ví dụ ‘妈妈让弟弟快点儿睡觉’, không nói ‘妈妈让睡觉弟弟’."]', '[{"hz":"老师请我们回答问题。","py":"lǎoshī qǐng wǒmen huídá wèntí.","vi":"Cô giáo mời chúng tôi trả lời câu hỏi."},{"hz":"妈妈让弟弟快点儿睡觉。","py":"māma ràng dìdi kuài diǎnr shuìjiào.","vi":"Mẹ bảo em trai nhanh đi ngủ."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-lian', 'HSK 3', 4, '连…都/也 – THẬM CHÍ CẢ… CŨNG', '连', 'ba', '连…都/也 – thậm chí cả… cũng — điểm ngữ pháp HSK 3.', '[["连 + tân ngữ / chủ ngữ nhấn mạnh"],["连","key"],["…"],["都 / 也"],["phần còn lại"]]', '["Người Việt thường bỏ 连 và chỉ dùng 都/也: ","‘连他都不知道这个问题’ – thậm chí anh ấy cũng không biết","\u003b 连…都/也 đi cặp, 都/也 phải đứng trước động từ phủ định."]', '[{"hz":"他连自己的电话号码都忘了。","py":"tā lián zìjǐ de diànhuà hàomǎ dōu wàng le.","vi":"Nó thậm chí quên cả số điện thoại của mình."},{"hz":"她忙得连饭都没吃。","py":"tā máng de lián fàn dōu méi chī.","vi":"Cô ấy bận đến mức cơm cũng không ăn."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-chu', 'HSK 3', 5, '除了…以外 – NGOÀI… RA (NGOẠI TRỪ HAY THÊM VÀO)', '除', 'ba', '除了…以外 – ngoài… ra (ngoại trừ hay thêm vào) — điểm ngữ pháp HSK 3.', '[["除了…以外"],["除","key"],["…以外"],["还 / 都 (hoặc không có)"],["phần còn lại"]]', '["Người Việt hay nhầm hai nghĩa: ","除了…以外 + 还/都 = ngoài ra còn, không có 还/都 = ngoại trừ",": ‘除了他，我们都去’ là trừ anh ấy\u003b ‘除了他还去’ là ngoài anh ấy ra cũng đi."]', '[{"hz":"除了英语以外，他还学习汉语。","py":"chúle Yīngyǔ yǐwài, tā hái xuéxí Hànyǔ.","vi":"Ngoài tiếng Anh ra, anh ấy còn học tiếng Trung."},{"hz":"除了星期天，我每天上班。","py":"chúle Xīngqītiān, wǒ měitiān shàngbān.","vi":"Ngoại trừ chủ nhật, ngày nào tôi cũng đi làm."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-bian', 'HSK 3', 6, '一边…一边 – VỪA… VỪA (HAI HÀNH ĐỘNG CÙNG LÚC)', '边', 'ba', '一边…一边 – vừa… vừa (hai hành động cùng lúc) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["边","key"],["一边 + động từ 1"],["一边"],["động từ 2"]]', '["Người Việt thường dùng cho hai hành động nối tiếp nhau: ","一边…一边 chỉ dùng cho hai hành động diễn ra đồng thời",", ví dụ ‘他一边吃饭一边看电视’\u003b việc nối tiếp dùng 先…然后."]', '[{"hz":"我喜欢一边喝咖啡一边看书。","py":"wǒ xǐhuan yìbiān hē kāfēi yìbiān kàn shū.","vi":"Tôi thích vừa uống cà phê vừa đọc sách."},{"hz":"她一边听音乐一边做作业。","py":"tā yìbiān tīng yīnyuè yìbiān zuò zuòyè.","vi":"Cô ấy vừa nghe nhạc vừa làm bài tập."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-yue', 'HSK 3', 7, '越…越 – CÀNG… CÀNG (MỨC ĐỘ TĂNG DẦN)', '越', 'ba', '越…越 – càng… càng (mức độ tăng dần) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["越","key"],["động từ / tình huống 1"],["越"],["tính từ / trạng thái 2"]]', '["Người Việt hay bỏ 越 thứ hai hoặc dùng sai vị trí 了: ","‘他越跑越快’ – càng chạy càng nhanh, ‘越来越忙了’ chỉ khi nói chung","\u003b 越…越 nhấn mức độ thay đổi theo tiến trình."]', '[{"hz":"天气越来越冷了。","py":"tiānqì yuèláiyuè lěng le.","vi":"Thời tiết ngày càng lạnh."},{"hz":"他越说越高兴。","py":"tā yuè shuō yuè gāoxìng.","vi":"Nó càng nói càng vui."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-you', 'HSK 3', 8, '又…又 – VỪA… VỪA (HAI TÍNH CHẤT CÙNG CÓ)', '又', 'ba', '又…又 – vừa… vừa (hai tính chất cùng có) — điểm ngữ pháp HSK 3.', '[["chủ ngữ / danh ngữ"],["又","key"],["tính từ / động từ 1"],["又"],["tính từ / động từ 2"]]', '["Người Việt hay nhầm 又…又 (miêu tả hai tính chất) với 一边…一边 (hai hành động): ","‘这个苹果又大又甜’ miêu tả, không phải hành động","\u003b 又…又 không nối hai hành động nối tiếp."]', '[{"hz":"这个房间又干净又漂亮。","py":"zhège fángjiān yòu gānjìng yòu piàoliang.","vi":"Căn phòng này vừa sạch vừa đẹp."},{"hz":"他又说又笑，很高兴。","py":"tā yòu shuō yòu xiào, hěn gāoxìng.","vi":"Nó vừa nói vừa cười, vui lắm."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-kuai', 'HSK 3', 9, '快…了 – SẮP… RỒI (SỰ KIỆN SẮP XẢY RA)', '快', 'ba', '快…了 – sắp… rồi (sự kiện sắp xảy ra) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["快","key"],["động từ / tính từ"],["了"],[""]]', '["Người Việt hay đặt 快 sau động từ hoặc quên 了: ","快 phải đứng trước động từ/tính từ và 了 ở cuối là bắt buộc",", ví dụ ‘快下雨了’, ‘火车快到了’."]', '[{"hz":"快下课了，我们走吧。","py":"kuài xiàkè le, wǒmen zǒu ba.","vi":"Sắp tan học rồi, mình đi thôi."},{"hz":"火车快到了。","py":"huǒchē kuài dào le.","vi":"Tàu sắp đến rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-yao', 'HSK 3', 10, '要…了 – SẮP… RỒI (KHÁC VỚI 要 = MUỐN)', '要', 'ba', '要…了 – sắp… rồi (khác với 要 = muốn) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["要","key"],["động từ"],["了"],["(快要…了 / 就要…了 nhấn mạnh hơn)"]]', '["Người Việt hay nhầm ‘要…了’ nghĩa ‘sắp’ với nghĩa ‘muốn’: ","‘他要去北京了’ = sắp đi Bắc Kinh rồi",", còn không có 了 thì ‘他要去北京’ = anh ấy muốn đi Bắc Kinh."]', '[{"hz":"天要黑了，快回家吧。","py":"tiān yào hēi le, kuài huí jiā ba.","vi":"Trời sắp tối rồi, nhanh về nhà đi."},{"hz":"我要毕业了。","py":"wǒ yào bìyè le.","vi":"Tôi sắp tốt nghiệp rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-yi', 'HSK 3', 11, '一…就 – VỪA… LÀ NGAY', '一', 'ba', '一…就 – vừa… là ngay — điểm ngữ pháp HSK 3.', '[["chủ ngữ 1"],["一","key"],["động từ 1"],["就"],["động từ 2 (xảy ra ngay sau)"]]', '["Người Việt hay bỏ 一 hoặc thêm 了 sau động từ đầu: ","‘他一回家就睡觉’ – vừa về nhà là đi ngủ ngay","\u003b 一…就 nhấn hành động hai xảy ra ngay lập tức."]', '[{"hz":"我一到北京就给你打电话。","py":"wǒ yí dào Běijīng jiù gěi nǐ dǎ diànhuà.","vi":"Tôi vừa đến Bắc Kinh là gọi điện cho bạn ngay."},{"hz":"他一听音乐就想跳舞。","py":"tā yì tīng yīnyuè jiù xiǎng tiàowǔ.","vi":"Nó vừa nghe nhạc là muốn nhảy ngay."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-yin', 'HSK 3', 12, '因为…所以 – VÌ… NÊN', '因', 'ba', '因为…所以 – vì… nên — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["因","key"],["为 + nguyên nhân"],["所以"],["kết quả"]]', '["Người Việt hay lặp chủ ngữ hai lần hoặc trộn với 但是: ","‘因为下雨，所以我不去’ – vì mưa nên tôi không đi","\u003b khi cùng một chủ ngữ, đặt chủ ngữ trước 因为, mệnh đề 因为 không lặp chủ ngữ."]', '[{"hz":"因为天气不好，所以我们没去公园。","py":"yīnwèi tiānqì bù hǎo, suǒyǐ wǒmen méi qù gōngyuán.","vi":"Vì thời tiết không tốt nên chúng tôi không đi công viên."},{"hz":"他因为生病没来上课。","py":"tā yīnwèi shēngbìng méi lái shàngkè.","vi":"Nó vì ốm nên không đến học."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-sui', 'HSK 3', 13, '虽然…但是 – TUY… NHƯNG (HAI TỪ PHẢI ĐI CẶP)', '虽', 'ba', '虽然…但是 – tuy… nhưng (hai từ phải đi cặp) — điểm ngữ pháp HSK 3.', '[["虽","key"],["然 + mệnh đề nhượng bộ"],["但是 / 可是"],["mệnh đề chính"],[""]]', '["Người Việt hay bỏ 但是 phía sau: ","虽然 và 但是 phải đi cùng nhau trong một câu",", ví dụ ‘虽然很难，但是我想学’\u003b không nói ‘虽然很难，我想学’ mang màu văn nói không tự nhiên."]', '[{"hz":"虽然房子小，但是很干净。","py":"suīrán fángzi xiǎo, dànshì hěn gānjìng.","vi":"Tuy nhà nhỏ nhưng rất sạch."},{"hz":"虽然他很小，可是跑得很快。","py":"suīrán tā hěn xiǎo, kěshì pǎo de hěn kuài.","vi":"Tuy nó nhỏ tuổi nhưng chạy nhanh lắm."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-dao', 'HSK 3', 14, '结果补语 到 – THẤY, NGHE THẤY, TÌM ĐƯỢC, MUA ĐƯỢC', '到', 'bi', '结果补语 到 – thấy, nghe thấy, tìm được, mua được — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["động từ"],["到","key"],["tân ngữ / 了"],[""]]', '["Người Việt hay bỏ 到 sau động từ: ","到 chỉ kết quả đạt được: 看到看见, 听到 nghe thấy, 找到 tìm thấy, 买到 mua được","\u003b ‘我看见他了’ khác ‘我看着他’ (tôi đang nhìn anh ấy)."]', '[{"hz":"我找到工作了。","py":"wǒ zhǎodào gōngzuò le.","vi":"Tôi đã tìm được việc rồi."},{"hz":"你听到那个消息了吗？","py":"nǐ tīngdào nàge xiāoxi le ma?","vi":"Bạn có nghe thấy tin đó không?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-wan', 'HSK 3', 15, '结果补语 完 – LÀM XONG, HOÀN THÀNH', '完', 'bi', '结果补语 完 – làm xong, hoàn thành — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["động từ"],["完","key"],["tân ngữ / 了"],[""]]', '["Người Việt hay dùng 了 thay cho 完: ","完 đứng sau động từ, trước tân ngữ: ‘我吃完饭了’","\u003b không nói ‘我吃完饭了’ thành ‘我吃完了饭’ khi tân ngữ là danh từ thông thường."]', '[{"hz":"我写完信就去睡觉。","py":"wǒ xiě wán xìn jiù qù shuìjiào.","vi":"Tôi viết xong thư là đi ngủ."},{"hz":"你做完作业了吗？","py":"nǐ zuò wán zuòyè le ma?","vi":"Bạn làm xong bài tập chưa?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-hao', 'HSK 3', 16, '结果补语 好 – LÀM XONG VÀ HOÀN HẢO, SẴN SÀNG', '好', 'bi', '结果补语 好 – làm xong và hoàn hảo, sẵn sàng — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["động từ"],["好","key"],["tân ngữ / 了"],[""]]', '["Người Việt hay nhầm 好 với 完: ","好 mang thêm nghĩa kết quả hoàn hảo, sẵn sàng dùng được",": ‘准备好了’ là chuẩn bị xong và sẵn sàng, ‘准备完了’ chỉ nói hoàn thành."]', '[{"hz":"饭做好了，快来吃吧。","py":"fàn zuò hǎo le, kuài lái chī ba.","vi":"Cơm nấu xong rồi, mau đến ăn đi."},{"hz":"我把房间收拾好了。","py":"wǒ bǎ fángjiān shōushi hǎo le.","vi":"Tôi đã dọn phòng gọn gàng rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-cuo', 'HSK 3', 17, '结果补语 错/懂/见 – LÀM SAI, HIỂU, THẤY', '错', 'bi', '结果补语 错/懂/见 – làm sai, hiểu, thấy — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["động từ"],["错","key"],["tân ngữ / 了"],["(懂, 见, 倒… cùng loại)"]]', '["Người Việt hay sai vị trí bổ ngữ kết quả: ","错/懂/见 đứng ngay sau động từ, trước tân ngữ: ‘我写错了一个字’",", không nói ‘我错了写一个字’."]', '[{"hz":"对不起，我说错了。","py":"duìbuqǐ, wǒ shuō cuò le.","vi":"Xin lỗi, tôi nói sai rồi."},{"hz":"这个问题我听懂了。","py":"zhège wèntí wǒ tīng dǒng le.","vi":"Câu hỏi này tôi nghe hiểu rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-lai', 'HSK 3', 18, '趋向补语 来/去 – HÀNH ĐỘNG HƯỚNG VỀ HOẶC RA KHỎI NGƯỜI NÓI', '来', 'bi', '趋向补语 来/去 – hành động hướng về hoặc ra khỏi người nói — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["động từ"],["来","key"],["tân ngữ nơi chốn / 了"],[""]]', '["Người Việt hay đặt nơi chốn giữa động từ và 来/去: ","‘他走进教室来’ đúng, ‘他进来教室’ sai","\u003b 来 = hướng về người nói, 去 = hướng đi xa người nói."]', '[{"hz":"他拿来了两瓶水。","py":"tā ná lái le liǎng píng shuǐ.","vi":"Cậu ấy mang tới hai chai nước."},{"hz":"你把我的书带去吧。","py":"nǐ bǎ wǒ de shū dài qù ba.","vi":"Bạn mang cuốn sách của tôi đi nhé."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-shang', 'HSK 3', 19, '趋向补语 上/下/进/出 – LÊN, XUỐNG, VÀO, RA', '上', 'bi', '趋向补语 上/下/进/出 – lên, xuống, vào, ra — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["động từ"],["上","key"],["nơi chốn + 来/去"],[""]]', '["Người Việt hay dùng 到 thay cho 上/下/进/出: ","这些趋向补语 chỉ hướng lên/xuống/vào/ra: 跑上去, 拿下来, 开进来",", thường kèm 来/去 ở cuối."]', '[{"hz":"他跑上去了。","py":"tā pǎo shàngqù le.","vi":"Nó chạy lên rồi."},{"hz":"请把车开进来。","py":"qǐng bǎ chē kāi jìnlái.","vi":"Xin hãy lái xe vào trong."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-qi', 'HSK 3', 20, '趋向补语复合 起来 – NHÌN VÀO THÌ… / NHỚ RA', '起', 'bi', '趋向补语复合 起来 – nhìn vào thì… / nhớ ra — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["động từ"],["起","key"],["来"],["(nhận xét / 了)"]]', '["Người Việt hay nhầm các nghĩa của 起来: ","‘看起来’ = nhìn vào thì, xem ra\u003b ‘想起来’ = nhớ ra\u003b ‘站起来’ = đứng dậy",", ba nghĩa này phải phân biệt theo động từ trước nó."]', '[{"hz":"这个房子看起来很新。","py":"zhège fángzi kàn qǐlái hěn xīn.","vi":"Cái nhà này nhìn vào thì rất mới."},{"hz":"我想起来了，他是小王。","py":"wǒ xiǎng qǐlái le, tā shì Xiǎo Wáng.","vi":"Tôi nhớ ra rồi, nó là Tiểu Vương."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-de', 'HSK 3', 21, '可能补语 得/不 – LÀM ĐƯỢC HAY KHÔNG LÀM ĐƯỢC (V + 得/不 + KẾT QUẢ)', '得', 'bi', '可能补语 得/不 – làm được hay không làm được (v + 得/不 + kết quả) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["得","key"],["kết quả / hướng (懂, 完, 上…)"],["hoặc: 不 + kết quả"],[""]]', '["Người Việt hay dùng 能 thay cho cấu trúc này: ","‘听不懂’ – nghe không hiểu, không nói ‘不能听懂’ khi nói năng lực hoàn thành","\u003b khẳng định là 听得懂, phủ định là 听不懂, hỏi là ‘听得懂吗?’."]', '[{"hz":"他说得太快，我听不懂。","py":"tā shuō de tài kuài, wǒ tīng bu dǒng.","vi":"Nó nói nhanh quá, tôi nghe không hiểu."},{"hz":"这么多饭，我吃不完。","py":"zhème duō fàn, wǒ chī bu wán.","vi":"Cơm nhiều thế này, tôi ăn không hết."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-bu-le', 'HSK 3', 22, '可能补语 不了 – KHÔNG THỂ TIẾP TỤC / KHÔNG XONG ĐƯỢC', '不了', 'bi', '可能补语 不了 – không thể tiếp tục / không xong được — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["động từ"],["不了","key"],["(tân ngữ)"],[""]]', '["Người Việt hay nói ‘不能做完了’ thay cho cấu trúc này: ","V + 不了 = làm không xong / không thể làm: ‘去不了’ đi không được",", khác 可能补语 ‘不完’ chỉ không hoàn thành được."]', '[{"hz":"今天我忙，去不了。","py":"jīntiān wǒ máng, qù bu liǎo.","vi":"Hôm nay tôi bận, đi không được."},{"hz":"这些菜我们吃不了。","py":"zhèxiē cài wǒmen chī bu liǎo.","vi":"Nhiều món thế này chúng tôi ăn không hết."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-de-2', 'HSK 3', 23, '程度补语 得 – LÀM (NHƯ THẾ NÀO) RẤT…', '得', 'bi', '程度补语 得 – làm (như thế nào) rất… — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["động từ"],["得","key"],["trạng ngữ mức độ (很, 太…了)"],[""]]', '["Người Việt hay đặt trạng từ trước động từ kiểu tiếng Việt: ","‘他跑得很快’ đúng, ‘他很快地跑’ không tự nhiên","\u003b thành phần chỉ mức độ phải đứng sau 得."]', '[{"hz":"她汉语说得很流利。","py":"tā Hànyǔ shuō de hěn liúlì.","vi":"Cô ấy nói tiếng Trung rất trôi chảy."},{"hz":"孩子们玩得很高兴。","py":"háizimen wán de hěn gāoxìng.","vi":"Bọn trẻ chơi rất vui."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-le', 'HSK 3', 24, '时量补语 – LÀM (BAO LÂU) + THỜI LƯỢNG', '了', 'bi', '时量补语 – làm (bao lâu) + thời lượng — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["động từ"],["了","key"],["thời lượng (分钟, 小时, 年…)"],["tân ngữ (nếu có)"]]', '["Người Việt hay đặt thời lượng trước tân ngữ như tiếng Việt: ","thời lượng đứng ngay sau động từ: ‘我学了两年汉语’",", không nói ‘我学了汉语两年’."]', '[{"hz":"我学了三年汉语了。","py":"wǒ xué le sān nián Hànyǔ le.","vi":"Tôi đã học tiếng Trung ba năm rồi."},{"hz":"他睡了八个小时。","py":"tā shuì le bā ge xiǎoshí.","vi":"Nó ngủ tám tiếng."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-bian-2', 'HSK 3', 25, '动量补语 次/遍 – LÀM (BAO NHIÊU LẦN)', '遍', 'bi', '动量补语 次/遍 – làm (bao nhiêu lần) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["động từ"],["遍","key"],["số từ + 次/遍"],["tân ngữ"]]', '["Người Việt hay dùng 次 cho mọi trường hợp: ","次 đếm lượt xảy ra, 遍 đếm lần làm trọn từ đầu đến cuối",": ‘他来过三次’ – đã đến ba lần, ‘我把课文读了两遍’ – đọc hai lượt."]', '[{"hz":"这个词我查过三次了。","py":"zhège cí wǒ chá guo sān cì le.","vi":"Từ này tôi đã tra ba lần rồi."},{"hz":"请把这句话再念一遍。","py":"qǐng bǎ zhè jù huà zài niàn yí biàn.","vi":"Xin hãy đọc lại câu này một lượt nữa."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-zai', 'HSK 3', 26, '补语 在/到/给 – ĐẶT Ở, GỬI ĐẾN, ĐƯA CHO', '在', 'bi', '补语 在/到/给 – đặt ở, gửi đến, đưa cho — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["động từ"],["在","key"],["nơi chốn / người nhận"],["(tân ngữ)"]]', '["Người Việt hay bỏ 在/到/给 hoặc đảo vị trí: ","giới từ này đứng sau động từ, trước nơi chốn hoặc người nhận",": ‘他把行李放在床上了’, ‘请把书还给我’."]', '[{"hz":"他把行李放在床上了。","py":"tā bǎ xíngli fàng zài chuáng shàng le.","vi":"Nó đặt hành lý lên giường."},{"hz":"我把座位让给老人了。","py":"wǒ bǎ zuòwèi ràng gěi lǎorén le.","vi":"Tôi nhường chỗ cho cụ già rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-le-2', 'HSK 3', 27, '了 (SAU ĐỘNG TỪ) – CHỈ HÀNH ĐỘNG ĐÃ HOÀN THÀNH', '了', 'bongu', '了 (sau động từ) – chỉ hành động đã hoàn thành — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["động từ"],["了","key"],["tân ngữ / thành phần khác"],[""]]', '["Người Việt hay gắn 了 sau mỗi động từ: ","phủ định dùng 没 và bỏ 了: ‘我昨天没买书’",", ‘我买了三本书’ – đã mua ba cuốn\u003b 了 chỉ hoàn thành trong câu khẳng định."]', '[{"hz":"他昨天看了两场电影。","py":"tā zuótiān kàn le liǎng chǎng diànyǐng.","vi":"Hôm qua nó xem hai bộ phim."},{"hz":"我上个月去了北京。","py":"wǒ shàng ge yuè qù le Běijīng.","vi":"Tháng trước tôi đã đi Bắc Kinh."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-le-3', 'HSK 3', 28, '了 (CUỐI CÂU) – TÌNH HÌNH MỚI THAY ĐỔI', '了', 'bongu', '了 (cuối câu) – tình hình mới thay đổi — điểm ngữ pháp HSK 3.', '[["chủ ngữ + vị ngữ"],["了","key"],["(đứng cuối câu)"],["…"],[""]]', '["Người Việt hay nhầm 了 cuối câu với 了 sau động từ: ","了 cuối câu báo tin mới, tình huống thay đổi: ‘下雨了’ – trời mưa rồi",", còn ‘下了一夜雨’ là mưa suốt một đêm (hoàn thành)."]', '[{"hz":"春天来了。","py":"chūntiān lái le.","vi":"Mùa xuân đến rồi."},{"hz":"我肚子疼了。","py":"wǒ dùzi téng le.","vi":"Bụng tôi đau rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-guo', 'HSK 3', 29, '过 – ĐÃ TỪNG (KINH NGHIỆM TRONG QUÁ KHỨ)', '过', 'bongu', '过 – đã từng (kinh nghiệm trong quá khứ) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["động từ"],["过","key"],["tân ngữ"],["(không có 了 ở cuối)"]]', '["Người Việt hay dùng 了 thay cho 过: ","‘我去过中国’ – đã từng đi (kinh nghiệm), ‘我去了中国’ – đã đi rồi","\u003b 过 chỉ kinh nghiệm từng trải, phủ định là 没去过."]', '[{"hz":"你吃过北京烤鸭吗？","py":"nǐ chī guo Běijīng kǎoyā ma?","vi":"Bạn đã từng ăn vịt quay Bắc Kinh chưa?"},{"hz":"我从来没见过这样的动物。","py":"wǒ cónglái méi jiànguo zhèyàng de dòngwù.","vi":"Tôi chưa bao giờ thấy con vật như vậy."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-zhe', 'HSK 3', 30, '着 – TRẠNG THÁI TIẾP DIỄN, DUY TRÌ', '着', 'bongu', '着 – trạng thái tiếp diễn, duy trì — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["động từ"],["着","key"],["(tân ngữ)"],["(mô tả trạng thái tồn tại)"]]', '["Người Việt hay nhầm 着 với 正在: ","‘门开着’ – cửa đang mở (trạng thái), ‘他在吃饭’ – đang ăn (hoạt động)","\u003b 着 mô tả trạng thái giữ nguyên: 穿着, 放着, 坐着."]', '[{"hz":"她穿着一件红色的毛衣。","py":"tā chuānzhe yí jiàn hóngsè de máoyī.","vi":"Cô ấy mặc một chiếc áo len màu đỏ."},{"hz":"桌子上放着很多书。","py":"zhuōzi shàng fàngzhe hěn duō shū.","vi":"Trên bàn để rất nhiều sách."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-zheng', 'HSK 3', 31, '正在/在…呢 – ĐANG (HÀNH ĐỘNG DIỄN RA LÚC NÓI)', '正', 'bongu', '正在/在…呢 – đang (hành động diễn ra lúc nói) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["正","key"],["在 + động từ"],["(tân ngữ)"],["呢 (có thể có)"]]', '["Người Việt hay thêm 了 cho hành động đang diễn ra: ","正在/在 đứng trước động từ, 呢 cuối câu, không dùng 了",": ‘妈妈正在做饭呢’ – mẹ đang nấu ăn."]', '[{"hz":"妈妈正在做饭呢。","py":"māma zhèngzài zuò fàn ne.","vi":"Mẹ đang nấu ăn."},{"hz":"别吵，孩子们在睡觉呢。","py":"bié chǎo, háizimen zài shuìjiào ne.","vi":"Đừng làm ồn, bọn trẻ đang ngủ."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-jiu', 'HSK 3', 32, '就 – SỚM, NGAY (THỜI GIAN SỚM HƠN DỰ KIẾN)', '就', 'bongu', '就 – sớm, ngay (thời gian sớm hơn dự kiến) — điểm ngữ pháp HSK 3.', '[["chủ ngữ / thời gian"],["就","key"],["động từ"],["(thành phần khác)"],[""]]', '["Người Việt hay nhầm 就 với 才: ","就 = sớm/nhanh hơn dự kiến: ‘他六点就起床了’ – sáu giờ đã dậy","\u003b 才 thì ngược lại, chỉ sự muộn."]', '[{"hz":"我明天就回来。","py":"wǒ míngtiān jiù huílái.","vi":"Ngày mai tôi sẽ về ngay."},{"hz":"他五分钟就做完了。","py":"tā wǔ fēnzhōng jiù zuò wán le.","vi":"Nó chỉ năm phút đã làm xong."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-cai', 'HSK 3', 33, '才 – MỚI, CHỈ (MUỘN HƠN DỰ KIẾN HOẶC SỐ LƯỢNG ÍT)', '才', 'bongu', '才 – mới, chỉ (muộn hơn dự kiến hoặc số lượng ít) — điểm ngữ pháp HSK 3.', '[["chủ ngữ / thời gian"],["才","key"],["động từ"],["(thành phần khác)"],[""]]', '["Người Việt hay nhầm 才 với 就: ","才 = muộn hơn dự kiến hoặc ít hơn nghĩ: ‘他八点才起床’",", ‘我才做了一半’ – tôi mới làm được nửa."]', '[{"hz":"他二十八岁才结婚。","py":"tā èrshíbā suì cái jiéhūn.","vi":"Nó hai tám tuổi mới kết hôn."},{"hz":"这道题太难，我才做了一半。","py":"zhè dào tí tài nán, wǒ cái zuò le yí bàn.","vi":"Bài này khó quá, tôi mới làm được nửa."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-you-2', 'HSK 3', 34, '又 – LẠI (LẶP LẠI ĐÃ XẢY RA HOẶC CHẮC CHẮN SẼ XẢY RA)', '又', 'bongu', '又 – lại (lặp lại đã xảy ra hoặc chắc chắn sẽ xảy ra) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["又","key"],["động từ"],["了 / thành phần khác"],[""]]', '["Người Việt hay dùng 又 cho tương lai: ","又 dùng cho việc lặp lại đã xảy ra: ‘他又迟到了’","\u003b hành động sẽ lặp lại trong tương lai dùng 再."]', '[{"hz":"他昨天又感冒了。","py":"tā zuótiān yòu gǎnmào le.","vi":"Hôm qua nó lại bị cảm."},{"hz":"你怎么又问这个问题？","py":"nǐ zěnme yòu wèn zhège wèntí?","vi":"Sao bạn lại hỏi câu này nữa?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-zai-2', 'HSK 3', 35, '再 – LẦN NỮA (LẶP LẠI TRONG TƯƠNG LAI)', '再', 'bongu', '再 – lần nữa (lặp lại trong tương lai) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["再","key"],["động từ"],["(tân ngữ / 一遍)"],[""]]', '["Người Việt hay dùng 又 cho tương lai: ","再 cho hành động sẽ lặp lại: ‘请你再说一遍’","\u003b 又 cho hành động đã lặp lại: ‘他又说了一遍’."]', '[{"hz":"太贵了，我不再买了。","py":"tài guì le, wǒ bú zài mǎi le.","vi":"Đắt quá, tôi không mua nữa."},{"hz":"等一下，我再看看。","py":"děng yíxià, wǒ zài kànkan.","vi":"Chờ một chút, tôi xem lại."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-hai', 'HSK 3', 36, '还是 – HAY (CÂU HỎI LỰA CHỌN)', '还', 'bongu', '还是 – hay (câu hỏi lựa chọn) — điểm ngữ pháp HSK 3.', '[["mệnh đề A"],["还","key"],["是"],["mệnh đề B"],["?"]]', '["Người Việt hay dùng 或者 trong câu hỏi: ","还是 chỉ dùng trong câu hỏi lựa chọn: ‘你喝茶还是喝咖啡?’","\u003b 或者 dùng trong câu trần thuật."]', '[{"hz":"你去医院还是去学校？","py":"nǐ qù yīyuàn háishi qù xuéxiào?","vi":"Bạn đi bệnh viện hay đi trường?"},{"hz":"我们坐火车还是坐飞机？","py":"wǒmen zuò huǒchē háishi zuò fēijī?","vi":"Chúng ta đi tàu hay đi máy bay?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-huo', 'HSK 3', 37, '或者 vs 还是 – HOẶC (TRẦN THUẬT) KHÁC HAY (CÂU HỎI)', '或', 'bongu', '或者 vs 还是 – hoặc (trần thuật) khác hay (câu hỏi) — điểm ngữ pháp HSK 3.', '[["mệnh đề / danh ngữ A"],["或","key"],["者"],["danh ngữ / mệnh đề B"],["(câu trần thuật)"]]', '["Người Việt hay dùng 还是 trong câu trần thuật: ","或者 dùng cho câu kể và câu mệnh lệnh: ‘下午我去打篮球或者游泳’","\u003b 还是 dùng cho câu hỏi lựa chọn."]', '[{"hz":"晚上我复习课文或者听录音。","py":"wǎnshang wǒ fùxí kèwén huòzhě tīng lùyīn.","vi":"Tối tôi ôn bài hoặc nghe băng."},{"hz":"星期天我们爬山或者钓鱼。","py":"Xīngqītiān wǒmen páshān huòzhě diàoyú.","vi":"Chủ nhật chúng ta leo núi hoặc câu cá."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-yi-2', 'HSK 3', 38, '已经…了 – ĐÃ… RỒI', '已', 'bongu', '已经…了 – đã… rồi — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["已","key"],["经"],["vị ngữ"],["了"]]', '["Người Việt hay dùng 已经 thiếu 了 ở cuối: ","已经…了 đi cặp: ‘他已经知道这个消息了’","\u003b phủ định tương ứng là 还没…呢."]', '[{"hz":"他已经知道这个消息了。","py":"tā yǐjīng zhīdào zhège xiāoxi le.","vi":"Nó đã biết tin này rồi."},{"hz":"我们已经等了你半个小时了。","py":"wǒmen yǐjīng děng le nǐ bàn ge xiǎoshí le.","vi":"Chúng tôi đã chờ bạn nửa tiếng rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-dou', 'HSK 3', 39, '都 – ĐỀU (PHỦ RỘNG CHỦ NGỮ HOẶC TÂN NGỮ ĐỨNG TRƯỚC)', '都', 'bongu', '都 – đều (phủ rộng chủ ngữ hoặc tân ngữ đứng trước) — điểm ngữ pháp HSK 3.', '[["chủ ngữ / 这些, 大家, 谁…"],["都","key"],["động từ"],["(thành phần khác)"],[""]]', '["Người Việt hay đặt 都 sai chỗ: ","都 phải đứng sau từ mà nó phủ rộng: ‘我们都去’","\u003b với tân ngữ đặt trước, cũng dùng 都: ‘他什么都不吃’."]', '[{"hz":"这些书都是我的。","py":"zhèxiē shū dōu shì wǒ de.","vi":"Những cuốn sách này đều là của tôi."},{"hz":"他什么都不想吃。","py":"tā shénme dōu bù xiǎng chī.","vi":"Nó cái gì cũng không muốn ăn."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-ye', 'HSK 3', 40, '也 – CŨNG (VỊ TRÍ VỚI PHỦ ĐỊNH)', '也', 'bongu', '也 – cũng (vị trí với phủ định) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["也","key"],["động từ / tính từ"],["(thành phần khác)"],[""]]', '["Người Việt hay đặt 不/没 trước 也: ","khi phủ định, 也 đứng trước 不/没: ‘我也不去’",", không nói ‘我也不去’ thành ‘我不也去’."]', '[{"hz":"他是学生，他姐姐也是学生。","py":"tā shì xuésheng, tā jiějie yě shì xuésheng.","vi":"Nó là học sinh, chị của nó cũng là học sinh."},{"hz":"我不认识他，他也不认识我。","py":"wǒ bú rènshi tā, tā yě bú rènshi wǒ.","vi":"Tôi không biết nó, nó cũng không biết tôi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-dian', 'HSK 3', 41, '有点儿 – HƠI, KHÁ (ĐI VỚI CẢM GIÁC KHÔNG MONG MUỐN)', '点', 'bongu', '有点儿 – hơi, khá (đi với cảm giác không mong muốn) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["点","key"],["有(一)点儿"],["tính từ / động từ (tiêu cực)"],[""]]', '["Người Việt hay dùng 有点儿 với tính từ tốt: ","有点儿 đứng trước tính từ/động từ tiêu cực: ‘今天有点儿冷’, ‘我有点儿累’","\u003b không nói ‘有点儿高兴’\u003b nghĩa tốt dùng ‘很高兴’."]', '[{"hz":"我有点儿累，想休息一下。","py":"wǒ yǒudiǎnr lèi, xiǎng xiūxi yíxià.","vi":"Tôi hơi mệt, muốn nghỉ một chút."},{"hz":"这个菜有点儿咸。","py":"zhège cài yǒudiǎnr xián.","vi":"Món này hơi mặn."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-dian-2', 'HSK 3', 42, '一点儿 – MỘT CHÚT (LƯỢNG ÍT, KHÔNG MANG CẢM XÚC TIÊU CỰC)', '点', 'bongu', '一点儿 – một chút (lượng ít, không mang cảm xúc tiêu cực) — điểm ngữ pháp HSK 3.', '[["động từ"],["点","key"],["(一)点儿"],["danh từ / tính từ"],["(phủ định: 一点儿也不/没)"]]', '["Người Việt hay đảo 有点儿 và 一点儿: ","一点儿 đứng sau tính từ hoặc trước danh từ: ‘快一点儿’, ‘买一点儿水果’","\u003b 有点儿 thì đứng trước tính từ tiêu cực."]', '[{"hz":"我想喝一点儿水。","py":"wǒ xiǎng hē yìdiǎnr shuǐ.","vi":"Tôi muốn uống một chút nước."},{"hz":"请你说得慢一点儿。","py":"qǐng nǐ shuō de màn yìdiǎnr.","vi":"Xin bạn nói chậm một chút."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-cha', 'HSK 3', 43, '差不多 – GẦN NHƯ, TƯƠNG TỰ, CHỪNG', '差', 'bongu', '差不多 – gần như, tương tự, chừng — điểm ngữ pháp HSK 3.', '[["chủ ngữ / số lượng"],["差","key"],["不多"],["vị ngữ / danh ngữ"],["(了)"]]', '["Người Việt hay quên nghĩa ‘gần đến lúc rồi’ của 差不多: ","‘差不多该走了’ – chừng đó thì nên đi thôi","\u003b ‘两个颜色差不多’ – hai màu gần như giống nhau."]', '[{"hz":"这两个颜色差不多。","py":"zhè liǎng ge yánsè chàbuduō.","vi":"Hai màu này gần như giống nhau."},{"hz":"差不多十点了，我们走吧。","py":"chàbuduō shí diǎn le, wǒmen zǒu ba.","vi":"Chừng mười giờ rồi, mình đi thôi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-cong', 'HSK 3', 44, '从…到 – TỪ… ĐẾN (THỜI GIAN HAY NƠI CHỐN)', '从', 'bongu', '从…到 – từ… đến (thời gian hay nơi chốn) — điểm ngữ pháp HSK 3.', '[["从"],["从","key"],["điểm bắt đầu"],["到"],["điểm kết thúc"]]', '["Người Việt hay bỏ 从 hoặc 到: ","hai từ phải đi cùng nhau: ‘从我家到学校很近’",", ‘从早上八点工作到下午六点’."]', '[{"hz":"我从早上八点工作到下午六点。","py":"wǒ cóng zǎoshang bā diǎn gōngzuò dào xiàwǔ liù diǎn.","vi":"Tôi làm việc từ tám giờ sáng đến sáu giờ chiều."},{"hz":"从北京到上海坐飞机要两个小时。","py":"cóng Běijīng dào Shànghǎi zuò fēijī yào liǎng ge xiǎoshí.","vi":"Từ Bắc Kinh đến Thượng Hải đi máy bay mất hai tiếng."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-dui', 'HSK 3', 45, '对 – ĐỐI VỚI (THÁI ĐỘ, CẢM XÚC ĐỐI VỚI AI/ĐIỀU GÌ)', '对', 'bongu', '对 – đối với (thái độ, cảm xúc đối với ai/điều gì) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["对","key"],["đối tượng (người/vật)"],["động từ / tính từ"],["(thành phần khác)"]]', '["Người Việt hay nhầm 对 với 向/给: ","对 dùng với thái độ, cảm xúc: ‘他对我很好’, ‘对…感兴趣’","\u003b 向/向 chỉ hướng, 给 chỉ người nhận."]', '[{"hz":"他对我笑了笑。","py":"tā duì wǒ xiào le xiào.","vi":"Nó cười với tôi."},{"hz":"我对汉语越来越感兴趣了。","py":"wǒ duì Hànyǔ yuèláiyuè gǎn xìngqù le.","vi":"Tôi càng ngày càng thích thú với tiếng Trung."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-gei', 'HSK 3', 46, '给 – CHO, THAY, VÌ (NGƯỜI NHẬN HOẶC NGƯỜI ĐƯỢC LÀM HỘ)', '给', 'bongu', '给 – cho, thay, vì (người nhận hoặc người được làm hộ) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["给","key"],["người nhận / người được giúp"],["động từ"],["(tân ngữ)"]]', '["Người Việt hay bỏ 给 khi nói làm gì cho ai: ","给 + người đứng trước động từ: ‘我给妈妈买礼物’","\u003b các cụm quen thuộc: 给…打电话, 给…写信, 给…介绍."]', '[{"hz":"老师给我们介绍了那个地方。","py":"lǎoshī gěi wǒmen jièshào le nàge dìfang.","vi":"Cô giáo giới thiệu với chúng tôi nơi đó."},{"hz":"请你给客人倒一杯茶。","py":"qǐng nǐ gěi kèrén dào yì bēi chá.","vi":"Xin bạn rót một cốc trà cho khách."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-wang', 'HSK 3', 47, '往/向 – HƯỚNG (PHƯƠNG HƯỚNG CỦA HÀNH ĐỘNG)', '往', 'bongu', '往/向 – hướng (phương hướng của hành động) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["往","key"],["danh ngữ phương hướng"],["động từ"],["(走/看/拐…)"]]', '["Người Việt hay dùng 到 thay 往/向: ","往/向 + phương hướng đứng trước động từ: ‘往前走’, ‘向南看’","\u003b 到 + nơi chốn đứng sau động từ: ‘走到银行’."]', '[{"hz":"往前走，右手边就是银行。","py":"wǎng qián zǒu, yòushǒu biān jiùshì yínháng.","vi":"Đi thẳng về phía trước, bên tay phải là ngân hàng."},{"hz":"他朝我招了招手。","py":"tā cháo wǒ zhāo le zhāo shǒu.","vi":"Nó vẫy tay về phía tôi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-li', 'HSK 3', 48, '离 – CÁCH, XA (KHOẢNG CÁCH NƠI CHỐN HOẶC THỜI GIAN CÒN LẠI)', '离', 'bongu', '离 – cách, xa (khoảng cách nơi chốn hoặc thời gian còn lại) — điểm ngữ pháp HSK 3.', '[["A"],["离","key"],["B"],["远 / 近 / số lượng thời gian"],["(thành phần khác)"]]', '["Người Việt hay dùng 从 thay 离 khi nói khoảng cách: ","离 chỉ khoảng cách: ‘学校离我家很近’",", hoặc thời gian còn lại: ‘离考试还有三天’."]', '[{"hz":"机场离市中心很远。","py":"jīchǎng lí shì zhōngxīn hěn yuǎn.","vi":"Sân bay cách trung tâm thành phố rất xa."},{"hz":"离圣诞节还有两个星期。","py":"lí Shèngdànjié hái yǒu liǎng ge xīngqī.","vi":"Còn hai tuần nữa là đến Giáng sinh."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-ne', 'HSK 3', 49, '呢 – CÒN… THÌ SAO / ĐANG… ĐÓ', '呢', 'bongu', '呢 – còn… thì sao / đang… đó — điểm ngữ pháp HSK 3.', '[["danh ngữ / chủ ngữ"],["呢","key"],["? (câu hỏi ngược)"],["hoặc: chủ ngữ + động từ đang diễn ra"],["呢"]]', '["Người Việt hay dùng 呢 cho câu hỏi có/không: ","呢 không dùng cho câu hỏi có/không, 吗 mới làm việc đó","\u003b ‘你呢?’ – còn bạn thì sao?, ‘他在开会呢’ – anh ấy đang họp đó."]', '[{"hz":"我很好，你呢？","py":"wǒ hěn hǎo, nǐ ne?","vi":"Tôi khỏe, còn bạn thì sao?"},{"hz":"他看电视呢，别打扰他。","py":"tā kàn diànshì ne, bié dǎrǎo tā.","vi":"Nó đang xem tivi đấy, đừng làm phiền nó."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-xian', 'HSK 3', 50, '先…然后 – TRƯỚC… RỒI SAU ĐÓ', '先', 'bongu', '先…然后 – trước… rồi sau đó — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["先","key"],["động từ 1"],["然后"],["động từ 2"]]', '["Người Việt hay dùng 先 mà thiếu 然后: ","先…然后 chỉ trình tự hai việc nối tiếp: ‘先洗手，然后吃饭’",", không dùng cho hai việc đồng thời (dùng 一边…一边)."]', '[{"hz":"我先做作业，然后看电视。","py":"wǒ xiān zuò zuòyè, ránhòu kàn diànshì.","vi":"Tôi làm bài tập trước, rồi xem tivi."},{"hz":"先往左拐，再往前走。","py":"xiān wǎng zuǒ guǎi, zài wǎng qián zǒu.","vi":"Rẽ trái trước, rồi đi thẳng."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-mei', 'HSK 3', 51, '每…都 – MỖI… ĐỀU (KHÔNG NGOẠI LỆ)', '每', 'bongu', '每…都 – mỗi… đều (không ngoại lệ) — điểm ngữ pháp HSK 3.', '[["每"],["每","key"],["lượng từ + danh từ"],["都"],["vị ngữ"]]', '["Người Việt hay bỏ 都 sau 每…: ","每 + lượng từ + danh từ thường phải kèm 都/也: ‘我每天都跑步’",", không nói ‘我每天跑步都’ kiểu tiếng Việt."]', '[{"hz":"他每个星期都去打球。","py":"tā měi ge xīngqī dōu qù dǎ qiú.","vi":"Tuần nào nó cũng đi chơi bóng."},{"hz":"每道题他都做对了。","py":"měi dào tí tā dōu zuò duì le.","vi":"Câu nào nó cũng làm đúng."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-tai', 'HSK 3', 52, '太…了 – QUÁ… (CẢM THÁN VƯỚI MỨC ĐỘ)', '太', 'bongu', '太…了 – quá… (cảm thán vưới mức độ) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["太","key"],["tính từ / trạng từ tâm lý"],["了"],[""]]', '["Người Việt hay dùng 太 thiếu 了: ","太…了 đi cặp mang cảm thán: ‘今天太热了’","\u003b rất/very trung tính dùng 很, không cần 了."]', '[{"hz":"这部电影太有意思了！","py":"zhè bù diànyǐng tài yǒu yìsi le!","vi":"Bộ phim này thú vị quá!"},{"hz":"这个箱子太重了，我搬不动。","py":"zhège xiāngzi tài zhòng le, wǒ bān bu dòng.","vi":"Cái thùng này nặng quá, tôi khiêng không nổi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-zhi', 'HSK 3', 53, '只有…才 – CHỈ KHI… MỚI (ĐIỀU KIỆN DUY NHẤT)', '只', 'bongu', '只有…才 – chỉ khi… mới (điều kiện duy nhất) — điểm ngữ pháp HSK 3.', '[["只","key"],["有 + điều kiện"],["才"],["kết quả"],[""]]', '["Người Việt hay dùng 只要 thay 只有 hoặc bỏ 才: ","只有…才 nhấn điều kiện duy nhất: ‘只有努力才能学好汉语’","\u003b 只要…就 nhấn điều kiện đủ, nghĩa khác."]', '[{"hz":"只有他才知道这个秘密。","py":"zhǐyǒu tā cái zhīdào zhège mìmì.","vi":"Chỉ có nó mới biết bí mật này."},{"hz":"只有坐出租车才赶得上飞机。","py":"zhǐyǒu zuò chūzūchē cái gǎn de shàng fēijī.","vi":"Chỉ đi taxi mới kịp máy bay."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-hui', 'HSK 3', 54, '会 vs 能 vs 可以 – BIỆT BA CÁCH NÓI ‘CÓ THỂ’', '会', 'hutu', '会 vs 能 vs 可以 – biệt ba cách nói ‘có thể’ — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["会","key"],["động từ"],["(能 = điều kiện/được phép\u003b 可以 = được phép)"],[""]]', '["Người Việt hay dùng 会 cho mọi nghĩa ‘có thể’: ","会 = kĩ năng học được, 能 = khả năng/điều kiện, 可以 = được phép",": ‘我会说汉语’, ‘这里不能抽烟’, ‘你可以走了’."]', '[{"hz":"他会弹钢琴，但是今天不能弹。","py":"tā huì tán gāngqín, dànshì jīntiān bù néng tán.","vi":"Nó biết chơi đàn piano, nhưng hôm nay không thể chơi."},{"hz":"老师，我可以问一个问题吗？","py":"lǎoshī, wǒ kěyǐ wèn yí ge wèntí ma?","vi":"Thầy ơi, em có thể hỏi một câu được không?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-xiang', 'HSK 3', 55, '想 vs 要 vs 想要 – MUỐN, ĐỊNH (MỨC ĐỘ Ý ĐỊNH KHÁC NHAU)', '想', 'hutu', '想 vs 要 vs 想要 – muốn, định (mức độ ý định khác nhau) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["想","key"],["động từ (mong muốn)"],["(要 = định chắc chắn\u003b 想要 = muốn có vật)"],[""]]', '["Người Việt hay dùng 想 cho vật và 要 cho hành động lẫn lộn: ","想 + động từ = muốn làm: ‘我想喝水’","\u003b 要 + danh từ = cần/đặt mua: ‘我要一瓶水’."]', '[{"hz":"我想去海南旅行。","py":"wǒ xiǎng qù Hǎinán lǚxíng.","vi":"Tôi muốn đi du lịch Hải Nam."},{"hz":"我想要一杯咖啡。","py":"wǒ xiǎng yào yì bēi kāfēi.","vi":"Tôi muốn một cốc cà phê."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-jian', 'HSK 3', 56, '离合词 – TỪ RỜI (见面, 睡觉, 洗澡: KHÔNG ĐƯA TÂN NGỮ NGAY SAU)', '见', 'hutu', '离合词 – từ rời (见面, 睡觉, 洗澡: không đưa tân ngữ ngay sau) — điểm ngữ pháp HSK 3.', '[["chủ ngữ"],["见","key"],["面 (từ rời: 见面, 睡觉, 洗澡, 帮忙…)"],["(thành phần chen giữa: 了, 了 + lượng từ)"],[""]]', '["Người Việt hay thêm tân ngữ ngay sau từ rời: ","‘见面他’ sai, phải nói ‘跟他见面’","\u003b các dạng đúng: ‘见过一次面’, ‘睡了一个好觉’, ‘帮了我一个忙’."]', '[{"hz":"我明天要见他一面。","py":"wǒ míngtiān yào jiàn tā yí miàn.","vi":"Ngày mai tôi sẽ gặp nó một lần."},{"hz":"他洗了个澡就睡了。","py":"tā xǐ le ge zǎo jiù shuì le.","vi":"Nó tắm một cái rồi đi ngủ."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-mian', 'HSK 3', 57, '方位词 – 里/上/下/前/后/旁边 (KHÔNG ĐƯỢC BỊ BỎ)', '面', 'hutu', '方位词 – 里/上/下/前/后/旁边 (không được bị bỏ) — điểm ngữ pháp HSK 3.', '[["danh ngữ +"],["面","key"],["里 / 上 / 下 / 前面 / 后面 / 旁边"],["+ động từ / 是"],[""]]', '["Người Việt hay dịch ‘trong phòng’ thành ‘在房间’ thiếu 里: ","sau danh từ nơi chốn thường phải có 方位词: ‘在房间里’, ‘桌子上’","\u003b chỉ một số từ như 家, 学校, 今年 có thể đứng một mình."]', '[{"hz":"书在桌子下面。","py":"shū zài zhuōzi xiàmiàn.","vi":"Sách ở dưới bàn."},{"hz":"银行旁边有一个邮局。","py":"yínháng pángbiān yǒu yí ge yóujú.","vi":"Bên cạnh ngân hàng có một bưu điện."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-hui-2', 'HSK 3', 58, '一会儿 – MỘT CHÚC, LÁT (KHOẢNG THỜI GIAN NGẮN)', '会', 'hutu', '一会儿 – một chúc, lát (khoảng thời gian ngắn) — điểm ngữ pháp HSK 3.', '[["等 / 看 / 说…"],["会","key"],["儿"],["(động từ)"],["(一会儿…一会儿 = chốc chốc làm việc đó)"]]', '["Người Việt hay nhầm 一会儿 với 一下: ","一会儿 chỉ khoảng thời gian: ‘等一会儿’ – chờ một lát","\u003b 一会儿…一会儿 mô tả hành động thay đổi liên tục."]', '[{"hz":"你等我一会儿，我马上回来。","py":"nǐ děng wǒ yíhuìr, wǒ mǎshàng huílái.","vi":"Chờ tôi một lát, tôi quay lại ngay."},{"hz":"小狗一会儿跑，一会儿跳。","py":"xiǎo gǒu yíhuìr pǎo, yíhuìr tiào.","vi":"Con chó con chốc chốc chạy, chốc chốc nhảy."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk3-shang-2', 'HSK 3', 59, '上/下 VỚI THỜI GIAN – TUẦN TRƯỚC/SAU, THÁNG TRƯỚC/SAU', '上', 'hutu', '上/下 với thời gian – tuần trước/sau, tháng trước/sau — điểm ngữ pháp HSK 3.', '[["上 / 下"],["上","key"],["个 / 星期 / 月 / 次"],["+ danh từ thời gian"],[""]]', '["Người Việt hay dùng 前/后 cho tuần và tháng: ","tuần/tháng dùng 上/下: ‘上星期’, ‘下个月’","\u003b 前/后 dùng với năm, ngày: ‘前天’, ‘后年’."]', '[{"hz":"上个月我去了两次上海。","py":"shàng ge yuè wǒ qù le liǎng cì Shànghǎi.","vi":"Tháng trước tôi đi Thượng Hải hai lần."},{"hz":"下星期我们有一场考试。","py":"xià xīngqī wǒmen yǒu yì chǎng kǎoshì.","vi":"Tuần sau chúng ta có một buổi thi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-b-ǎ-O-V-C', 'HSK 4', 0, 'CÂU 把字句', 'SbǎOVC', 'ba', 'Câu 把字句 — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["把","key"],["Tân ngữ","key"],["Động từ","key"],["Bổ ngữ","key"]]', '["Người Việt hay bỏ bổ ngữ sau động từ: ","我把作业做"," là câu dở, phải nói 我把作业做完了。"]', '[{"hz":"我把作业做完了。","py":"Wǒ bǎ zuòyè zuò wán le.","vi":"Tôi đã làm xong bài tập rồi."},{"hz":"请把门打开。","py":"Qǐng bǎ mén dǎkāi.","vi":"Xin hãy mở cửa ra."},{"hz":"他把手机放在桌子上了。","py":"Tā bǎ shǒujī fàng zài zhuōzi shang le.","vi":"Anh ấy đã đặt điện thoại lên bàn."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-b-è-i-a-g-e-n-t-V-+-C', 'HSK 4', 1, 'CÂU BỊ ĐỘNG 被字句', 'SbèiagentV+C', 'ba', 'Câu bị động 被字句 — điểm ngữ pháp HSK 4.', '[["Chủ ngữ (bị tác động)","key"],["被","key"],["Người/vật tác động","key"],["Động từ + bổ ngữ","key"]]', '["Người Việt hay quên kết quả ở cuối câu: ","书被我借"," chưa xong, phải nói 书被我借走了。"]', '[{"hz":"杯子被弟弟打破了。","py":"Bēizi bèi dìdi dǎ pò le.","vi":"Cái cốc bị em trai đánh vỡ rồi."},{"hz":"我的自行车被偷了。","py":"Wǒ de zìxíngchē bèi tōu le.","vi":"Xe đạp của tôi bị mất trộm rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-l-i-á-n-X-d-ō-u-/-y-ě-V-/-A-d-j', 'HSK 4', 2, 'CẤU TRÚC 连……都/也', 'liánXdōu/yěV/Adj', 'ba', 'Cấu trúc 连……都/也 — điểm ngữ pháp HSK 4.', '[["连","key"],["Từ được nhấn mạnh","key"],["都/也","key"],["Động từ/Tính từ","key"]]', '["Người Việt hay quên 都/也 ở giữa: ","连饭不做"," là sai, phải nói 连饭都不做。"]', '[{"hz":"他连早饭都没吃就去上班了。","py":"Tā lián zǎofàn dōu méi chī jiù qù shàngbān le.","vi":"Anh ấy thậm chí còn chưa ăn sáng đã đi làm rồi."},{"hz":"这个问题连老师都不会。","py":"Zhège wèntí lián lǎoshī dōu bú huì.","vi":"Câu hỏi này đến tận thầy cô cũng không biết."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-r-à-n-g-/-j-i-à-o-/-q-ǐ-n-g-O-V', 'HSK 4', 3, 'CÂU 兼语句（让/叫/请）', 'Sràng/jiào/qǐngOV', 'ba', 'Câu 兼语句（让/叫/请） — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["让/叫/请","key"],["Người","key"],["Động từ","key"]]', '["Người Việt hay chèn 把 sai chỗ: ","我让他把过来"," là sai, phải nói 我让他过来。"]', '[{"hz":"老师让我们每天读课文。","py":"Lǎoshī ràng wǒmen měitiān dú kèwén.","vi":"Giáo viên bắt chúng tôi đọc bài mỗi ngày."},{"hz":"我请你帮个忙。","py":"Wǒ qǐng nǐ bāng ge máng.","vi":"Tôi nhờ cậu giúp một việc."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-V--+-O-V--+-O', 'HSK 4', 4, 'CÂU ĐỘNG TỪ LIÊN TIẾP (连动句)', 'SV1+OV2+O', 'hutu', 'Câu động từ liên tiếp (连动句) — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["Động từ 1 + tân ngữ","key"],["Động từ 2 + tân ngữ","key"]]', '["Người Việt hay thêm 为了 kiểu dịch máy: ","我去商店为了买东西"," là sai, phải nói 我去商店买东西。"]', '[{"hz":"我去银行换钱。","py":"Wǒ qù yínhuán huàn qián.","vi":"Tôi đến ngân hàng đổi tiền."},{"hz":"他坐地铁上班。","py":"Tā zuò dìtiě shàngbān.","vi":"Anh ấy đi làm bằng tàu điện."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-s-h-ì-X-V-+-d-e', 'HSK 4', 5, 'CẤU TRÚC 是……的', 'SshìXV+de', 'hutu', 'Cấu trúc 是……的 — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["是","key"],["Phần được nhấn mạnh","key"],["Động từ + 的","key"]]', '["Người Việt hay quên 的 ở cuối: ","他是昨天来"," là câu dở, phải nói 他是昨天来的。"]', '[{"hz":"我是在中国学的汉语。","py":"Wǒ shì zài Zhōngguó xué de Hànyǔ.","vi":"Tôi học tiếng Trung ở Trung Quốc (chứ)."},{"hz":"他是坐火车去的。","py":"Tā shì zuò huǒchē qù de.","vi":"Anh ấy đi bằng tàu hỏa đấy."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-A-b-ǐ-B-A-d-j-+-đ-ộ-c-h-ê-n-h', 'HSK 4', 6, 'SO SÁNH VỚI 比', 'AbǐBAdj+độ chênh', 'hutu', 'So sánh với 比 — điểm ngữ pháp HSK 4.', '[["A","key"],["比","key"],["B","key"],["Tính từ + phần khác biệt","key"]]', '["Người Việt hay thêm 很 trước tính từ: ","他比我很高"," là sai, phải nói 他比我高得多。"]', '[{"hz":"今天比昨天热。","py":"Jīntiān bǐ zuótiān rè.","vi":"Hôm nay nóng hơn hôm qua."},{"hz":"他跑得比我快。","py":"Tā pǎo de bǐ wǒ kuài.","vi":"Anh ấy chạy nhanh hơn tôi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-A-g-ē-n-B-y-ī-y-à-n-g-A-d-j', 'HSK 4', 7, 'SO SÁNH 跟……一样', 'AgēnByīyàngAdj', 'hutu', 'So sánh 跟……一样 — điểm ngữ pháp HSK 4.', '[["A","key"],["跟","key"],["B","key"],["一样","key"],["Tính từ","key"]]', '["Người Việt hay bỏ 一样: ","他跟我高"," là sai, phải nói 他跟我一样高。"]', '[{"hz":"这个房间跟那个房间一样大。","py":"Zhège fángjiān gēn nàge fángjiān yīyàng dà.","vi":"Căn phòng này to bằng căn phòng kia."},{"hz":"我的意见跟他的一样。","py":"Wǒ de yìjiàn gēn tā de yīyàng.","vi":"Ý kiến của tôi giống hệt của anh ấy."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-A-m-é-i-y-ǒ-u-B-z-h-è-m-e-/-n-à-m-e-A-d-j', 'HSK 4', 8, 'SO SÁNH PHỦ ĐỊNH 没有……这么/那么', 'AméiyǒuBzhème/nàmeAdj', 'hutu', 'So sánh phủ định 没有……这么/那么 — điểm ngữ pháp HSK 4.', '[["A","key"],["没有","key"],["B","key"],["这么/那么","key"],["Tính từ","key"]]', '["Người Việt hay dùng 比 để phủ định: ","他比我不高"," là sai, phải nói 他没有我高。"]', '[{"hz":"弟弟没有哥哥那么高。","py":"Dìdi méiyǒu gēge nàme gāo.","vi":"Em trai không cao bằng anh trai."},{"hz":"今天没有昨天那么冷。","py":"Jīntiān méiyǒu zuótiān nàme lěng.","vi":"Hôm nay không lạnh bằng hôm qua."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-y-u-è-X--y-u-è-X-', 'HSK 4', 9, 'CẤU TRÚC 越……越……', 'yuèX1yuèX2', 'hutu', 'Cấu trúc 越……越…… — điểm ngữ pháp HSK 4.', '[["越","key"],["V/Tính từ 1","key"],["越","key"],["V/Tính từ 2","key"]]', '["Người Việt hay trộn hai mẫu: ","越学越来越难"," là sai, dùng một trong hai: 越学越难 hoặc 越来越难。"]', '[{"hz":"他越说越高兴。","py":"Tā yuè shuō yuè gāoxìng.","vi":"Anh ấy càng nói càng vui."},{"hz":"雨越下越大。","py":"Yǔ yuè xià yuè dà.","vi":"Mưa càng lúc càng to."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-y-u-è-l-á-i-y-u-è-A-d-j-/-V', 'HSK 4', 10, 'CẤU TRÚC 越来越', 'SyuèláiyuèAdj/V', 'hutu', 'Cấu trúc 越来越 — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["越来越","key"],["Tính từ/Động từ","key"]]', '["Người Việt hay bỏ 来 ở giữa: ","越越好"," là sai, phải nói 越来越好。"]', '[{"hz":"天气越来越冷了。","py":"Tiānqì yuèláiyuè lěng le.","vi":"Thời tiết ngày càng lạnh rồi."},{"hz":"汉语越来越有意思了。","py":"Hànyǔ yuèláiyuè yǒu yìsi le.","vi":"Tiếng Trung càng lúc càng thú vị rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-y-ī-b-i-ā-n-V--y-ī-b-i-ā-n-V-', 'HSK 4', 11, 'CẤU TRÚC 一边……一边……', 'SyībiānV1yībiānV2', 'hutu', 'Cấu trúc 一边……一边…… — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["一边","key"],["Động từ 1","key"],["一边","key"],["Động từ 2","key"]]', '["Người Việt hay lặp chủ ngữ ở vế sau: ","我一边听歌，我一边写作业"," là dư, phải bỏ chủ ngữ thứ hai."]', '[{"hz":"我们一边喝茶一边聊天。","py":"Wǒmen yībiān hē chá yībiān liáotiān.","vi":"Chúng tôi vừa uống trà vừa tán gẫu."},{"hz":"他一边走路一边看手机。","py":"Tā yībiān zǒulù yībiān kàn shǒujī.","vi":"Anh ấy vừa đi bộ vừa xem điện thoại."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-y-ò-u-X--y-ò-u-X-', 'HSK 4', 12, 'CẤU TRÚC 又……又……', 'SyòuX1yòuX2', 'hutu', 'Cấu trúc 又……又…… — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["又","key"],["Tính từ/Động từ 1","key"],["又","key"],["Tính từ/Động từ 2","key"]]', '["Người Việt hay dùng 也 để nối: ","他又高也聪明"," là sai, phải nói 他又高又聪明。"]', '[{"hz":"这个西瓜又大又甜。","py":"Zhège xīguā yòu dà yòu tián.","vi":"Quả dưa hấu này vừa to vừa ngọt."},{"hz":"她又聪明又勤劳。","py":"Tā yòu cōngming yòu qínláo.","vi":"Cô ấy vừa thông minh vừa chăm chỉ."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-y-ī-V--j-i-ù-V-', 'HSK 4', 13, 'CẤU TRÚC 一……就……', 'yīV1jiùV2', 'hutu', 'Cấu trúc 一……就…… — điểm ngữ pháp HSK 4.', '[["一","key"],["Động từ 1","key"],["就","key"],["Động từ 2","key"]]', '["Người Việt hay dùng 就 hai lần: ","他一回家就就睡觉"," là sai, chỉ cần một 就。"]', '[{"hz":"我一到家就给你打电话。","py":"Wǒ yī dào jiā jiù gěi nǐ dǎ diànhuà.","vi":"Tôi vừa về đến nhà là gọi cho bạn ngay."},{"hz":"他一看书就困。","py":"Tā yī kàn shū jiù kùn.","vi":"Cậu ấy vừa cầm sách là buồn ngủ."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-k-u-à-i-y-à-o-V-/-A-d-j-l-e', 'HSK 4', 14, 'CẤU TRÚC 快要……了', 'Skuài(yào)V/Adjle', 'hutu', 'Cấu trúc 快要……了 — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["快/快要","key"],["Động từ/Tính từ","key"],["了","key"]]', '["Người Việt hay quên 了: ","火车快到"," là câu dở, phải nói 火车快到了。"]', '[{"hz":"火车快到了。","py":"Huǒchē kuài dào le.","vi":"Tàu sắp đến rồi."},{"hz":"天快要黑了。","py":"Tiān kuài yào hēi le.","vi":"Trời sắp tối rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-V-w-á-n-/-h-ǎ-o-/-d-à-o-/-j-i-à-n-l-e', 'HSK 4', 15, 'BỔ NGỮ KẾT QUẢ 完/好/到/见', 'Vwán/hǎo/dào/jiànle', 'bi', 'Bổ ngữ kết quả 完/好/到/见 — điểm ngữ pháp HSK 4.', '[["Động từ","key"],["完/好/到/见","key"],["(了)","key"]]', '["Người Việt hay chỉ dùng động từ trần: ","我看你的信了"," khác với 我看到你的信了 (thấy rõ được)."]', '[{"hz":"我吃完了。","py":"Wǒ chī wán le.","vi":"Tôi ăn xong rồi."},{"hz":"你听见了吗？","py":"Nǐ tīngjiàn le ma?","vi":"Bạn nghe thấy không?"},{"hz":"作业做好了。","py":"Zuòyè zuò hǎo le.","vi":"Bài tập làm xong rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-V-c-u-ò-/-d-u-ì-/-d-ǒ-n-g-/-q-ī-n-g-c-h-u', 'HSK 4', 16, 'BỔ NGỮ KẾT QUẢ 错/对/懂/清楚', 'Vcuò/duì/dǒng/qīngchu', 'bi', 'Bổ ngữ kết quả 错/对/懂/清楚 — điểm ngữ pháp HSK 4.', '[["Động từ","key"],["错/对/懂/清楚","key"]]', '["Người Việt hay đảo bổ ngữ lên trước động từ: ","错听了"," là sai, phải nói 听错了。"]', '[{"hz":"我听错了。","py":"Wǒ tīng cuò le.","vi":"Tôi nghe nhầm rồi."},{"hz":"你写错一个字。","py":"Nǐ xiě cuò yī ge zì.","vi":"Bạn viết sai một chữ."},{"hz":"这道题我做对了。","py":"Zhè dào tí wǒ zuò duì le.","vi":"Câu này tôi làm đúng rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-V-l-á-i-/-q-ù-c-h-ỗ', 'HSK 4', 17, 'BỔ NGỮ HƯỚNG 来/去', 'Vlái/qù(chỗ)', 'bi', 'Bổ ngữ hướng 来/去 — điểm ngữ pháp HSK 4.', '[["Động từ","key"],["来/去","key"],["(Tân ngữ nơi chốn)","key"]]', '["Người Việt hay bỏ động từ trước 来/去: ","来学校去"," là lộn xộn, phải nói 来学校 hoặc 去学校。"]', '[{"hz":"他上来了。","py":"Tā shàng lái le.","vi":"Anh ấy đi lên (nơi này) rồi."},{"hz":"我们进去吧。","py":"Wǒmen jìn qù ba.","vi":"Chúng ta vào đi."},{"hz":"你带钱来了吗？","py":"Nǐ dài qián lái le ma?","vi":"Bạn mang tiền đến chưa?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-V-j-ì-n-/-c-h-ū-/-s-h-à-n-g-/-x-i-à-/-h-u-í-/-g-u-ò-l-á-i-/-q-ù-O', 'HSK 4', 18, 'BỔ NGỮ HƯỚNG KÉP (复合趋向补语)', 'Vjìn/chū/shàng/xià/huí/guòlái/qù(O)', 'bi', 'Bổ ngữ hướng kép (复合趋向补语) — điểm ngữ pháp HSK 4.', '[["Động từ","key"],["进/出/上/下/回/过","key"],["来/去","key"],["(Tân ngữ)","key"]]', '["Người Việt hay chèn tân ngữ sai chỗ: ","他走进去教室"," là sai, phải nói 他走进教室去 hoặc 他走进教室。"]', '[{"hz":"他走进教室去了。","py":"Tā zǒu jìn jiàoshì qù le.","vi":"Anh ấy bước vào lớp học rồi."},{"hz":"小猫从床上跳下来了。","py":"Xiǎo māo cóng chuáng shang tiào xià lái le.","vi":"Con mèo nhảy xuống khỏi giường."},{"hz":"快拿出你的书来。","py":"Kuài ná chū nǐ de shū lái.","vi":"Nhanh lấy sách ra đi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-V-q-ǐ-l-á-i-/-x-i-à-l-á-i-ẩ-n-d-ụ', 'HSK 4', 19, 'NGHĨA ẨN DỤ CỦA BỔ NGỮ HƯỚNG (起来/下来/出来)', 'Vqǐlái/xiàlái(ẩn dụ)', 'bi', 'Nghĩa ẩn dụ của bổ ngữ hướng (起来/下来/出来) — điểm ngữ pháp HSK 4.', '[["Động từ","key"],["起来/下来","key"],["(nghĩa bắt đầu/yên tĩnh)","key"]]', '["Người Việt dịch sát nghĩa đen: ","天冷起来了"," không phải \"trời đứng lên lạnh\" — 起来 ở đây nghĩa là bắt đầu."]', '[{"hz":"天气冷起来了。","py":"Tiānqì lěng qǐlái le.","vi":"Trời bắt đầu lạnh rồi."},{"hz":"请大家安静下来。","py":"Qǐng dàjiā ānjìng xiàlái.","vi":"Xin mọi người yên tĩnh lại."},{"hz":"这个问题我想不出来了。","py":"Zhège wèntí wǒ xiǎng bu chūlái le.","vi":"Câu này tôi nghĩ mãi không ra."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-V-d-e-/-b-ù-C', 'HSK 4', 20, 'BỔ NGỮ KHẢ NĂNG V得/不C', 'Vde/bùC', 'bi', 'Bổ ngữ khả năng v得/不c — điểm ngữ pháp HSK 4.', '[["Động từ","key"],["得/不","key"],["Kết quả/Hướng","key"]]', '["Người Việt hay thay bằng 不能: ","我不能看懂"," không tự nhiên, nên nói 我看不懂。"]', '[{"hz":"这么多菜，我吃不完。","py":"Zhème duō cài, wǒ chī bu wán.","vi":"Nhiều món thế này, tôi ăn không hết."},{"hz":"门太小，桌子搬不进去。","py":"Mén tài xiǎo, zhuōzi bān bu jìnqù.","vi":"Cửa quá nhỏ, cái bàn không kê vào được."},{"hz":"明天我有事，来不了。","py":"Míngtiān wǒ yǒu shì, lái bu liǎo.","vi":"Ngày mai tôi bận, không đến được."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-V-d-e-l-i-ǎ-o-/-b-ù-l-i-ǎ-o', 'HSK 4', 21, 'BỔ NGỮ KHẢ NĂNG V得了/V不了', 'Vdeliǎo/bùliǎo', 'bi', 'Bổ ngữ khả năng v得了/v不了 — điểm ngữ pháp HSK 4.', '[["Động từ","key"],["得/不了","key"]]', '["Người Việt hay đọc sai thanh điệu: ","吃不了 đọc thành \"chī bù lè\""," là sai, phải đọc chī bù liǎo。"]', '[{"hz":"这些菜我吃得了。","py":"Zhèxiē cài wǒ chī deliǎo.","vi":"Số món này tôi ăn hết nổi."},{"hz":"我一天看不了那么多书。","py":"Wǒ yì tiān kàn bu liǎo nàme duō shū.","vi":"Một ngày tôi không đọc nổi nhiều sách thế."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-/-O-V-d-e-A-d-j', 'HSK 4', 22, 'BỔ NGỮ MỨC ĐỘ VỚI 得', 'S/OVdeAdj', 'bi', 'Bổ ngữ mức độ với 得 — điểm ngữ pháp HSK 4.', '[["Chủ ngữ / Tân ngữ trước","key"],["Động từ","key"],["得","key"],["Tính từ mức độ","key"]]', '["Người Việt hay đặt tính từ kiểu tiếng Việt: ","他说汉语很好"," là sai, phải nói 他汉语说得很好。"]', '[{"hz":"他说得很快。","py":"Tā shuō de hěn kuài.","vi":"Anh ấy nói rất nhanh."},{"hz":"姐姐做菜做得很好吃。","py":"Jiějie zuò cài zuò de hěn hǎochī.","vi":"Chị làm món rất ngon."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-A-d-j-/-V-d-e-h-ě-n-/-j-í-l-e-/-h-u-à-i-l-e', 'HSK 4', 23, 'BỔ NGỮ MỨC ĐỘ 得很/极了/坏了', 'Adj/Vdehěn/jíle/huàile', 'bi', 'Bổ ngữ mức độ 得很/极了/坏了 — điểm ngữ pháp HSK 4.', '[["Tính từ/Động từ","key"],["得","key"],["很/极了/坏了","key"]]', '["Người Việt hay bỏ 得: ","他高兴极"," là thiếu, phải nói 他高兴极了。"]', '[{"hz":"我饿得很。","py":"Wǒ è de hěn.","vi":"Tôi đói lắm."},{"hz":"这道菜好吃极了。","py":"Zhè dào cài hǎochī jí le.","vi":"Món này ngon tuyệt."},{"hz":"孩子们高兴坏了。","py":"Háizimen gāoxìng huài le.","vi":"Bọn trẻ vui như nổ rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-V-l-e-t-O', 'HSK 4', 24, 'BỔ NGỮ THỜI LƯỢNG', 'Vlet(O)', 'bi', 'Bổ ngữ thời lượng — điểm ngữ pháp HSK 4.', '[["Động từ","key"],["了","key"],["Thời lượng","key"],["(Tân ngữ)","key"]]', '["Người Việt hay bỏ 了 khi có tân ngữ: ","我学汉语三年"," nên nói 我学了三年汉语。"]', '[{"hz":"我学了三年汉语。","py":"Wǒ xué le sān nián Hànyǔ.","vi":"Tôi đã học tiếng Trung ba năm."},{"hz":"他睡了一个小时。","py":"Tā shuì le yí ge xiǎoshí.","vi":"Anh ấy ngủ một tiếng."},{"hz":"我们等了十分钟车。","py":"Wǒmen děng le shí fēnzhōng chē.","vi":"Chúng tôi đợi xe mười phút."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-V-l-e-c-ì-/-b-i-à-n-/-t-à-n-g-/-x-i-à-O', 'HSK 4', 25, 'BỔ NGỮ SỐ LẦN (次/遍/趟/下)', 'Vlecì/biàn/tàng/xià(O)', 'bi', 'Bổ ngữ số lần (次/遍/趟/下) — điểm ngữ pháp HSK 4.', '[["Động từ","key"],["了","key"],["次/遍/趟/下","key"],["(Tân ngữ)","key"]]', '["Người Việt hay nhầm 次 với 遍: ","我看了三次这本书"," nên nói 这本书我看了三遍 (đọc trọn từ đầu đến cuối)."]', '[{"hz":"这个电影我看了两遍。","py":"Zhège diànyǐng wǒ kàn le liǎng biàn.","vi":"Bộ phim này tôi xem hai lượt."},{"hz":"我去过一次上海。","py":"Wǒ qù guo yí cì Shànghǎi.","vi":"Tôi từng đến Thượng Hải một lần."},{"hz":"请再说一遍。","py":"Qǐng zài shuō yí biàn.","vi":"Xin nhắc lại một lần nữa."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-y-ī-n-w-è-i-n-g-u-y-ê-n-n-h-â-n-s-u-ǒ-y-ǐ-k-ế-t-q-u-ả', 'HSK 4', 26, 'CẤU TRÚC 因为……所以……', 'yīnwèinguyên nhânsuǒyǐkết quả', 'bongu', 'Cấu trúc 因为……所以…… — điểm ngữ pháp HSK 4.', '[["因为","key"],["Nguyên nhân","key"],["所以","key"],["Kết quả","key"]]', '["Người Việt hay trộn 因为 với 为了: ","为了他病了，所以没来"," là sai — nguyên nhân dùng 因为，mục đích mới dùng 为了。"]', '[{"hz":"因为下雨，所以我们在家。","py":"Yīnwèi xià yǔ, suǒyǐ wǒmen zài jiā.","vi":"Vì trời mưa nên chúng tôi ở nhà."},{"hz":"他因为工作忙，很久没回家了。","py":"Tā yīnwèi gōngzuò máng, hěn jiǔ méi huí jiā le.","vi":"Vì công việc bận nên anh ấy lâu rồi chưa về nhà."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-s-u-ī-r-á-n-A-d-à-n-s-h-ì-/-k-ě-s-h-ì-B', 'HSK 4', 27, 'CẤU TRÚC 虽然……但是……', 'suīránAdànshì/kěshìB', 'bongu', 'Cấu trúc 虽然……但是…… — điểm ngữ pháp HSK 4.', '[["虽然","key"],["Vế nhượng bộ","key"],["但是/可是","key"],["Vế chính","key"]]', '["Người Việt hay bỏ vế sau: ","虽然天气不好"," dừng ở đó mà thiếu 但是…… là câu dở."]', '[{"hz":"虽然很难，但是我不放弃。","py":"Suīrán hěn nán, dànshì wǒ bú fàngqì.","vi":"Tuy khó nhưng tôi không bỏ cuộc."},{"hz":"他虽然年轻，但是很有经验。","py":"Tā suīrán niánqīng, dànshì hěn yǒu jīngyàn.","vi":"Tuy trẻ nhưng anh ấy giàu kinh nghiệm."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-b-ú-d-à-n-A-é-r-q-i-ě-B', 'HSK 4', 28, 'CẤU TRÚC 不但……而且……', 'SbúdànAérqiěB', 'bongu', 'Cấu trúc 不但……而且…… — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["不但","key"],["Vế 1","key"],["而且","key"],["Vế tiến hơn","key"]]', '["Người Việt hay đảo hai vế sai hướng: ","他不但会说日语，而且会一点儿汉语"," sai hướng — 而且 phải dẫn vế tiến hơn."]', '[{"hz":"他不但会说汉语，而且会说日语。","py":"Tā búdàn huì shuō Hànyǔ, érqiě huì shuō Rìyǔ.","vi":"Anh ấy không những biết tiếng Trung mà còn biết tiếng Nhật."},{"hz":"这个手机不但便宜，而且好用。","py":"Zhège shǒujī búdàn piányi, érqiě hǎoyòng.","vi":"Chiếc điện thoại này không những rẻ mà còn dễ dùng."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-z-h-ǐ-y-à-o-đ-i-ề-u-k-i-ệ-n-j-i-ù-k-ế-t-q-u-ả', 'HSK 4', 29, 'CẤU TRÚC 只要……就……', 'zhǐyàođiều kiệnjiùkết quả', 'bongu', 'Cấu trúc 只要……就…… — điểm ngữ pháp HSK 4.', '[["只要","key"],["Điều kiện","key"],["就","key"],["Kết quả","key"]]', '["Người Việt hay nhầm 只要 với 只有: ","只有你努力，你就会成功"," là sai kết hợp — 只有 phải搭配 才。"]', '[{"hz":"只要有时间，我就来。","py":"Zhǐyào yǒu shíjiān, wǒ jiù lái.","vi":"Miễn có thời gian là tôi đến."},{"hz":"只要你说，我就帮你。","py":"Zhǐyào nǐ shuō, wǒ jiù bāng nǐ.","vi":"Miễn bạn nói là tôi giúp."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-z-h-ǐ-y-ǒ-u-đ-i-ề-u-k-i-ệ-n-d-u-y-n-h-ấ-t-c-á-i-k-ế-t-q-u-ả', 'HSK 4', 30, 'CẤU TRÚC 只有……才……', 'zhǐyǒuđiều kiện duy nhấtcáikết quả', 'bongu', 'Cấu trúc 只有……才…… — điểm ngữ pháp HSK 4.', '[["只有","key"],["Điều kiện duy nhất","key"],["才","key"],["Kết quả","key"]]', '["Người Việt hay dùng 就 với 只有: ","只有你有钥匙，就能开门"," là sai, phải nói 只有你有钥匙，才能开门。"]', '[{"hz":"只有努力，才能成功。","py":"Zhǐyǒu nǔlì, cái néng chénggōng.","vi":"Chỉ khi chăm chỉ mới thành công được."},{"hz":"只有坐地铁，才不会迟到。","py":"Zhǐyǒu zuò dìtiě, cái bú huì chídào.","vi":"Chỉ khi đi tàu điện mới không trễ."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-b-ù-g-u-ǎ-n-X-d-ō-u-k-ế-t-q-u-ả', 'HSK 4', 31, 'CẤU TRÚC 不管……都……', 'bùguǎnXdōukết quả', 'bongu', 'Cấu trúc 不管……都…… — điểm ngữ pháp HSK 4.', '[["不管","key"],["Từ nghi vấn/lựa chọn","key"],["都","key"],["Kết quả","key"]]', '["Người Việt hay quên 都 ở vế sau: ","不管多忙，我陪你"," là thiếu, phải nói 不管多忙，我都陪你。"]', '[{"hz":"不管多忙，他都坚持锻炼。","py":"Bùguǎn duō máng, tā dōu jiānchí duànliàn.","vi":"Dù bận đến đâu anh ấy vẫn kiên trì rèn luyện."},{"hz":"不管你去不去，我都要去。","py":"Bùguǎn nǐ qù bu qù, wǒ dōu yào qù.","vi":"Dù bạn có đi hay không thì tôi vẫn đi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-r-ú-g-u-ǒ-g-i-ả-đ-ị-n-h-j-i-ù-k-ế-t-q-u-ả', 'HSK 4', 32, 'CẤU TRÚC 如果……就……', 'rúguǒgiả địnhjiùkết quả', 'bongu', 'Cấu trúc 如果……就…… — điểm ngữ pháp HSK 4.', '[["如果","key"],["Giả định","key"],["就","key"],["Kết quả","key"]]', '["Người Việt hay bỏ 就 ở vế sau: ","如果你来，我高兴"," tự nhiên hơn phải là 如果你来，我就很高兴。"]', '[{"hz":"如果明天下雨，我们就不去了。","py":"Rúguǒ míngtiān xià yǔ, wǒmen jiù bú qù le.","vi":"Nếu mai trời mưa thì chúng ta không đi nữa."},{"hz":"如果你不舒服，就早点儿休息。","py":"Rúguǒ nǐ bù shūfu, jiù zǎodiǎnr xiūxi.","vi":"Nếu bạn không khỏe thì nghỉ sớm đi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-j-ì-r-á-n-s-ự-k-i-ệ-n-j-i-ù-k-ế-t-l-u-ậ-n', 'HSK 4', 33, 'CẤU TRÚC 既然……就……', 'jìránsự kiệnjiùkết luận', 'bongu', 'Cấu trúc 既然……就…… — điểm ngữ pháp HSK 4.', '[["既然","key"],["Sự kiện đã rõ","key"],["就","key"],["Kết luận/khuyên","key"]]', '["Người Việt hay nhầm 既然 với 如果: ","如果你已经来了"," khi muốn nói 既然来了 — 既然 dùng cho việc đã xảy ra."]', '[{"hz":"既然来了，就坐一会儿吧。","py":"Jìrán lái le, jiù zuò yíhuìr ba.","vi":"Đã đến rồi thì ngồi lại chút đi."},{"hz":"既然你不会，我来教你。","py":"Jìrán nǐ bú huì, wǒ lái jiāo nǐ.","vi":"Đã thế bạn không biết thì tôi dạy."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-c-h-ú-l-e-A-y-ǐ-w-à-i-/-h-á-i-/-d-ō-u-B', 'HSK 4', 34, 'CẤU TRÚC 除了……以外', 'chúleAyǐwài/hái/dōuB', 'bongu', 'Cấu trúc 除了……以外 — điểm ngữ pháp HSK 4.', '[["除了","key"],["A","key"],["以外/还/都","key"],["B","key"]]', '["Người Việt hay quên 还/都: ","除了汉语，他学英语"," là dở, phải nói 除了汉语以外，他还学英语。"]', '[{"hz":"除了汉语以外，他还会说法语。","py":"Chúle Hànyǔ yǐwài, tā hái huì shuō Fǎyǔ.","vi":"Ngoài tiếng Trung, anh ấy còn biết tiếng Pháp."},{"hz":"除了你，大家都到了。","py":"Chúle nǐ, dàjiā dōu dào le.","vi":"Ngoài bạn ra thì ai cũng đến rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-A-h-u-ò-z-h-ě-B', 'HSK 4', 35, 'LIÊN TỪ 或者', 'AhuòzhěB', 'bongu', 'Liên từ 或者 — điểm ngữ pháp HSK 4.', '[["A","key"],["或者","key"],["B","key"]]', '["Người Việt hay dùng 还是 trong câu trần thuật: ","我喝水还是喝茶"," ở câu khẳng định là sai, phải nói 我喝水或者喝茶。"]', '[{"hz":"我们坐火车或者飞机去。","py":"Wǒmen zuò huǒchē huòzhě fēijī qù.","vi":"Chúng ta đi bằng tàu hỏa hoặc máy bay."},{"hz":"早上喝牛奶或者豆浆都行。","py":"Zǎoshang hē niúnǎi huòzhě dòujiāng dōu xíng.","vi":"Sáng uống sữa hoặc sữa đậu nành đều được."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-A-h-á-i-s-h-ì-B', 'HSK 4', 36, 'LIÊN TỪ 还是（câu hỏi lựa chọn）', 'AháishìB?', 'bongu', 'Liên từ 还是（câu hỏi lựa chọn） — điểm ngữ pháp HSK 4.', '[["A","key"],["还是","key"],["B","key"],["(?)","key"]]', '["Người Việt hay dùng 或者 trong câu hỏi lựa chọn: ","你喝茶或者咖啡？"," là sai, phải nói 你喝茶还是咖啡？"]', '[{"hz":"你喝茶还是咖啡？","py":"Nǐ hē chá háishì kāfēi?","vi":"Bạn uống trà hay cà phê?"},{"hz":"我们星期六去还是星期日去？","py":"Wǒmen xīngqīliù qù háishì xīngqīrì qù?","vi":"Chúng ta đi thứ Bảy hay Chủ Nhật?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-q-u-è-V-/-A-d-j', 'HSK 4', 37, 'PHÓ TỪ 却', 'SquèV/Adj', 'bongu', 'Phó từ 却 — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["却","key"],["V/Tính từ","key"]]', '["Người Việt hay đặt 却 đầu câu: ","却他不喜欢"," là sai, phải nói 他却不喜欢。"]', '[{"hz":"他很努力，成绩却不好。","py":"Tā hěn nǔlì, chéngjì què bù hǎo.","vi":"Anh ấy rất chăm nhưng điểm lại không tốt."},{"hz":"都十点了，他却还没起床。","py":"Dōu shí diǎn le, tā què hái méi qǐchuáng.","vi":"Mười giờ rồi mà anh ấy vẫn chưa dậy."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-A-B-s-h-è-n-z-h-ì-X', 'HSK 4', 38, 'PHÓ TỪ 甚至', 'A, BshènzhìX', 'bongu', 'Phó từ 甚至 — điểm ngữ pháp HSK 4.', '[["Các vế tăng tiến","key"],["甚至","key"],["Cực đại","key"]]', '["Người Việt hay dùng 甚至 nối hai vế đối lập: ","他喜欢茶甚至不喜欢咖啡"," là sai logic — 甚至 diễn tả mức tiến thêm."]', '[{"hz":"这本书很有意思，我甚至读了两遍。","py":"Zhè běn shū hěn yǒu yìsi, wǒ shènzhì dú le liǎng biàn.","vi":"Cuốn sách này rất hay, tôi thậm chí đọc đến hai lượt."},{"hz":"他会说法语、日语，甚至阿拉伯语。","py":"Tā huì shuō Fǎyǔ, Rìyǔ, shènzhì Ālābóyǔ.","vi":"Anh ấy biết tiếng Pháp, tiếng Nhật, thậm chí cả tiếng Ả Rập."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-j-ǐ-n-g-u-ǎ-n-A-d-à-n-/-h-á-i-s-h-ì-B', 'HSK 4', 39, 'LIÊN TỪ 尽管……但', 'jǐnguǎnAdàn/háishìB', 'bongu', 'Liên từ 尽管……但 — điểm ngữ pháp HSK 4.', '[["尽管","key"],["Vế nhượng bộ","key"],["但/还是","key"],["Vế chính","key"]]', '["Người Việt hay nhầm 尽管 với 不管: ","尽管下不下雨"," là sai — 不管 mới搭配 câu hỏi, 尽管 dùng cho sự thật."]', '[{"hz":"尽管很累，他还是完成了作业。","py":"Jǐnguǎn hěn lèi, tā háishì wánchéng le zuòyè.","vi":"Tuy mệt nhưng anh ấy vẫn làm xong bài."},{"hz":"尽管大家反对，他还是决定去。","py":"Jǐnguǎn dàjiā fǎnduì, tā háishì juédìng qù.","vi":"Tuy mọi người phản đối nhưng anh ấy vẫn quyết định đi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-A-y-ī-n-c-ǐ-B', 'HSK 4', 40, 'LIÊN TỪ 因此', 'AyīncǐB', 'bongu', 'Liên từ 因此 — điểm ngữ pháp HSK 4.', '[["Vế 1","key"],["因此","key"],["Vế kết quả","key"]]', '["Người Việt hay dùng 因此 cùng 所以 một lúc: ","所以他因此没来"," là thừa — có 因此 thì bỏ 所以。"]', '[{"hz":"他生病了，因此没来上课。","py":"Tā shēngbìng le, yīncǐ méi lái shàngkè.","vi":"Anh ấy ốm nên không đến học."},{"hz":"物价上涨，因此很多人开始省钱。","py":"Wùjià shàngzhǎng, yīncǐ hěn duō rén kāishǐ shěngqián.","vi":"Giá cả tăng, vì thế nhiều người bắt đầu tiết kiệm."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-y-ó-u-a-g-e-n-t-V', 'HSK 4', 41, 'GIỚI TỪ 由', 'SyóuagentV', 'bongu', 'Giới từ 由 — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["由","key"],["Người đảm nhiệm","key"],["Động từ","key"]]', '["Người Việt hay nhầm 由 với 从: ","这个问题从老师决定"," là sai, phải nói 这个问题由老师决定。"]', '[{"hz":"这个问题由老师决定。","py":"Zhège wèntí yóu lǎoshī juédìng.","vi":"Vấn đề này do thầy giáo quyết định."},{"hz":"晚饭由爸爸做。","py":"Wǎnfàn yóu bàba zuò.","vi":"Bữa tối do bố nấu."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-d-u-ì-đ-ố-i-t-ư-ợ-n-g-V-/-A-d-j', 'HSK 4', 42, 'GIỚI TỪ 对', 'Sduìđối tượngV/Adj', 'bongu', 'Giới từ 对 — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["对","key"],["Đối tượng","key"],["V/Tính từ","key"]]', '["Người Việt hay nhầm 对 với 给: ","他给我很好"," là sai, phải nói 他对我很好。"]', '[{"hz":"他对朋友很热情。","py":"Tā duì péngyou hěn rèqíng.","vi":"Anh ấy rất nhiệt tình với bạn bè."},{"hz":"汉语对工作很有帮助。","py":"Hànyǔ duì gōngzuò hěn yǒu bāngzhù.","vi":"Tiếng Trung rất có ích cho công việc."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-d-u-ì-X-l-á-i-s-h-u-ō-n-h-ậ-n-x-é-t', 'HSK 4', 43, 'CẤU TRÚC 对……来说', 'duìXláishuōnhận xét', 'bongu', 'Cấu trúc 对……来说 — điểm ngữ pháp HSK 4.', '[["对","key"],["Người/cái gì","key"],["来说","key"],["Nhận xét","key"]]', '["Người Việt hay bỏ 来说: ","对我"," thôi là thiếu, phải nói 对我来说。"]', '[{"hz":"对我来说，健康最重要。","py":"Duì wǒ láishuō, jiànkāng zuì zhòngyào.","vi":"Đối với tôi, sức khỏe là quan trọng nhất."},{"hz":"对学生来说，这个练习有点难。","py":"Duì xuésheng láishuō, zhège liànxí yǒudiǎn nán.","vi":"Đối với học sinh, bài tập này hơi khó."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-g-ě-i-n-g-ư-ờ-i-n-h-ậ-n-V-+-O', 'HSK 4', 44, 'GIỚI TỪ 给', 'Sgěingười nhậnV+O', 'bongu', 'Giới từ 给 — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["给","key"],["Người nhận","key"],["Động từ + tân ngữ","key"]]', '["Người Việt hay quên 给: ","我打电话妈妈"," là sai, phải nói 我给妈妈打电话。"]', '[{"hz":"我给妈妈打电话。","py":"Wǒ gěi māma dǎ diànhuà.","vi":"Tôi gọi điện cho mẹ."},{"hz":"他给我买了一本书。","py":"Tā gěi wǒ mǎi le yì běn shū.","vi":"Anh ấy mua cho tôi một cuốn sách."},{"hz":"请给我看看。","py":"Qǐng gěi wǒ kànkan.","vi":"Cho tôi xem với."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-x-i-à-n-g-/-w-ǎ-n-g-/-c-h-á-o-h-ư-ớ-n-g-V', 'HSK 4', 45, 'GIỚI TỪ 向/往/朝', 'Sxiàng/wǎng/cháohướngV', 'bongu', 'Giới từ 向/往/朝 — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["向/往/朝","key"],["Hướng","key"],["Động từ","key"]]', '["Người Việt hay dùng 往 với người học: ","我往他学习"," là sai, phải nói 我向他学习。"]', '[{"hz":"我们往东走。","py":"Wǒmen wǎng dōng zǒu.","vi":"Chúng ta đi về phía đông."},{"hz":"他向同学们介绍了自己。","py":"Tā xiàng tóngxuémen jièshào le zìjǐ.","vi":"Anh ấy giới thiệu bản thân với các bạn."},{"hz":"往前看！","py":"Wǎng qián kàn!","vi":"Nhìn về phía trước!"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-c-ó-n-g-đ-ầ-u-d-à-o-c-u-ố-i', 'HSK 4', 46, 'CẤU TRÚC 从……到……', 'cóngđầudàocuối', 'bongu', 'Cấu trúc 从……到…… — điểm ngữ pháp HSK 4.', '[["从","key"],["Điểm đầu","key"],["到","key"],["Điểm cuối","key"]]', '["Người Việt hay đảo điểm đầu cuối: ","从九点到达八点"," là sai, phải nói 从八点到九点。"]', '[{"hz":"我从家到学校要走二十分钟。","py":"Wǒ cóng jiā dào xuéxiào yào zǒu èrshí fēnzhōng.","vi":"Từ nhà đến trường tôi phải đi hai mươi phút."},{"hz":"商店从早上九点开到晚上九点。","py":"Shāngdiàn cóng zǎoshang jiǔ diǎn kāi dào wǎnshang jiǔ diǎn.","vi":"Cửa hàng mở từ sáng 9 giờ đến tối 9 giờ."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-A-l-í-B-k-h-o-ả-n-g-c-á-c-h', 'HSK 4', 47, 'GIỚI TỪ 离', 'AlíBkhoảng cách', 'bongu', 'Giới từ 离 — điểm ngữ pháp HSK 4.', '[["A","key"],["离","key"],["B","key"],["Khoảng cách/Adj","key"]]', '["Người Việt hay dùng 从 thay 离: ","学校从我家的距离"," là kiểu dịch máy, phải nói 学校离我家很近。"]', '[{"hz":"学校离我家很近。","py":"Xuéxiào lí wǒ jiā hěn jìn.","vi":"Trường cách nhà tôi rất gần."},{"hz":"现在离考试还有一个月。","py":"Xiànzài lí kǎoshì hái yǒu yí ge yuè.","vi":"Bây giờ còn một tháng nữa mới thi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-à-n-/-à-n-z-h-à-o-t-i-ê-u-c-h-u-ẩ-n-V', 'HSK 4', 48, 'GIỚI TỪ 按/按照', 'àn/ànzhàotiêu chuẩnV', 'bongu', 'Giới từ 按/按照 — điểm ngữ pháp HSK 4.', '[["按/按照","key"],["Tiêu chuẩn/quy định","key"],["Động từ","key"]]', '["Người Việt hay dùng 跟 thay 按: ","跟规定做"," là sai, phải nói 按规定做。"]', '[{"hz":"按照老师说的做。","py":"Ànzhào lǎoshī shuō de zuò.","vi":"Làm theo những gì thầy nói."},{"hz":"我们按时间表上课。","py":"Wǒmen àn shíjiānbiǎo shàngkè.","vi":"Chúng tôi học theo thời khóa biểu."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-g-ē-n-j-ù-c-ă-n-c-ứ-n-h-ậ-n-đ-ị-n-h', 'HSK 4', 49, 'GIỚI TỪ 根据', 'gēnjùcăn cứnhận định', 'bongu', 'Giới từ 根据 — điểm ngữ pháp HSK 4.', '[["根据","key"],["Căn cứ","key"],["Nhận định/Động từ","key"]]', '["Người Việt hay nhầm 根据 với 按照: ","根据规定进来"," là sai — quy định cứng nhắc dùng 按照，dựa vào nguồn thông tin mới用 根据。"]', '[{"hz":"根据天气预报，明天有雨。","py":"Gēnjù tiānqì yùbào, míngtiān yǒu yǔ.","vi":"Theo dự báo thời tiết, mai có mưa."},{"hz":"根据我的经验，这个方法很有用。","py":"Gēnjù wǒ de jīngyàn, zhège fāngfǎ hěn yǒuyòng.","vi":"Theo kinh nghiệm của tôi, cách này rất hữu ích."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-w-è-i-l-e-m-ụ-c-đ-í-c-h-h-à-n-h-đ-ộ-n-g', 'HSK 4', 50, 'GIỚI TỪ 为了', 'wèilemục đíchhành động', 'bongu', 'Giới từ 为了 — điểm ngữ pháp HSK 4.', '[["为了","key"],["Mục đích","key"],["Hành động","key"]]', '["Người Việt hay nhầm 为了 với 因为: ","为了他病了"," là sai — nguyên nhân dùng 因为，mục đích mới用 为了。"]', '[{"hz":"为了考试，他每天复习。","py":"Wèile kǎoshì, tā měitiān fùxí.","vi":"Vì kỳ thi nên cậu ấy ôn bài mỗi ngày."},{"hz":"我为了健康开始运动。","py":"Wǒ wèile jiànkāng kāishǐ yùndòng.","vi":"Vì sức khỏe nên tôi bắt đầu vận động."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-c-h-è-n-t-h-ờ-i-đ-i-ể-m-V', 'HSK 4', 51, 'GIỚI TỪ 趁', 'chènthời điểmV', 'bongu', 'Giới từ 趁 — điểm ngữ pháp HSK 4.', '[["趁","key"],["Cơ hội/thời điểm","key"],["Động từ","key"]]', '["Người Việt hay bỏ hành động sau 趁: ","趁年轻"," một mình chưa xong, phải nói 趁年轻多学点儿东西。"]', '[{"hz":"趁年轻，多学点儿东西。","py":"Chèn niánqīng, duō xué diǎnr dōngxi.","vi":"Nhân còn trẻ, học thêm chút."},{"hz":"趁热吃吧。","py":"Chèn rè chī ba.","vi":"Ăn khi còn nóng đi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-t-ì-n-h-h-u-ố-n-g-V-/-A-d-j-l-e', 'HSK 4', 52, 'TRỢ TỪ 了（biến đổi tình huống）', 'tình huốngV/Adjle', 'bongu', 'Trợ từ 了（biến đổi tình huống） — điểm ngữ pháp HSK 4.', '[["Tình huống mới","key"],["V/Tính từ","key"],["了","key"]]', '["Người Việt hay quên 了 diễn tả thay đổi: ","现在我不喝咖啡"," khi so với trước thì phải nói 现在我不喝咖啡了。"]', '[{"hz":"他会开车了。","py":"Tā huì kāichē le.","vi":"Anh ấy biết lái xe rồi."},{"hz":"下雨了。","py":"Xià yǔ le.","vi":"Trời mưa rồi."},{"hz":"我不吃甜的了。","py":"Wǒ bù chī tián de le.","vi":"Tôi không ăn đồ ngọt nữa rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-V-g-u-ò-s-ố-l-ầ-n', 'HSK 4', 53, 'TRỢ TỪ 过（kinh nghiệm）', 'SVguò(số lần)', 'bongu', 'Trợ từ 过（kinh nghiệm） — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["Động từ","key"],["过","key"],["(Số lần)","key"]]', '["Người Việt hay nhầm 过 với 了: ","我去了北京"," là hành động đã xong\u003b kinh nghiệm phải nói 我去过北京。"]', '[{"hz":"我去过中国两次。","py":"Wǒ qù guo Zhōngguó liǎng cì.","vi":"Tôi từng đến Trung Quốc hai lần."},{"hz":"你吃过北京烤鸭吗？","py":"Nǐ chī guo Běijīng kǎoyā ma?","vi":"Bạn đã từng ăn vịt quay Bắc Kinh chưa?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-V--z-h-e-V-', 'HSK 4', 54, 'TRỢ TỪ 着（tình trạng kéo dài）', 'SV1zheV2', 'bongu', 'Trợ từ 着（tình trạng kéo dài） — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["Động từ 1","key"],["着","key"],["Động từ 2","key"]]', '["Người Việt hay dùng 了 thay 着: ","他开了电视睡觉"," là sai, phải nói 他开着电视睡觉。"]', '[{"hz":"他开着电视睡觉。","py":"Tā kāizhe diànshì shuìjiào.","vi":"Anh ấy ngủ mà để television bật."},{"hz":"门开着呢。","py":"Mén kāizhe ne.","vi":"Cửa đang mở đấy."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-c-â-u-h-ỏ-i-m-a-/-b-a-/-n-e', 'HSK 4', 55, 'TRỢ TỪ NGỮ KHÍ 吗/吧/呢', 'câu hỏima/ba/ne', 'bongu', 'Trợ từ ngữ khí 吗/吧/呢 — điểm ngữ pháp HSK 4.', '[["Câu/Thành phần hỏi","key"],["吗/吧/呢","key"]]', '["Người Việt hay dùng 吧 cho câu hỏi thật: ","你是学生吧？"," là phỏng đoán\u003b hỏi thật phải nói 你是学生吗？"]', '[{"hz":"你是学生吗？","py":"Nǐ shì xuésheng ma?","vi":"Bạn là học sinh à?"},{"hz":"我们走吧。","py":"Wǒmen zǒu ba.","vi":"Chúng ta đi thôi."},{"hz":"你呢？","py":"Nǐ ne?","vi":"Còn bạn thì sao?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-n-é-n-g-/-h-u-ì-/-k-ě-y-ǐ-V', 'HSK 4', 56, 'ĐỘNG TỪ TRỢ TÌNH 能/会/可以', 'Snéng/huì/kěyǐV', 'bongu', 'Động từ trợ tình 能/会/可以 — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["能/会/可以","key"],["Động từ","key"]]', '["Người Việt hay nhầm 会 với 能: ","我能说汉语"," chỉ đúng khi nói khả năng cụ thể\u003b \"biết\" phải nói 我会说汉语。"]', '[{"hz":"我会说一点儿汉语。","py":"Wǒ huì shuō yìdiǎnr Hànyǔ.","vi":"Tôi biết nói chút tiếng Trung."},{"hz":"今天不能喝酒，我要开车。","py":"Jīntiān bù néng hē jiǔ, wǒ yào kāichē.","vi":"Hôm nay không được rượu, tôi phải lái xe."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-y-ī-n-g-g-ā-i-/-b-ì-x-ū-/-d-ě-i-V', 'HSK 4', 57, '应该/必须/得（děi）', 'Syīnggāi/bìxū/děiV', 'bongu', '应该/必须/得（děi） — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["应该/必须/得","key"],["Động từ","key"]]', '["Người Việt hay đọc 得 thành \"de\": ","我得走了"," 中 得 phải đọc \"děi\" chứ không phải \"de\"。"]', '[{"hz":"你应该早点儿睡觉。","py":"Nǐ yīnggāi zǎodiǎnr shuìjiào.","vi":"Bạn nên ngủ sớm hơn."},{"hz":"我得走了。","py":"Wǒ děi zǒu le.","vi":"Tôi phải đi rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-+-t-h-ờ-i-g-i-a-n-c-á-i-/-j-i-ù-V-/-A-d-j', 'HSK 4', 58, 'PHÓ TỪ 才 và 就', 'S+thời giancái/jiùV/Adj', 'bongu', 'Phó từ 才 và 就 — điểm ngữ pháp HSK 4.', '[["Chủ ngữ + thời điểm","key"],["才/就","key"],["Động từ/Tính từ","key"]]', '["Người Việt hay đảo 才 và 就: ","他才八点来"," là sai, phải nói 他八点才来。"]', '[{"hz":"他八点才来。","py":"Tā bā diǎn cái lái.","vi":"Anh ấy 8 giờ mới đến."},{"hz":"我五分钟就做完了。","py":"Wǒ wǔ fēnzhōng jiù zuò wán le.","vi":"Tôi 5 phút là làm xong."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk4-S-z-à-i-/-y-ò-u-V', 'HSK 4', 59, 'PHÓ TỪ 再 và 又', 'Szài/yòuV', 'bongu', 'Phó từ 再 và 又 — điểm ngữ pháp HSK 4.', '[["Chủ ngữ","key"],["再/又","key"],["Động từ","key"]]', '["Người Việt hay dùng 又 cho tương lai: ","明天我又来"," là sai, tương lai dùng 再：明天我再来。"]', '[{"hz":"请再说一遍。","py":"Qǐng zài shuō yí biàn.","vi":"Xin nói lại lần nữa."},{"hz":"昨天他又迟到了。","py":"Zuótiān tā yòu chídào le.","vi":"Hôm qua anh ấy lại trễ nữa."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-f-ē-i-V-b-ù-k-ě', 'HSK 5', 0, 'CẤU TRÚC 非……不可', 'SfēiVbùkě', 'ba', 'Cấu trúc 非……不可 — điểm ngữ pháp HSK 5.', '[["Chủ ngữ","key"],["非","key"],["Động từ","key"],["不可","key"]]', '["Người Việt hay bỏ 不可: ","他非要去"," chỉ dùng được trong khẩu ngữ\u003b văn viết phải是 他非要去不可。"]', '[{"hz":"他今天非去不可。","py":"Tā jīntiān fēi qù bùkě.","vi":"Hôm nay anh ấy nhất định phải đi."},{"hz":"这件事非你不可。","py":"Zhè jiàn shì fēi nǐ bùkě.","vi":"Việc này không có bạn là không được."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-c-h-à-d-i-ǎ-n-r-m-é-i-V-+-l-e', 'HSK 5', 1, 'CẤU TRÚC 差点儿（没）', 'Schàdiǎnr(méi)V+le', 'ba', 'Cấu trúc 差点儿（没） — điểm ngữ pháp HSK 5.', '[["Chủ ngữ","key"],["差点儿","key"],["(没)","key"],["Động từ + 了","key"]]', '["Người Việt dịch sát từng chữ: ","差点儿没摔倒"," nghĩa là \"suýt ngã\" (chưa ngã), không phải \"chưa đủ để không ngã\"。"]', '[{"hz":"路太滑，我差点儿摔倒了。","py":"Lù tài huá, wǒ chàdiǎnr shuāidǎo le.","vi":"Đường trơn quá, tôi suýt ngã."},{"hz":"我差点儿没赶上火车。","py":"Wǒ chàdiǎnr méi gǎnshang huǒchē.","vi":"Tôi suýt nữa thì lỡ tàu."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-z-h-ī-s-u-ǒ-y-ǐ-k-ế-t-q-u-ả-s-h-ì-y-ī-n-w-è-i-n-g-u-y-ê-n-n-h-â-n', 'HSK 5', 2, 'CẤU TRÚC 之所以……是因为', 'Szhīsuǒyǐkết quảshì yīnwèinguyên nhân', 'ba', 'Cấu trúc 之所以……是因为 — điểm ngữ pháp HSK 5.', '[["Chủ ngữ","key"],["之所以","key"],["Kết quả","key"],["是因为","key"],["Nguyên nhân","key"]]', '["Người Việt hay đảo trật tự: ","他成功是因为努力之所以"," là sai — 之所以 đứng trước vế kết quả."]', '[{"hz":"他之所以成功，是因为非常努力。","py":"Tā zhīsuǒyǐ chénggōng, shì yīnwèi fēicháng nǔlì.","vi":"Anh ấy thành công là vì rất chăm chỉ."},{"hz":"我之所以学汉语，是因为喜欢中国文化。","py":"Wǒ zhīsuǒyǐ xué Hànyǔ, shì yīnwèi xǐhuan Zhōngguó wénhuà.","vi":"Tôi học tiếng Trung là vì yêu văn hóa Trung Quốc."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-l-i-á-n-A-d-à-i-B', 'HSK 5', 3, 'CẤU TRÚC 连……带……', 'liánAdàiB', 'ba', 'Cấu trúc 连……带…… — điểm ngữ pháp HSK 5.', '[["连","key"],["A","key"],["带","key"],["B","key"]]', '["Người Việt hay bỏ 连: ","他吃带拿"," là sai, phải nói 他连吃带拿 (vừa ăn vừa lấy)."]', '[{"hz":"老王连吃带拿，一点也不客气。","py":"Lǎo Wáng lián chī dài ná, yìdiǎn yě bú kèqi.","vi":"Lão Vương vừa ăn vừa cầm, không chút khách sáo."},{"hz":"我们连买带做，准备了一整天。","py":"Wǒmen lián mǎi dài zuò, zhǔnbèi le yì zhěng tiān.","vi":"Chúng tôi vừa mua vừa làm, chuẩn bị cả ngày."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-y-ǔ-q-í-A-b-ù-r-ú-B', 'HSK 5', 4, 'CẤU TRÚC 与其……不如……', 'yǔqíAbùrúB', 'ba', 'Cấu trúc 与其……不如…… — điểm ngữ pháp HSK 5.', '[["与其","key"],["A (kém hơn)","key"],["不如","key"],["B (tốt hơn)","key"]]', '["Người Việt hay đảo hai vế: ","不如在家，与其出去"," là sai — 与其 phải mở đầu vế bị bỏ đi."]', '[{"hz":"与其在家看电视，不如出去运动。","py":"Yǔqí zài jiā kàn diànshì, bùrú chūqù yùndòng.","vi":"Thà ra ngoài vận động còn hơn ngồi nhà xem TV."},{"hz":"与其等他，不如我们自己先做。","py":"Yǔqí děng tā, bùrú wǒmen zìjǐ xiān zuò.","vi":"Thà tự mình làm trước còn hơn chờ anh ấy."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-n-ì-n-g-k-ě-A-y-ě-b-ù-B', 'HSK 5', 5, 'CẤU TRÚC 宁可……也不……', 'SnìngkěAyěbùB', 'ba', 'Cấu trúc 宁可……也不…… — điểm ngữ pháp HSK 5.', '[["Chủ ngữ","key"],["宁可","key"],["A","key"],["也不","key"],["B","key"]]', '["Người Việt hay dùng 才 thay 也不: ","宁可饿才吃零食"," là sai, phải nói 宁可饿也不吃零食。"]', '[{"hz":"他宁可走路也不坐出租车。","py":"Tā nìngkě zǒulù yěbù zuò chūzūchē.","vi":"Anh ấy thà đi bộ chứ không bắt taxi."},{"hz":"我宁可不去，也不愿意说谎。","py":"Wǒ nìngkě bú qù, yěbù yuànyì shuōhuǎng.","vi":"Tôi thà không đi chứ không chịu nói dối."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-y-à-o-m-e-A-y-à-o-m-e-B', 'HSK 5', 6, 'CẤU TRÚC 要么……要么……', 'yàomeAyàomeB', 'ba', 'Cấu trúc 要么……要么…… — điểm ngữ pháp HSK 5.', '[["要么","key"],["A","key"],["要么","key"],["B","key"]]', '["Người Việt hay trộn 要么 với 或者: ","要么你去，或者我去"," là lộn xộn — hai vế đều用 要么。"]', '[{"hz":"要么你去，要么我去，总得有一个人去。","py":"Yàome nǐ qù, yàome wǒ qù, zǒng děi yǒu yí ge rén qù.","vi":"Hoặc bạn đi hoặc tôi đi, nhất định phải có một người đi."},{"hz":"周末要么在家休息，要么去爬山。","py":"Zhōumò yàome zài jiā xiūxi, yàome qù páshān.","vi":"Cuối tuần hoặc ở nhà nghỉ hoặc đi leo núi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-n-ǎ-p-à-g-i-ả-đ-ị-n-h-y-ě-k-ế-t-q-u-ả', 'HSK 5', 7, 'CẤU TRÚC 哪怕……也……', 'nǎpàgiả địnhyěkết quả', 'ba', 'Cấu trúc 哪怕……也…… — điểm ngữ pháp HSK 5.', '[["哪怕","key"],["Giả định bất lợi","key"],["也","key"],["Kết quả","key"]]', '["Người Việt hay dùng 就 với 哪怕: ","哪怕下雨就去"," là sai — 哪怕搭配 也：哪怕下雨也去。"]', '[{"hz":"哪怕再难，我也要试试。","py":"Nǎpà zài nán, wǒ yě yào shìshi.","vi":"Dù khó thế nào tôi cũng phải thử."},{"hz":"哪怕只有一个人，我也坚持到底。","py":"Nǎpà zhǐyǒu yí ge rén, wǒ yě jiānchí dàodǐ.","vi":"Dù chỉ còn một mình tôi cũng kiên trì đến cùng."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-y-à-o-b-u-s-h-ì-đ-i-ề-u-k-i-ệ-n-j-i-ù-/-z-ǎ-o-j-i-ù-k-ế-t-q-u-ả', 'HSK 5', 8, 'CẤU TRÚC 要不是……', 'yàobushìđiều kiệnjiù/zǎojiùkết quả', 'ba', 'Cấu trúc 要不是…… — điểm ngữ pháp HSK 5.', '[["要不是","key"],["Điều kiện phủ định","key"],["就/早就","key"],["Kết quả ngược","key"]]', '["Người Việt hay bỏ vế kết quả ngược: ","要不是你帮我"," dừng ở đó là thiếu, phải nói 要不是你帮我，我早就失败了。"]', '[{"hz":"要不是你帮我，我就迟到了。","py":"Yàobushì nǐ bāng wǒ, wǒ jiù chídào le.","vi":"Được bạn giúp chứ không thì tôi trễ mất rồi."},{"hz":"要不是下雨，我们就去爬山了。","py":"Yàobushì xià yǔ, wǒmen jiù qù páshān le.","vi":"Chẳng phải mưa thì chúng ta đã đi leo núi rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-j-í-s-h-ǐ-g-i-ả-đ-ị-n-h-y-ě-k-ế-t-q-u-ả', 'HSK 5', 9, 'LIÊN TỪ 即使……也……', 'jíshǐgiả địnhyěkết quả', 'bongu', 'Liên từ 即使……也…… — điểm ngữ pháp HSK 5.', '[["即使","key"],["Giả định","key"],["也","key"],["Kết quả","key"]]', '["Người Việt hay dùng 但是 với 即使: ","即使失败，但是我再试"," là sai — 即使搭配 也。"]', '[{"hz":"即使失败了，我也不后悔。","py":"Jíshǐ shībài le, wǒ yě bú hòuhuǐ.","vi":"Cho dù thất bại tôi cũng không hối tiếc."},{"hz":"即使下雨，比赛也照常进行。","py":"Jíshǐ xià yǔ, bǐsài yě zhàocháng jìnxíng.","vi":"Cho dù mưa, trận đấu vẫn diễn ra bình thường."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-j-ì-n-g-r-á-n-/-j-ū-r-á-n-s-ự-b-ấ-t-n-g-ờ', 'HSK 5', 10, 'PHÓ TỪ 竟然/居然', 'Sjìngrán/jūránsự bất ngờ', 'bongu', 'Phó từ 竟然/居然 — điểm ngữ pháp HSK 5.', '[["Chủ ngữ","key"],["竟然/居然","key"],["Sự bất ngờ","key"]]', '["Người Việt hay nhầm 果然 với 竟然: ","他果然考了一百分"," là \"đúng như dự đoán\"\u003b bất ngờ mới dùng 竟然/居然。"]', '[{"hz":"他居然一个人搬完了所有的箱子。","py":"Tā jūrán yí ge rén bān wán le suǒyǒu de xiāngzi.","vi":"Anh ấy bất ngờ một mình xách hết mọi thùng."},{"hz":"这么难的题，他竟然做对了。","py":"Zhème nán de tí, tā jìngrán zuò duì le.","vi":"Câu khó thế mà anh ấy bất ngờ làm đúng."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-x-i-ǎ-n-d-e-A-d-j', 'HSK 5', 11, 'ĐỘNG TỪ 显得', 'SxiǎndeAdj', 'hutu', 'Động từ 显得 — điểm ngữ pháp HSK 5.', '[["Chủ ngữ","key"],["显得","key"],["Tính từ (cảm nhận bên ngoài)","key"]]', '["Người Việt hay chèn 很 trước 显得: ","他很显得累"," là sai thứ tự, phải nói 他显得很累。"]', '[{"hz":"她今天显得特别高兴。","py":"Tā jīntiān xiǎnde tèbié gāoxìng.","vi":"Hôm nay trông cô ấy vui vẻ đặc biệt."},{"hz":"这个房间显得很小。","py":"Zhège fángjiān xiǎnde hěn xiǎo.","vi":"Căn phòng này trông khá nhỏ."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-q-í-s-h-í-/-s-h-í-j-ì-s-h-a-n-g-s-ự-t-h-ậ-t', 'HSK 5', 12, 'PHÓ TỪ 其实/实际上', 'qíshí/shíjìshangsự thật', 'bongu', 'Phó từ 其实/实际上 — điểm ngữ pháp HSK 5.', '[["其实/实际上","key"],["Sự thật khác mong đợi","key"]]', '["Người Việt hay dùng cả hai một lúc: ","其实实际上他很忙"," là thừa — chỉ cần một trong hai."]', '[{"hz":"他看起来很凶，其实很热心。","py":"Tā kàn qǐlái hěn xiōng, qíshí hěn rèxīn.","vi":"Nhìn anh ấy dữ, thật ra rất nhiệt tình."},{"hz":"这件事实际上很简单。","py":"Zhè jiàn shì shíjìshang hěn jiǎndān.","vi":"Việc này thực ra rất đơn giản."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-j-i-ǎ-n-z-h-í-c-ự-c-đ-o-a-n', 'HSK 5', 13, 'PHÓ TỪ 简直', 'Sjiǎnzhícực đoan', 'bongu', 'Phó từ 简直 — điểm ngữ pháp HSK 5.', '[["Chủ ngữ","key"],["简直","key"],["是/像/Adj + phóng đại","key"]]', '["Người Việt hay dùng 简直 cho việc bình thường: ","简直他吃了饭"," là sai — 简直 chỉ dùng khi phóng đại: 简直像做梦一样。"]', '[{"hz":"这里简直像天堂一样。","py":"Zhèlǐ jiǎnzhí xiàng tiāntáng yíyàng.","vi":"Nơi này đúng như thiên đường vậy."},{"hz":"他简直不敢相信自己的眼睛。","py":"Tā jiǎnzhí bù gǎn xiāngxìn zìjǐ de yǎnjing.","vi":"Anh ấy thậm chí không dám tin vào mắt mình."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-j-ī-h-ū-X', 'HSK 5', 14, 'PHÓ TỪ 几乎', 'SjīhūX', 'bongu', 'Phó từ 几乎 — điểm ngữ pháp HSK 5.', '[["Chủ ngữ","key"],["几乎","key"],["V/Adj (gần như tuyệt đối)","key"]]', '["Người Việt hay thay 几乎 bằng 简直: ","简直所有人都来了"," là sai — \"gần như tất cả\" phải là 几乎所有人都来了。"]', '[{"hz":"我几乎每天都要喝咖啡。","py":"Wǒ jīhū měitiān dōu yào hē kāfēi.","vi":"Tôi gần như ngày nào cũng uống cà phê."},{"hz":"这两件衣服几乎一样。","py":"Zhè liǎng jiàn yīfu jīhū yíyàng.","vi":"Hai bộ đồ này gần như giống hệt nhau."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-t-ì-n-h-h-u-ố-n-g-f-ǎ-n-é-r-k-ế-t-q-u-ả', 'HSK 5', 15, 'PHÓ TỪ 反而', 'tình huốngfǎn''érkết quả', 'bongu', 'Phó từ 反而 — điểm ngữ pháp HSK 5.', '[["Không như mong đợi","key"],["反而","key"],["Kết quả ngược lại","key"]]', '["Người Việt hay dùng 但是 thay 反而: ","他但是走得更快了"," là sai — chỉ 反而 mới diễn tả \"ngược đời\": 他反而走得更快了。"]', '[{"hz":"雨越下越大，他反而走得越快。","py":"Yǔ yuè xià yuè dà, tā fǎn\u0027ér zǒu de yuè kuài.","vi":"Mưa càng to, anh ấy lại càng đi nhanh."},{"hz":"吃了药，病反而重了。","py":"Chī le yào, bìng fǎn\u0027ér zhòng le.","vi":"Uống thuốc rồi bệnh lại nặng thêm."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-ǒ-u-r-á-n-/-ǒ-u-ě-r-V', 'HSK 5', 16, 'PHÓ TỪ 偶然/偶尔', 'Sǒurán/ǒu''ěrV', 'bongu', 'Phó từ 偶然/偶尔 — điểm ngữ pháp HSK 5.', '[["Chủ ngữ","key"],["偶然/偶尔","key"],["Động từ","key"]]', '["Người Việt hay nhầm hai từ: ","我偶然在家做饭"," khi muốn nói \"thi thoảng\" phải是 我偶尔在家做饭；偶然 mang nghĩa \"tình cờ\"。"]', '[{"hz":"我偶尔在家做饭。","py":"Wǒ ǒu\u0027ěr zài jiā zuòfàn.","vi":"Thi thoảng tôi mới nấu ăn ở nhà."},{"hz":"我们在图书馆偶然遇到了。","py":"Wǒmen zài túshūguǎn ǒurán yùdào le.","vi":"Chúng tôi tình cờ gặp nhau ở thư viện."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-s-h-ā-o-w-ē-i-X-y-ì-d-i-ǎ-n-r-/-y-í-x-i-à', 'HSK 5', 17, 'PHÓ TỪ 稍微', 'shāowēiXyìdiǎnr/yíxià', 'bongu', 'Phó từ 稍微 — điểm ngữ pháp HSK 5.', '[["稍微","key"],["V/Adj","key"],["一点儿/一下","key"]]', '["Người Việt hay quên 一点儿/一下: ","稍微等"," là câu dở, tự nhiên phải是 稍微等一下。"]', '[{"hz":"请稍微等一下。","py":"Qǐng shāowēi děng yíxià.","vi":"Xin chờ một chút."},{"hz":"今天稍微冷一点儿。","py":"Jīntiān shāowēi lěng yìdiǎnr.","vi":"Hôm nay hơi lạnh một chút."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-z-h-ú-j-i-à-n-/-j-i-à-n-j-i-à-n-X', 'HSK 5', 18, 'PHÓ TỪ 逐渐/渐渐', 'Szhújiàn/jiànjiànX', 'bongu', 'Phó từ 逐渐/渐渐 — điểm ngữ pháp HSK 5.', '[["Chủ ngữ","key"],["逐渐/渐渐","key"],["V/Adj + 起来/了","key"]]', '["Người Việt hay dùng 渐渐 cho hành động tức thời: ","渐渐开门"," là sai — 渐渐 chỉ搭配 quá trình: 天渐渐黑了。"]', '[{"hz":"天渐渐黑了。","py":"Tiān jiànjiàn hēi le.","vi":"Trời dần tối rồi."},{"hz":"他的身体逐渐恢复了。","py":"Tā de shēntǐ zhújiàn huīfù le.","vi":"Sức khỏe anh ấy dần hồi phục."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-l-ù-x-ù-/-f-ē-n-f-ē-n-V', 'HSK 5', 19, 'PHÓ TỪ 陆续/纷纷', 'Slùxù/fēnfēnV', 'bongu', 'Phó từ 陆续/纷纷 — điểm ngữ pháp HSK 5.', '[["Chủ ngữ (nhiều)","key"],["陆续/纷纷","key"],["Động từ","key"]]', '["Người Việt hay dùng 纷纷 cho một người: ","我纷纷发言"," là sai — 纷纷 phải với nhiều người: 代表们纷纷发言。"]', '[{"hz":"春天到了，花儿纷纷开了。","py":"Chūntiān dào le, huār fēnfēn kāi le.","vi":"Xuân đến, hoa nở rộ khắp nơi."},{"hz":"同学们陆续走进了教室。","py":"Tóngxuémen lùxù zǒu jìn le jiàoshì.","vi":"Các bạn học sinh lần lượt bước vào lớp."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-c-é-n-g-j-ī-n-g-/-y-ǐ-j-ī-n-g-V-+-g-u-ò-/-l-e', 'HSK 5', 20, 'PHÓ TỪ 曾经 và 已经', 'Scéngjīng/yǐjīngV+guò/le', 'bongu', 'Phó từ 曾经 và 已经 — điểm ngữ pháp HSK 5.', '[["Chủ ngữ","key"],["曾经/已经","key"],["V + 过/了","key"]]', '["Người Việt hay trộn lẫn: ","我曾经去了北京"," là sai — 曾经搭配 过：我曾经去过北京。"]', '[{"hz":"我曾经在北京住过三年。","py":"Wǒ céngjīng zài Běijīng zhù guo sān nián.","vi":"Tôi từng sống ở Bắc Kinh ba năm."},{"hz":"他已经毕业三年了。","py":"Tā yǐjīng bìyè sān nián le.","vi":"Anh ấy tốt nghiệp đã ba năm rồi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-z-h-ō-n-g-y-ú-k-ế-t-q-u-ả', 'HSK 5', 21, 'PHÓ TỪ 终于', 'Szhōngyúkết quả', 'bongu', 'Phó từ 终于 — điểm ngữ pháp HSK 5.', '[["Chủ ngữ","key"],["终于","key"],["V + kết quả mong muốn","key"]]', '["Người Việt hay dùng 终于 cho kết quả xấu: ","终于生病了"," là sai — 终于 chỉ dùng cho kết quả mong ước."]', '[{"hz":"我们终于到了山顶。","py":"Wǒmen zhōngyú dào le shāndǐng.","vi":"Cuối cùng chúng tôi cũng lên đỉnh núi."},{"hz":"这个问题他终于想明白了。","py":"Zhège wèntí tā zhōngyú xiǎng míngbai le.","vi":"Vấn đề này cuối cùng anh ấy cũng nghĩ thông."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-d-à-o-d-ǐ-/-j-i-ū-j-ì-n-g-t-ừ-h-ỏ-i', 'HSK 5', 22, 'PHÓ TỪ 到底/究竟', 'Sdàodǐ/jiūjìngtừ hỏi', 'bongu', 'Phó từ 到底/究竟 — điểm ngữ pháp HSK 5.', '[["Chủ ngữ","key"],["到底/究竟","key"],["Từ nghi vấn","key"]]', '["Người Việt hay dùng 到底 với câu hỏi có/không: ","你到底去吗？"," là sai — phải là câu hỏi có từ hỏi: 你到底去不去？"]', '[{"hz":"你到底去不去？","py":"Nǐ dàodǐ qù bu qù?","vi":"Rốt cuộc bạn có đi không?"},{"hz":"这件事究竟是谁干的？","py":"Zhè jiàn shì jiūjìng shì shéi gàn de?","vi":"Việc này rốt cuộc là ai làm?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-h-é-b-ì-V-n-e', 'HSK 5', 23, 'PHÓ TỪ 何必', 'ShébìV(ne)', 'bongu', 'Phó từ 何必 — điểm ngữ pháp HSK 5.', '[["Chủ ngữ","key"],["何必","key"],["Động từ","key"],["(呢)","key"]]', '["Người Việt hay nhầm 何必 với 为什么: ","你为什么生气"," là hỏi lý do\u003b \"không cần đâu\" mới dùng 何必生气呢？"]', '[{"hz":"都过去了，何必再想呢？","py":"Dōu guòqù le, hébì zài xiǎng ne?","vi":"Đã qua rồi, còn nghĩ làm gì nữa."},{"hz":"何必为小事生气呢？","py":"Hébì wèi xiǎoshì shēngqì ne?","vi":"Vì chuyện nhỏ mà giận làm gì chứ?"}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-f-ǎ-n-z-h-è-n-g-k-ế-t-l-u-ậ-n', 'HSK 5', 24, 'PHÓ TỪ 反正', 'fǎnzhèngkết luận', 'bongu', 'Phó từ 反正 — điểm ngữ pháp HSK 5.', '[["反正","key"],["Kết luận bất biến","key"]]', '["Người Việt hay đặt 反正 cuối câu: ","我不去反正"," là sai — 反正 đứng đầu: 反正我不去。"]', '[{"hz":"反正也没人去，我们就不去了。","py":"Fǎnzhèng yě méi rén qù, wǒmen jiù bú qù le.","vi":"Dù sao cũng không ai đi, vậy chúng ta thôi."},{"hz":"不管你怎么说，反正我不去。","py":"Bùguǎn nǐ zěnme shuō, fǎnzhèng wǒ bú qù.","vi":"Dù bạn nói gì thì tôi cũng chẳng đi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-c-á-c-ý-t-r-ư-ớ-c-z-ǒ-n-g-z-h-ī-/-z-ǒ-n-g-é-r-y-á-n-z-h-ī-t-ổ-n-g-k-ế-t', 'HSK 5', 25, 'LIÊN TỪ 总之/总而言之', 'các ý trướczǒngzhī/zǒng''éryánzhītổng kết', 'bongu', 'Liên từ 总之/总而言之 — điểm ngữ pháp HSK 5.', '[["Các ý trước","key"],["总之/总而言之","key"],["Tổng kết","key"]]', '["Người Việt hay dùng 总之 cho nguyên nhân: ","总之他病了，所以没来"," là sai — 总之 chỉ kết luận, không phải \"vì vậy\"。"]', '[{"hz":"总之，这次旅行很开心。","py":"Zǒngzhī, zhè cì lǚxíng hěn kāixīn.","vi":"Tóm lại, chuyến đi lần này rất vui."},{"hz":"总而言之，健康比钱重要。","py":"Zǒng\u0027éryánzhī, jiànkāng bǐ qián zhòngyào.","vi":"Tóm một câu, sức khỏe quan trọng hơn tiền."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-đ-i-ề-u-k-i-ệ-n-f-ǒ-u-z-é-/-y-à-o-b-u-r-á-n-k-ế-t-q-u-ả', 'HSK 5', 26, 'LIÊN TỪ 否则/要不然', 'điều kiệnfǒuzé/yàoburánkết quả', 'bongu', 'Liên từ 否则/要不然 — điểm ngữ pháp HSK 5.', '[["Điều kiện/cảnh báo","key"],["否则/要不然","key"],["Kết quả trái chiều","key"]]', '["Người Việt hay dùng hai từ một lúc: ","否则要不然要迟到了"," là sai — chỉ chọn một: 否则要迟到了。"]', '[{"hz":"快点儿走，否则要迟到了。","py":"Kuàidiǎnr zǒu, fǒuzé yào chídào le.","vi":"Đi nhanh lên, không thì trễ đấy."},{"hz":"你得多穿点儿，要不然会感冒。","py":"Nǐ děi duō chuān diǎnr, yàoburán huì gǎnmào.","vi":"Bạn phải mặc thêm, không thì cảm mất."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-t-ì-n-h-h-u-ố-n-g-y-ú-s-h-ì-h-à-n-h-đ-ộ-n-g', 'HSK 5', 27, 'LIÊN TỪ 于是', 'tình huốngyúshìhành động', 'bongu', 'Liên từ 于是 — điểm ngữ pháp HSK 5.', '[["Tình huống","key"],["于是","key"],["Hành động tiếp theo","key"]]', '["Người Việt hay nhầm 于是 với 因此: ","他病了于是没来上课"," thì 用 因此 đúng hơn — 于是 diễn tả hành động nối tiếp."]', '[{"hz":"他看见一家书店，于是进去看了看。","py":"Tā kànjiàn yì jiā shūdiàn, yúshì jìnqù kànle kan.","vi":"Anh ấy thấy một nhà sách, bèn đi vào xem thử."},{"hz":"天黑了，于是我们回家了。","py":"Tiān hēi le, yúshì wǒmen huí jiā le.","vi":"Trời tối, thế là chúng tôi về nhà."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-c-á-c-h-t-h-ứ-c-c-ó-n-g-é-r-k-ế-t-q-u-ả', 'HSK 5', 28, 'LIÊN TỪ 从而', 'cách thứccóng''érkết quả', 'bongu', 'Liên từ 从而 — điểm ngữ pháp HSK 5.', '[["Hành động/cách","key"],["从而","key"],["Kết quả thúc đẩy","key"]]', '["Người Việt hay dùng 从而 cho chuyện đời thường: ","我吃了饭从而去睡觉"," là sai — 从而 trang trọng, văn viết: 从而提高效率。"]', '[{"hz":"新方法大大提高了效率，从而降低了成本。","py":"Xīn fāngfǎ dàdà tígāo le xiàolǜ, cóng\u0027ér jiàngdī le chéngběn.","vi":"Cách mới tăng hiệu quả nhiều, qua đó giảm chi phí."},{"hz":"他坚持锻炼，从而增强了体质。","py":"Tā jiānchí duànliàn, cóng\u0027ér zēngqiáng le tǐzhì.","vi":"Anh ấy kiên trì rèn luyện, nhờ thế thể lực tốt hơn."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-ý-c-h-í-n-h-z-h-ì-y-ú-c-h-ủ-đ-ề-p-h-ụ', 'HSK 5', 29, 'GIỚI TỪ 至于', 'ý chínhzhìyúchủ đề phụ', 'bongu', 'Giới từ 至于 — điểm ngữ pháp HSK 5.', '[["Ý chính","key"],["至于","key"],["Chủ đề phụ","key"]]', '["Người Việt hay dùng 至于 mở đầu cuộc nói: ","至于工资，我们再谈"," đứng một mình đầu bài là sai — phải nói ý chính trước."]', '[{"hz":"我们先谈工作，至于工资，以后再说。","py":"Wǒmen xiān tán gōngzuò, zhìyú gōngzī, yǐhòu zài shuō.","vi":"Trước ta bàn công việc, còn lương thì nói sau."},{"hz":"书我已经买好了，至于什么时候读，再说吧。","py":"Shū wǒ yǐjīng mǎi hǎo le, zhìyú shénme shíhou dú, zài shuō ba.","vi":"Sách đã mua rồi, còn khi nào đọc thì tính sau."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-g-u-ā-n-y-ú-/-d-u-ì-y-ú-đ-ố-i-t-ư-ợ-n-g-n-h-ậ-n-x-é-t', 'HSK 5', 30, 'GIỚI TỪ 关于/对于', 'guānyú/duìyúđối tượngnhận xét', 'bongu', 'Giới từ 关于/对于 — điểm ngữ pháp HSK 5.', '[["关于/对于","key"],["Đối tượng","key"],["Nhận xét","key"]]', '["Người Việt hay trộn hai giới từ: ","对于这本书的内容简介"," nên dùng 关于 — phạm vi rộng用 关于，đối tượng cụ thể用 对于。"]', '[{"hz":"关于这件事，我不太了解。","py":"Guānyú zhè jiàn shì, wǒ bú tài liǎojiě.","vi":"Về chuyện này, tôi không rõ lắm."},{"hz":"对于他的做法，大家有不同的看法。","py":"Duìyú tā de zuòfǎ, dàjiā yǒu bùtóng de kànfǎ.","vi":"Về cách làm của anh ấy, mọi người có ý kiến khác nhau."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-A-B-j-í-/-y-ǐ-j-í-C', 'HSK 5', 31, 'LIÊN TỪ 及/以及', 'A、Bjí/yǐjíC', 'bongu', 'Liên từ 及/以及 — điểm ngữ pháp HSK 5.', '[["A、B","key"],["及/以及","key"],["C","key"]]', '["Người Việt hay lặp 和 cùng 以及 thừa: ","和词典以及本子和笔"," là lộn xộn — nối dài dùng 以及 ở cuối: 笔、本子以及词典。"]', '[{"hz":"请带上笔、本子以及词典。","py":"Qǐng dài shang bǐ, běnzi yǐjí cídiǎn.","vi":"Mang theo bút, vở và từ điển."},{"hz":"老师、学生及家长都参加了。","py":"Lǎoshī, xuésheng jí jiāzhǎng dōu cānjiā le.","vi":"Giáo viên, học sinh cùng phụ huynh đều tham gia."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-l-ý-d-o--h-é-k-u-à-n-g-/-k-u-à-n-g-q-i-ě-l-ý-d-o-', 'HSK 5', 32, 'LIÊN TỪ 何况/况且', 'lý do 1hékuàng/kuàngqiělý do 2', 'bongu', 'Liên từ 何况/况且 — điểm ngữ pháp HSK 5.', '[["Lý do 1","key"],["何况/况且","key"],["Lý do mạnh hơn","key"]]', '["Người Việt hay dùng 何况 mở đầu câu chuyện: ","何况我们没时间"," đứng một mình đầu bài là sai — phải nối sau một ý trước."]', '[{"hz":"这个地方太远，何况我们也没有时间。","py":"Zhège dìfang tài yuǎn, hékuàng wǒmen yě méi shíjiān.","vi":"Chỗ này quá xa, hơn nữa chúng tôi cũng không có thời gian."},{"hz":"孩子很累了，况且天也晚了，我们回去吧。","py":"Háizi hěn lèi le, kuàngqiě tiān yě wǎn le, wǒmen huíqù ba.","vi":"Con mệt rồi, lại thêm trời tối, mình về đi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-f-á-n-s-h-ì-l-o-ạ-i-d-ō-u-k-ế-t-q-u-ả', 'HSK 5', 33, 'PHÓ TỪ 凡是……都', 'fánshìloạidōukết quả', 'bongu', 'Phó từ 凡是……都 — điểm ngữ pháp HSK 5.', '[["凡是","key"],["Tất cả thuộc loại đó","key"],["都","key"],["Kết quả","key"]]', '["Người Việt hay quên 都: ","凡是我喜欢的书我都买"," — nếu thiếu 都 (凡是我喜欢的书我买) là câu dở."]', '[{"hz":"凡是他答应的事，他都做到。","py":"Fánshì tā dāying de shì, tā dōu zuòdào.","vi":"Chuyện nào anh ấy hứa đều làm được."},{"hz":"凡是考试他都提前准备。","py":"Fánshì kǎoshì tā dōu tíqián zhǔnbèi.","vi":"Kỳ thi nào cậu ấy đều chuẩn bị trước."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-y-ī-d-à-n-đ-i-ề-u-k-i-ệ-n-k-ế-t-q-u-ả', 'HSK 5', 34, 'PHÓ TỪ 一旦', 'yīdànđiều kiệnkết quả', 'bongu', 'Phó từ 一旦 — điểm ngữ pháp HSK 5.', '[["一旦","key"],["Điều kiện (không đảo ngược)","key"],["Kết quả","key"]]', '["Người Việt hay dùng 一旦 cho việc đã xảy ra: ","我一旦去了北京了"," là sai — 一旦 là giả định: 一旦决定，就不要放弃。"]', '[{"hz":"一旦决定了，就不要放弃。","py":"Yīdàn juédìng le, jiù búyào fàngqì.","vi":"Một khi quyết định rồi thì đừng bỏ cuộc."},{"hz":"一旦错过，就很难再见到。","py":"Yīdàn cuòguò, jiù hěn nán zài jiàndào.","vi":"Một khi lỡ mất thì khó gặp lại."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-z-ì-c-ó-n-g-t-h-ờ-i-đ-i-ể-m-y-ǐ-l-á-i-k-ế-t-q-u-ả', 'HSK 5', 35, 'GIỚI TỪ 自从', 'zìcóngthời điểm(yǐlái)kết quả', 'bongu', 'Giới từ 自从 — điểm ngữ pháp HSK 5.', '[["自从","key"],["Thời điểm","key"],["(以后/以来)","key"],["Kết quả","key"]]', '["Người Việt hay quên 以来/以后: ","自从大学毕业我想回去"," là câu dở, phải是 自从毕业以来，我一直想回去。"]', '[{"hz":"自从搬家以来，我们很少见面。","py":"Zìcóng bānjiā yǐlái, wǒmen hěn shǎo jiànmiàn.","vi":"Từ khi chuyển nhà, chúng tôi ít gặp nhau."},{"hz":"自从毕业，我们再也没见过。","py":"Zìcóng bìyè, wǒmen zài yě méi jiànguò.","vi":"Từ khi tốt nghiệp, chúng tôi chưa gặp lại."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-s-u-í-z-h-e-s-ự-t-h-a-y-đ-ổ-i-t-h-a-y-đ-ổ-i-t-h-e-o', 'HSK 5', 36, 'GIỚI TỪ 随着', 'suízhesự thay đổithay đổi theo', 'bongu', 'Giới từ 随着 — điểm ngữ pháp HSK 5.', '[["随着","key"],["Sự thay đổi","key"],["……也/越来越","key"]]', '["Người Việt hay bỏ 着: ","随经济发展"," trong văn viết phải是 随着经济的发展。"]', '[{"hz":"随着经济的发展，人们的生活越来越好。","py":"Suízhe jīngjì de fāzhǎn, rénmen de shēnghuó yuèláiyuè hǎo.","vi":"Cùng với kinh tế phát triển, đời sống ngày càng tốt hơn."},{"hz":"随着年龄的增长，他成熟了很多。","py":"Suízhe niánlíng de zēngzhǎng, tā chéngshú le hěn duō.","vi":"Cùng tuổi tác tăng, anh ấy trưởng thành hơn nhiều."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-y-á-n-z-h-e-/-s-h-ù-n-z-h-e-đ-ư-ờ-n-g-V', 'HSK 5', 37, 'GIỚI TỪ 沿着/顺着', 'yánzhe/shùnzheđườngV', 'bongu', 'Giới từ 沿着/顺着 — điểm ngữ pháp HSK 5.', '[["沿着/顺着","key"],["Đường/nơi","key"],["Động từ","key"]]', '["Người Việt hay nhầm 沿着 với 向: ","向河走"," là \"đi về phía sông\"\u003b \"đi dọc sông\" phải是 沿着河走。"]', '[{"hz":"我们沿着河边散步。","py":"Wǒmen yánzhe hébiān sànbù.","vi":"Chúng tôi dạo bước dọc bờ sông."},{"hz":"顺着这条路走，到头就是银行。","py":"Shùnzhe zhè tiáo lù zǒu, dào tóu jiù shì yínhuán.","vi":"Đi dọc con đường này, hết đường là ngân hàng."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-t-ō-n-g-g-u-ò-p-h-ư-ơ-n-g-t-i-ệ-n-k-ế-t-q-u-ả', 'HSK 5', 38, 'GIỚI TỪ 通过', 'Stōngguòphương tiệnkết quả', 'bongu', 'Giới từ 通过 — điểm ngữ pháp HSK 5.', '[["Chủ ngữ","key"],["通过","key"],["Phương tiện","key"],["V + kết quả","key"]]', '["Người Việt hay dùng 用 thay 通过: ","用练习提高水平"," là dịch thô, trang trọng phải是 通过练习提高水平。"]', '[{"hz":"他通过考试拿到了证书。","py":"Tā tōngguò kǎoshì ná dào le zhèngshū.","vi":"Anh ấy qua kỳ thi đã nhận được chứng chỉ."},{"hz":"我们通过网络学到了很多。","py":"Wǒmen tōngguò wǎngluò xué dào le hěn duō.","vi":"Chúng tôi qua mạng học được nhiều thứ."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-y-ó-u-y-ú-n-g-u-y-ê-n-n-h-â-n-k-ế-t-q-u-ả', 'HSK 5', 39, 'GIỚI TỪ 由于', 'yóuyúnguyên nhânkết quả', 'bongu', 'Giới từ 由于 — điểm ngữ pháp HSK 5.', '[["由于","key"],["Nguyên nhân (trang trọng)","key"],["Kết quả","key"]]', '["Người Việt hay dùng 由于 cho văn nói đời thường: ","由于他饿了"," hàng ngày nói là quá trang trọng — khẩu ngữ用 因为。"]', '[{"hz":"由于天气原因，比赛推迟了。","py":"Yóuyú tiānqì yuányīn, bǐsài tuīchí le.","vi":"Do lý do thời tiết, trận đấu bị hoãn."},{"hz":"由于准备充分，他顺利通过了考试。","py":"Yóuyú zhǔnbèi chōngfèn, tā shùnlì tōngguò le kǎoshì.","vi":"Do chuẩn bị chu đáo nên anh ấy vượt qua kỳ thi thuận lợi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-d-ā-n-g-d-e-s-h-í-h-o-u-S-+-V', 'HSK 5', 40, 'CẤU TRÚC 当……的时候', 'dāngde shíhouS+V', 'bongu', 'Cấu trúc 当……的时候 — điểm ngữ pháp HSK 5.', '[["当","key"],["……的时候","key"],["Chủ ngữ + V","key"]]', '["Người Việt hay dùng 当 một mình thiếu 的时候: ","当我在中国"," dừng ở đó là thiếu, phải是 当我在中国的时候。"]', '[{"hz":"当我遇到困难的时候，朋友总是帮助我。","py":"Dāng wǒ yùdào kùnnan de shíhou, péngyou zǒngshì bāngzhù wǒ.","vi":"Khi tôi gặp khó khăn, bạn bè luôn giúp tôi."},{"hz":"当他听到这个消息，激动得说不出话来。","py":"Dāng tā tīngdào zhège xiāoxi, jīdòng de shuō bu chū huà lái.","vi":"Khi nghe tin này, anh ấy xúc động đến không nói nổi lời."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-z-à-i-z-h-ō-n-g-/-x-i-à-/-f-ā-n-g-m-i-à-n-X', 'HSK 5', 41, 'CẤU TRÚC 在……中/下/方面', 'zàizhōng/xià/fāngmiànX', 'bongu', 'Cấu trúc 在……中/下/方面 — điểm ngữ pháp HSK 5.', '[["在","key"],["……中/下/方面","key"],["V/Adj","key"]]', '["Người Việt hay đảo trật tự: ","在老师的下帮助"," là sai, phải是 在老师的帮助下。"]', '[{"hz":"在老师的帮助下，我的汉语进步很快。","py":"Zài lǎoshī de bāngzhù xià, wǒ de Hànyǔ jìnbù hěn kuài.","vi":"Nhờ thầy giúp đỡ, tiếng Trung tôi tiến bộ nhanh."},{"hz":"在工作方面，他经验丰富。","py":"Zài gōngzuò fāngmiàn, tā jīngyàn fēngfù.","vi":"Về công việc, anh ấy giàu kinh nghiệm."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-d-u-ì-đ-ố-i-t-ư-ợ-n-g-j-ì-n-x-í-n-g-V-k-é-p', 'HSK 5', 42, 'CẤU TRÚC 对……进行+V', 'duìđối tượngjìnxíngV kép', 'hutu', 'Cấu trúc 对……进行+v — điểm ngữ pháp HSK 5.', '[["对","key"],["Đối tượng","key"],["进行","key"],["Động từ danh hóa (讨论/研究…)","key"]]', '["Người Việt hay 进行 với động từ đơn: ","对他进行看"," là sai — 进行 chỉ đi với động từ danh hóa: 进行讨论、进行研究。"]', '[{"hz":"老师对这个问题进行了详细的分析。","py":"Lǎoshī duì zhège wèntí jìnxíng le xiángxì de fēnxī.","vi":"Thầy phân tích chi tiết vấn đề này."},{"hz":"我们对计划进行了修改。","py":"Wǒmen duì jìhuà jìnxíng le xiūgǎi.","vi":"Chúng tôi đã chỉnh sửa kế hoạch."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-A-y-ó-u-c-á-c-p-h-ầ-n-z-ǔ-c-h-é-n-g', 'HSK 5', 43, 'CẤU TRÚC 由……组成', 'Ayóucác phầnzǔchéng', 'hutu', 'Cấu trúc 由……组成 — điểm ngữ pháp HSK 5.', '[["A","key"],["由","key"],["B (các phần)","key"],["组成","key"]]', '["Người Việt hay dùng 被 thay 由: ","水被氢和氧组成"," là sai — phải là 水由氢和氧组成。"]', '[{"hz":"我们班由二十个学生组成。","py":"Wǒmen bān yóu èrshí ge xuésheng zǔchéng.","vi":"Lớp chúng tôi gồm hai mươi học sinh."},{"hz":"这个小组由五个人组成。","py":"Zhège xiǎozǔ yóu wǔ ge rén zǔchéng.","vi":"Nhóm này gồm năm người."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-y-ǐ-A-w-é-i-z-h-ǔ', 'HSK 5', 44, 'CẤU TRÚC 以……为主', 'yǐAwéizhǔ', 'hutu', 'Cấu trúc 以……为主 — điểm ngữ pháp HSK 5.', '[["以","key"],["A","key"],["为主","key"]]', '["Người Việt hay viết sai 是/为: ","菜单以川菜是主"," là sai — phải是 菜单以川菜为主。"]', '[{"hz":"这家餐厅的菜以辣为主。","py":"Zhè jiā cāntīng de cài yǐ là wéizhǔ.","vi":"Món của nhà hàng này chủ yếu là cay."},{"hz":"课程内容以口语为主。","py":"Kèchéng nèiróng yǐ kǒuyǔ wéizhǔ.","vi":"Nội dung khóa học chủ yếu là nói."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-c-ó-n-g-c-h-ū-f-ā-ẩ-n-d-ụ-đ-ư-ợ-c', 'HSK 5', 45, 'CẤU TRÚC 从……出发', 'cóngchūfā(ẩn dụ được)', 'hutu', 'Cấu trúc 从……出发 — điểm ngữ pháp HSK 5.', '[["从","key"],["……出发","key"],["(nghĩa đen hoặc ẩn dụ)","key"]]', '["Người Việt hay bỏ 出: ","从实际发"," là thiếu — phải是 从实际出发。"]', '[{"hz":"我们从北京出发去上海。","py":"Wǒmen cóng Běijīng chūfā qù Shànghǎi.","vi":"Chúng tôi xuất phát từ Bắc Kinh đi Thượng Hải."},{"hz":"大家应该从实际出发考虑问题。","py":"Dàjiā yīnggāi cóng shíjì chūfā kǎolǜ wèntí.","vi":"Mọi người nên xuất phát từ thực tế để xem xét vấn đề."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-j-i-ù-é-r-y-á-n-n-h-ậ-n-x-é-t', 'HSK 5', 46, 'CẤU TRÚC 就……而言', 'jiùéryánnhận xét', 'hutu', 'Cấu trúc 就……而言 — điểm ngữ pháp HSK 5.', '[["就","key"],["……而言","key"],["Nhận xét","key"]]', '["Người Việt hay dùng 就……而言 trong văn nói: ","就这个话题而言"," rất trang trọng — nói chuyện hằng ngày用 对……来说。"]', '[{"hz":"就价格而言，这个方案比较合理。","py":"Jiù jiàgé éryán, zhège fāng\u0027àn bǐjiào hélǐ.","vi":"Xét về giá, phương án này khá hợp lý."},{"hz":"就我而言，在哪儿工作都行。","py":"Jiù wǒ éryán, zài nǎr gōngzuò dōu xíng.","vi":"Đối với riêng tôi, làm việc ở đâu cũng được."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-z-à-i-j-ī-c-h-ǔ-s-h-a-n-g-V', 'HSK 5', 47, 'CẤU TRÚC 在……的基础上', 'zàijīchǔshangV', 'hutu', 'Cấu trúc 在……的基础上 — điểm ngữ pháp HSK 5.', '[["在","key"],["……的基础","key"],["上","key"],["Động từ","key"]]', '["Người Việt hay quên 上: ","在这个基础"," là câu dở, phải是 在这个基础上。"]', '[{"hz":"我们在原有计划的基础上做了修改。","py":"Wǒmen zài yuányǒu jìhuà de jīchǔ shang zuò le xiūgǎi.","vi":"Chúng tôi chỉnh sửa trên cơ sở kế hoạch cũ."},{"hz":"在学习的基础上，他开始实践。","py":"Zài xuéxí de jīchǔ shang, tā kāishǐ shíjiàn.","vi":"Trên cơ sở học tập, anh ấy bắt đầu thực hành."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-A-s-h-ò-u-B-y-ǐ-n-g-x-i-ǎ-n-g', 'HSK 5', 48, 'CẤU TRÚC 受……影响', 'AshòuByǐngxiǎng', 'hutu', 'Cấu trúc 受……影响 — điểm ngữ pháp HSK 5.', '[["A","key"],["受","key"],["B","key"],["影响","key"]]', '["Người Việt hay dùng 被 cho văn viết: ","被环境影响"," không sai nhưng thiếu trang trọng — văn viết用 受环境影响。"]', '[{"hz":"他受父亲的影响，从小喜欢画画。","py":"Tā shòu fùqīn de yǐngxiǎng, cóngxiǎo xǐhuan huà huà.","vi":"Chịu ảnh hưởng của bố, anh ấy thích vẽ từ nhỏ."},{"hz":"这种说法受到很多年轻人的欢迎。","py":"Zhè zhǒng shuōfǎ shòudào hěn duō niánqīngrén de huānyíng.","vi":"Cách nói này được nhiều bạn trẻ ưa chuộng."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-S-b-ǎ-A-d-à-n-g-z-u-ò-/-s-h-ì-w-é-i-B', 'HSK 5', 49, 'CẤU TRÚC 把……当作/视为', 'SbǎAdàngzuò/shìwéiB', 'hutu', 'Cấu trúc 把……当作/视为 — điểm ngữ pháp HSK 5.', '[["Chủ ngữ","key"],["把","key"],["A","key"],["当作/视为","key"],["B","key"]]', '["Người Việt hay bỏ 把: ","我当他是朋友"," nghĩa khác (\"tôi tưởng anh ấy là bạn\")\u003b \"xem như\" phải是 我把他当作朋友。"]', '[{"hz":"我把他当作自己的哥哥。","py":"Wǒ bǎ tā dàngzuò zìjǐ de gēge.","vi":"Tôi xem anh ấy như anh trai của mình."},{"hz":"他把这里视为第二个家。","py":"Tā bǎ zhèlǐ shìwéi dì\u0027èr ge jiā.","vi":"Anh ấy xem nơi này như gia đình thứ hai."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-k-à-n-l-á-i-/-k-à-n-q-ǐ-l-á-i-s-u-y-đ-o-á-n', 'HSK 5', 50, '看来/看起来（suy đoán）', 'kànlái/kànqǐláisuy đoán', 'bi', '看来/看起来（suy đoán） — điểm ngữ pháp HSK 5.', '[["看来/看起来","key"],["Suy đoán/nhận xét","key"]]', '["Người Việt hay trộn hai từ: ","看起来要下雨了"," khi rút kết luận từ dữ kiện phải是 看来要下雨了；看起来 chỉ cảm nhận bề ngoài."]', '[{"hz":"天阴了，看来要下雨了。","py":"Tiān yīn le, kànlái yào xià yǔ le.","vi":"Trời âm u, chắc chắn là sắp mưa rồi."},{"hz":"他看起来很高兴。","py":"Tā kànqǐlái hěn gāoxìng.","vi":"Trông anh ấy rất vui."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-V-x-i-à-q-u-t-i-ế-p-t-ụ-c', 'HSK 5', 51, 'BỔ NGỮ HƯỚNG V下去（tiếp tục）', 'Vxiàqu(tiếp tục)', 'bi', 'Bổ ngữ hướng v下去（tiếp tục） — điểm ngữ pháp HSK 5.', '[["Động từ","key"],["下去","key"],["(tiếp tục)","key"]]', '["Người Việt hay đảo thứ tự với 继续: ","说继续下去"," là sai — phải là 继续说 hoặc 说下去。"]', '[{"hz":"你说下去，我在听。","py":"Nǐ shuō xiàqu, wǒ zài tīng.","vi":"Cậu nói tiếp đi, tôi đang nghe."},{"hz":"照这样下去，我们永远完不成。","py":"Zhào zhèyàng xiàqu, wǒmen yǒngyuǎn wánbuchéng.","vi":"Cứ thế này tiếp tục thì chúng ta mãi không xong."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-V-+-c-h-u-l-á-i-n-h-ậ-n-r-a', 'HSK 5', 52, 'BỔ NGỮ HƯỚNG V出来（nhận ra）', 'V+chulái(nhận ra)', 'bi', 'Bổ ngữ hướng v出来（nhận ra） — điểm ngữ pháp HSK 5.', '[["听/看/闻 + 出来","key"],["(nhận ra)","key"]]', '["Người Việt hay chèn giữa động từ và 补语: ","我听懂出来"," là sai — phải是 我听出来（了）。"]', '[{"hz":"我听出来了，他是南方人。","py":"Wǒ tīng chūlái le, tā shì nánfāng rén.","vi":"Tôi nghe ra rồi, anh ấy là người phương Nam."},{"hz":"我看出来他不太高兴。","py":"Wǒ kàn chūlái tā bú tài gāoxìng.","vi":"Tôi nhìn ra là anh ấy không vui lắm."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-V-b-ù-q-ǐ-n-ă-n-g-l-ự-c', 'HSK 5', 53, 'BỔ NGỮ KHẢ NĂNG V不起', 'Vbùqǐ(năng lực)', 'bi', 'Bổ ngữ khả năng v不起 — điểm ngữ pháp HSK 5.', '[["Động từ","key"],["不起","key"],["(không chịu nổi chi phí)","key"]]', '["Người Việt hay thay bằng 不能: ","我不能买"," là \"không được mua\"\u003b \"không đủ tiền\" phải是 买不起。"]', '[{"hz":"这双鞋太贵了，我买不起。","py":"Zhè shuāng xié tài guì le, wǒ mǎi bu qǐ.","vi":"Đôi giày này đắt quá, tôi không mua nổi."},{"hz":"房租太贵，我们租不起。","py":"Fángzū tài guì, wǒmen zū bu qǐ.","vi":"Tiền nhà đắt quá, chúng tôi không thuê nổi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-V-l-á-i-d-e-j-í-/-l-á-i-b-u-j-í', 'HSK 5', 54, 'BỔ NGỮ KHẢ NĂNG 来得及/来不及', 'Vláidejí/láibují', 'bi', 'Bổ ngữ khả năng 来得及/来不及 — điểm ngữ pháp HSK 5.', '[["Động từ","key"],["来得及/来不及","key"]]', '["Người Việt hay nói thừa: ","没有时间来不及"," là lộn xộn — một mình 来不及了 đã đủ nghĩa \"không kịp rồi\"。"]', '[{"hz":"快走吧，不然来不及了。","py":"Kuài zǒu ba, bùrán láibují le.","vi":"Đi nhanh đi, không thì không kịp."},{"hz":"别着急，时间还来得及。","py":"Bié zháojí, shíjiān hái láidejí.","vi":"Đừng vội, thời gian còn kịp."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-V-d-e-/-b-ù-d-ò-n-g-s-ứ-c', 'HSK 5', 55, 'BỔ NGỮ KHẢ NĂNG V得/不动', 'Vde/bùdòng(sức)', 'bi', 'Bổ ngữ khả năng v得/不动 — điểm ngữ pháp HSK 5.', '[["Động từ","key"],["得/不动","key"],["(sức chịu nổi)","key"]]', '["Người Việt hay dùng 不能: ","我不能走了"," nghĩa khác\u003b \"hết sức đi nổi\" phải是 我走不动了。"]', '[{"hz":"爬了三个小时，我实在走不动了。","py":"Pá le sān ge xiǎoshí, wǒ shízài zǒu bu dòng le.","vi":"Leo ba tiếng, tôi thực sự không bước nổi nữa."},{"hz":"这些箱子太重，我搬不动。","py":"Zhèxiē xiāngzi tài zhòng, wǒ bān bu dòng.","vi":"Những thùng này nặng quá, tôi không khiêng nổi."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-V-g-è-b-ù-t-í-n-g', 'HSK 5', 56, 'CẤU TRÚC V个不停', 'Vgèbùtíng', 'bi', 'Cấu trúc v个不停 — điểm ngữ pháp HSK 5.', '[["Động từ","key"],["个","key"],["不停","key"]]', '["Người Việt hay lặp 不停 hai lần: ","他不停地说话说个不停"," là thừa — 他说话说个不停 đã đủ."]', '[{"hz":"孩子们又唱又跳，闹个不停。","py":"Háizimen yòu chàng yòu tiào, nào ge bùtíng.","vi":"Bọn trẻ lại hát lại nhảy, náo không ngừng."},{"hz":"他一进门就说个不停。","py":"Tā yì jìnmén jiù shuō ge bùtíng.","vi":"Anh ấy vừa bước vào cửa là nói không ngừng."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-y-ì-t-i-ā-n-b-ǐ-y-ì-t-i-ā-n-A-d-j-/-V', 'HSK 5', 57, 'CẤU TRÚC 一天比一天', 'yì tiān bǐ yì tiānAdj/V', 'hutu', 'Cấu trúc 一天比一天 — điểm ngữ pháp HSK 5.', '[["一天比一天","key"],["Tính từ/Động từ","key"]]', '["Người Việt hay dùng 越来越 thay tùy tiện: ","越来越一天比一天好"," là trộn hai mẫu — chọn một: 一天比一天好 hoặc 越来越好。"]', '[{"hz":"他的汉语一天比一天好。","py":"Tā de Hànyǔ yì tiān bǐ yì tiān hǎo.","vi":"Tiếng Trung của anh ấy mỗi ngày một tốt hơn."},{"hz":"天气一天比一天冷了。","py":"Tiānqì yì tiān bǐ yì tiān lěng le.","vi":"Thời tiết mỗi ngày một lạnh."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-V-l-á-i-V-q-ù', 'HSK 5', 58, 'CẤU TRÚC A来A去', 'VláiVqù', 'hutu', 'Cấu trúc a来a去 — điểm ngữ pháp HSK 5.', '[["Động từ","key"],["来","key"],["Động từ","key"],["去","key"]]', '["Người Việt hay chèn tân ngữ vào giữa: ","想这个问题来去"," là sai — phải là 想来想去 hoặc 想这个问题。"]', '[{"hz":"他想来想去，还是决定不去。","py":"Tā xiǎng lái xiǎng qù, háishì juédìng bú qù.","vi":"Anh ấy suy đi nghĩ lại, cuối cùng vẫn quyết định không đi."},{"hz":"孩子在院子里跑来跑去。","py":"Háizi zài yuànzi lǐ pǎo lái pǎo qù.","vi":"Con trẻ chạy nhảy khắp sân."}]');
INSERT OR REPLACE INTO content_grammars (id, level, ord, title, hz, topic, def, formula, pitfall, ex) VALUES ('hsk5-M-+-M-đ-ố-i-t-ư-ợ-n-g', 'HSK 5', 59, 'LƯỢNG TỪ CHỒNG（一个个/一座座）', 'M+Mđối tượng', 'bongu', 'Lượng từ chồng（一个个/一座座） — điểm ngữ pháp HSK 5.', '[["Lượng từ chồng","key"],["Đối tượng","key"]]', '["Người Việt hay chồng sai dạng: ","一一个个"," là sai — chỉ cần 一个个 hoặc 一座座。"]', '[{"hz":"一个个问题都被解决了。","py":"Yí ge ge wèntí dōu bèi jiějué le.","vi":"Từng vấn đề một đều được giải quyết."},{"hz":"路边种着一棵棵大树。","py":"Lùbiān zhòngzhe yì kē kē dà shù.","vi":"Dọc đường trồng từng hàng cây to."}]');
